insert into public.learning_paths (id, slug, code, title, subtitle, description, icon, sort) values (md5('path:fundamentos-vocais')::uuid, 'fundamentos-vocais', 'A', 'Fundamentos vocais', 'Postura, respiração, emissão e cuidado com a voz', 'A base técnica de quem canta: um corpo disponível, ar bem administrado, som livre, texto claro e uma rotina segura de aquecimento. Cada aula traz prática guiada e critérios para avançar.', 'mic-vocal', 0) on conflict (slug) do update set code = excluded.code, title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, icon = excluded.icon, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:postura-e-relaxamento')::uuid, (select id from public.learning_paths where slug = 'fundamentos-vocais'), 'postura-e-relaxamento', 'Postura e relaxamento', 'Um corpo alinhado e sem tensões desnecessárias deixa o ar e o som circularem.', 0, 1, 15, '{"objetivo":"Encontrar uma postura alinhada e relaxada, de pé e sentado, que favoreça a respiração e a emissão, e reconhecer as tensões mais comuns ao cantar.","gancho":"Antes da primeira nota, quem canta é o corpo. Vamos descobrir como deixá-lo pronto, sem esforço e sem rigidez.","etapas":[{"titulo":"Sua voz usa o corpo inteiro","tipo":"descobrir","blocos":[{"type":"p","text":"O som nasce na garganta, mas quem sustenta a voz é o corpo todo: pés, coluna, ombros e mandíbula."},{"type":"callout","icon":"musica","title":"Pense num violão","text":"As cordas fazem o som, mas é a caixa de madeira que o deixa bonito. Seu corpo é a caixa da sua voz: se estiver torto ou travado, o som sai apertado."},{"type":"check","question":"Se os ombros sobem e o pescoço trava ao cantar, o que tende a acontecer com o som?","options":["Fica mais apertado e cansa mais rápido","Fica mais forte e bonito","Não muda nada"],"answer":0,"explain":"Tensão no corpo vira tensão no som. Por isso a postura vem antes de qualquer nota."}]},{"titulo":"Alto e solto","tipo":"descobrir","blocos":[{"type":"illustration","name":"postura-comparada","caption":"Orelha, ombro, quadril e tornozelo na mesma linha."},{"type":"callout","icon":"ideia","title":"A imagem do fio","text":"Imagine um fio puxando o topo da cabeça para cima, enquanto ombros e braços pesam para baixo. Alto e solto ao mesmo tempo."},{"type":"trueFalse","items":[{"statement":"Boa postura é ficar duro, como um soldado.","answer":false,"explain":"Postura não é rigidez. Se precisa de força para mantê-la, está rígida demais."},{"statement":"Para notas agudas, devo erguer o queixo.","answer":false,"explain":"Erguer o queixo estica o pescoço e aperta a laringe. O queixo fica paralelo ao chão."},{"statement":"Joelhos destravados evitam tensão nas costas.","answer":true,"explain":"Joelhos travados endurecem o corpo e podem até causar tontura em pé."}]}]},{"titulo":"Encontre o seu centro","tipo":"experimentar","blocos":[{"type":"p","text":"Fique de pé, de preferência na frente de um espelho, e siga o cronômetro."},{"type":"timer","instruction":"Feche os olhos e balance devagar para frente e para trás até sentir o peso dividido entre calcanhares e dedos.","seconds":20},{"type":"checklist","title":"Confira no espelho","items":["Pés na largura do quadril","Joelhos destravados","Ombros soltos, longe das orelhas","Queixo paralelo ao chão","Peito aberto, barriga livre"]}]},{"titulo":"Solte ombros e mandíbula","tipo":"experimentar","blocos":[{"type":"timer","instruction":"Suba os ombros até as orelhas ao inspirar e deixe-os cair de uma vez ao soltar o ar. Repita.","seconds":6,"reps":3},{"type":"illustration","name":"mandibula","caption":"A mandíbula cai por gravidade, sem empurrar."},{"type":"timer","instruction":"Com as pontas dos dedos, massageie as bochechas perto da articulação da mandíbula, com a boca entreaberta.","seconds":20},{"type":"reveal","prompt":"Coloque a mão nos ombros e inspire fundo. Eles subiram?","answer":"Se subiram, o ar foi para cima do peito. Tente de novo pensando em encher a cintura e as costelas: os ombros ficam parados."}]},{"titulo":"O “hum” que vibra","tipo":"ouvir","blocos":[{"type":"p","text":"Agora una corpo e som. Com a boca fechada e os dentes separados por dentro, faça um “hum” confortável."},{"type":"singAlong","instruction":"Ouça a nota e faça “hum” sustentando por 3 segundos. Sinta os lábios fazendo cócegas.","note":"A3","seconds":3},{"type":"callout","icon":"maos","title":"Teste do toque","text":"Encoste os dedos nos lábios enquanto faz o “hum”. Sentiu vibrar? É sinal de som livre, sem apertar a garganta."}]},{"titulo":"E sentado, como fica?","tipo":"aplicar","blocos":[{"type":"illustration","name":"postura-sentada"},{"type":"check","question":"No ensaio sentado, qual é a melhor posição?","options":["Na frente da cadeira, pés no chão, costas sem encostar","Recostado(a), pernas cruzadas","Inclinado(a) para frente, apoiado nos joelhos"],"answer":0,"explain":"Na frente da cadeira o abdômen fica livre para a respiração, e você mantém o mesmo alinhamento de quando está de pé."},{"type":"toolLink","tool":"gravador","label":"Desafio: grave uma frase “largado(a)” e outra alinhado(a). Ouça a diferença."}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada tensão à sua correção.","pairs":[{"left":"Ombros sobem ao inspirar","right":"Encher cintura e costelas"},{"left":"Queixo para cima no agudo","right":"Queixo paralelo ao chão"},{"left":"Joelhos travados","right":"Joelhos destravados"},{"left":"Dentes apertados","right":"Mandíbula solta"}]}]}],"pratiqueSozinho":{"passos":["Antes de cada estudo ou ensaio, faça o checklist de postura (1 minuto).","Cante uma frase de um hino conhecido observando-se no espelho: queixo, ombros e mandíbula ficaram soltos?","Repita a mesma frase sentado(a)."],"minutos":5,"frequencia":"Todos os dias, antes de cantar"},"errosComuns":[{"erro":"Erguer o queixo para alcançar notas agudas.","correcao":"Mantenha o queixo paralelo ao chão. A nota aguda não está “em cima”; erguer a cabeça tensiona a laringe."},{"erro":"Estufar o peito e travar a barriga.","correcao":"O peito fica aberto, mas o abdômen precisa estar livre para se mover com a respiração."},{"erro":"Travar os joelhos durante músicas longas.","correcao":"Joelhos destravados evitam tensão nas costas e até tontura em pé por muito tempo."},{"erro":"Ombros que sobem ao inspirar.","correcao":"A inspiração acontece embaixo (costelas e abdômen). Pratique inspirar com as mãos nos ombros para perceber."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo).","Se sentir tontura durante alongamentos ou respirações, sente-se e volte à respiração normal."],"criterioAvanco":"Acertar pelo menos 70% da avaliação desta aula e conseguir cantar uma frase mantendo ombros, pescoço e mandíbula soltos (confira gravando-se ou com o professor)."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'postura-relaxamento' from public.lessons where slug = 'postura-e-relaxamento' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:postura-checklist')::uuid, 'postura-checklist', (select id from public.lessons where slug = 'postura-e-relaxamento'), 'Checklist de postura', 'Fique em frente a um espelho e confira cada item, primeiro de pé e depois sentado(a).', 'self_check', '{"minutes":3,"items":["Pés na largura do quadril e peso distribuído","Joelhos destravados","Ombros soltos, sem subir ao inspirar","Queixo paralelo ao chão","Mandíbula solta no “hum”","Mesmo alinhamento quando sentado(a)"]}'::jsonb, 'postura-relaxamento', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:postura-avaliacao')::uuid, 'postura-avaliacao', (select id from public.lessons where slug = 'postura-e-relaxamento'), 'Avaliação: postura para cantar', 'Responda com base no que você estudou na aula.', 'quiz', '{"questions":[{"q":"Qual imagem ajuda a encontrar uma postura alinhada sem rigidez?","options":["Um fio puxando o topo da cabeça para cima, com ombros pesando para baixo","Peito estufado e barriga travada","Queixo erguido para o som ir “para cima”","Joelhos esticados ao máximo"],"answer":0,"explanation":"“Alto e solto”: a coluna se alonga enquanto ombros e braços ficam relaxados."},{"q":"Por que não se deve erguer o queixo para cantar notas agudas?","options":["Porque tensiona o pescoço e a laringe","Porque a nota fica mais grave","Porque o som fica mais alto","Não há problema em erguer o queixo"],"answer":0,"explanation":"Erguer a cabeça estica a musculatura do pescoço e dificulta a emissão livre."},{"q":"Ao cantar sentado(a), qual é a melhor posição?","options":["Na parte da frente da cadeira, pés no chão e coluna sem encostar","Recostado(a) no encosto, pernas cruzadas","Na ponta da cadeira com os pés para trás e o corpo inclinado para frente","Qualquer posição, a postura só importa em pé"],"answer":0},{"q":"O que acontece com os ombros numa inspiração eficiente?","options":["Permanecem soltos; a expansão acontece nas costelas e no abdômen","Sobem para encher mais o pulmão","Vão para frente","Ficam contraídos para dar apoio"],"answer":0},{"q":"Para que serve o “hum” de boca fechada nesta aula?","options":["Sentir a vibração do som sem esforço, com a mandíbula solta","Cantar o mais forte possível","Testar a nota mais aguda","Descansar a voz sem produzir som"],"answer":0}]}'::jsonb, 'postura-relaxamento', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:aquecimento-vocal')::uuid, (select id from public.learning_paths where slug = 'fundamentos-vocais'), 'aquecimento-vocal', 'Aquecimento e desaquecimento vocal', 'Uma rotina curta e progressiva prepara a voz para cantar com segurança.', 1, 1, 20, '{"objetivo":"Conhecer e executar uma rotina de aquecimento de 8 a 10 minutos — corpo, respiração, vibração, deslizes e articulação — e um desaquecimento de 2 minutos após o ensaio.","gancho":"Nenhum atleta entra em campo sem aquecer. Em 10 minutos, você vai preparar a voz do jeito certo e sentir a diferença no ensaio.","etapas":[{"titulo":"Por que aquecer?","tipo":"descobrir","blocos":[{"type":"p","text":"As pregas vocais são um tecido delicado, coordenado por pequenos músculos. Como um atleta antes do jogo, quem canta prepara essa musculatura aos poucos."},{"type":"illustration","name":"aquecimento","caption":"Do suave ao intenso, do meio para as pontas."},{"type":"callout","icon":"ideia","title":"Três regras de ouro","text":"Do suave para o intenso. Da região média para as extremidades. Do som fechado (“hum”, “u”) para o aberto (“á”)."},{"type":"check","question":"Qual é o jeito mais seguro de começar o aquecimento?","options":["Na região média, com volume moderado","Pela nota mais aguda, para “abrir” a voz","Com o trecho mais difícil do repertório","Gritando um pouco para soltar"],"answer":0,"explain":"Começar no meio e suave prepara a musculatura sem sobrecarga. Agudos e volume vêm depois, aos poucos."}]},{"titulo":"Corpo e ar (2 minutos)","tipo":"experimentar","blocos":[{"type":"timer","instruction":"Incline a cabeça devagar para um lado e para o outro, role os ombros para trás e deixe a mandíbula cair solta.","seconds":60},{"type":"p","text":"Agora inspire pelo nariz, expandindo as costelas, e solte o ar num “sss” contínuo."},{"type":"breathing","inhale":4,"exhale":8,"rounds":4,"exhaleOn":"sss"},{"type":"tip","text":"Ficou fácil? Aos poucos, estique o “sss” para 12 tempos."}]},{"titulo":"O motorzinho dos lábios","tipo":"experimentar","blocos":[{"type":"callout","icon":"ideia","title":"Por que o “brrr” funciona","text":"A vibração de lábios cria uma leve resistência na saída do ar. Isso equilibra a pressão sobre as pregas vocais com pouco esforço. É ótima para começar o dia e para recuperar a voz depois do ensaio."},{"type":"audio","label":"Escala de cinco notas em Dó (vozes femininas)","notes":["C4","D4","E4","F4","G4","F4","E4","D4","C4"],"tempo":120},{"type":"audio","label":"Escala de cinco notas em Dó (vozes masculinas)","notes":["C3","D3","E3","F3","G3","F3","E3","D3","C3"],"tempo":120},{"type":"timer","instruction":"Faça “brrr” acompanhando a escala. Se os lábios travarem, apoie os dedos de leve nas bochechas. Não saiu? Use a vibração de língua: “trrr”.","seconds":30,"reps":2}]},{"titulo":"A sirene que sobe e desce","tipo":"experimentar","blocos":[{"type":"p","text":"Em “u”, deslize suavemente do grave ao agudo confortável e volte, como um elevador. Use o arpejo como guia."},{"type":"audio","label":"Arpejo para deslize (Dó–Mi–Sol–Mi–Dó)","notes":["C4","E4","G4","E4","C4"],"tempo":100},{"type":"timer","instruction":"Sirene em “u”: suba e desça bem suave, sem empurrar o topo.","seconds":8,"reps":3},{"type":"trueFalse","items":[{"statement":"Se o topo da sirene pesar, devo empurrar mais forte.","answer":false,"explain":"Pare antes do esforço. O aquecimento expande a voz aos poucos, sem empurrar."},{"statement":"Um bom aquecimento deixa a voz cansada.","answer":false,"explain":"Aquecimento não deve doer nem cansar. Se cansar, diminua o volume e a extensão."}]}]},{"titulo":"Vogais em cinco notas","tipo":"experimentar","blocos":[{"type":"p","text":"Cante Dó–Ré–Mi–Fá–Sol–Fá–Mi–Ré–Dó em “mi”, “mê”, “má”, “mô”, “mu”. A cada repetição, suba meio-tom, só enquanto estiver confortável."},{"type":"singAlong","instruction":"Comece pela primeira nota da escala: cante “mi” e sustente, suave.","note":"C4","seconds":3},{"type":"reveal","prompt":"Até onde subir a escala?","answer":"Até onde estiver confortável, sem esforço. Não existe uma nota certa para todos: cada voz tem seu limite, e ele pode mudar de um dia para o outro."}]},{"titulo":"Acorde a língua","tipo":"experimentar","blocos":[{"type":"p","text":"Para fechar: articulação. Trava-línguas e as consoantes do repertório do dia."},{"type":"timer","instruction":"Diga, articulando sem pressa: “O rato roeu a roupa do rei de Roma”. Depois, um pouco mais rápido.","seconds":20},{"type":"toolLink","tool":"aquecimento","label":"Abrir a rotina guiada: ela toca as notas e avança sozinha"}]},{"titulo":"Depois do ensaio: desaquecer","tipo":"aplicar","blocos":[{"type":"p","text":"O desaquecimento leva a voz de volta à fala. Após o ensaio, faça 1 minuto de “brrr” em deslizes descendentes e alguns bocejos-suspiros suaves, terminando na altura da sua fala."},{"type":"check","question":"Acabou o ensaio e a garganta parece “arranhando”. O que fazer?","options":["Deslizes descendentes em “brrr” e um gole de água","Pigarrear até limpar","Cantar as notas mais agudas para fechar","Sussurrar com força o resto da noite"],"answer":0,"explain":"Deslizes suaves ajudam a voz a se recuperar. Pigarrear e sussurrar forçado atritam as pregas vocais; prefira engolir em seco ou beber água."}]},{"titulo":"Monte a sua rotina","tipo":"checar","blocos":[{"type":"order","prompt":"Coloque as etapas do aquecimento na ordem.","items":["Corpo: pescoço, ombros e mandíbula","Respiração em “sss”","Vibração de lábios ou de língua","Sirene em “u”","Escala de cinco notas em vogais","Trava-línguas"]}]}],"pratiqueSozinho":{"passos":["Use a rotina guiada antes de cada estudo e antes do ensaio.","Depois de cantar, faça 1 minuto de vibração de lábios descendente e 3 suspiros suaves.","Registre o seu estudo em “Meu progresso” para manter a sequência de dias."],"minutos":10,"frequencia":"Todos os dias em que for cantar"},"errosComuns":[{"erro":"Começar pelas notas mais agudas e mais fortes.","correcao":"Comece na região média, com volume moderado, e expanda aos poucos."},{"erro":"Fazer a vibração de lábios com as bochechas tensas.","correcao":"Apoie levemente os dedos nas bochechas; o som deve sair contínuo, com pouco esforço."},{"erro":"Pular o desaquecimento depois do ensaio.","correcao":"Dois minutos de deslizes suaves ajudam a voz a se recuperar e voltar para a fala."},{"erro":"Achar que pigarrear limpa a voz.","correcao":"Pigarrear atrita as pregas vocais. Prefira engolir em seco ou tomar um gole de água."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo).","Aquecimento não deve doer nem cansar. Se cansar, diminua o volume e a extensão."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e completar a rotina guiada em 3 dias diferentes."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'aquecimento-vocal' from public.lessons where slug = 'aquecimento-vocal' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:aquecimento-rotina')::uuid, 'aquecimento-rotina', (select id from public.lessons where slug = 'aquecimento-vocal'), 'Rotina de aquecimento', 'Faça a rotina completa e avalie como cada etapa foi.', 'self_check', '{"minutes":10,"items":["Alongamentos sem dor","Respiração em “sss” por 8 tempos","Vibração de lábios contínua","Sirene sem empurrar o agudo","Escala de cinco notas em vogais","Desaquecimento após cantar"],"audio":{"notes":["C4","D4","E4","F4","G4","F4","E4","D4","C4"],"mode":"seq","tempo":120}}'::jsonb, 'aquecimento-vocal', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:aquecimento-avaliacao')::uuid, 'aquecimento-avaliacao', (select id from public.lessons where slug = 'aquecimento-vocal'), 'Avaliação: aquecimento seguro', 'Responda sobre os princípios do aquecimento vocal.', 'quiz', '{"questions":[{"q":"Qual é a ordem mais segura para aquecer a voz?","options":["Do suave para o intenso, da região média para as extremidades","Do agudo para o grave, sempre forte","Começar com o repertório mais difícil","Gritar um pouco para “abrir” a voz"],"answer":0},{"q":"Por que a vibração de lábios é um bom exercício inicial?","options":["Equilibra a pressão do ar sobre as pregas vocais com pouco esforço","Porque deixa a voz mais grave","Porque dispensa a respiração","Porque aumenta a extensão imediatamente"],"answer":0},{"q":"O que fazer em vez de pigarrear?","options":["Engolir em seco ou beber um gole de água","Pigarrear mais forte","Tossir","Sussurrar"],"answer":0,"explanation":"Sussurrar forçado e pigarrear também atritam as pregas vocais."},{"q":"Para que serve o desaquecimento?","options":["Levar a voz de volta para a fala e ajudar na recuperação","Treinar notas extremas","Substituir o aquecimento","Não tem utilidade"],"answer":0},{"q":"Na escala de cinco notas, até onde subir?","options":["Até onde estiver confortável, sem esforço","Sempre até a nota mais aguda possível","Exatamente uma oitava acima, para todos","Até a voz falhar"],"answer":0}]}'::jsonb, 'aquecimento-vocal', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:respiracao-e-fraseado')::uuid, (select id from public.learning_paths where slug = 'fundamentos-vocais'), 'respiracao-e-fraseado', 'Respiração e fraseado', 'Administrar o ar com conforto e planejar onde respirar em cada frase.', 2, 1, 20, '{"objetivo":"Inspirar sem tensão, administrar a saída do ar para sustentar frases e planejar as respirações de uma música de acordo com o texto e a melodia.","gancho":"Já ficou sem ar no meio de um hino? O segredo não é ter mais fôlego: é saber onde o ar entra e onde respirar.","etapas":[{"titulo":"Onde o ar realmente entra","tipo":"descobrir","blocos":[{"type":"p","text":"Cantar pede mais ar e mais controle do que falar. Na inspiração, o diafragma desce e as costelas se expandem. Por isso sentimos a cintura e as costas se abrirem."},{"type":"illustration","name":"respiracao","caption":"O diafragma desce; costelas e cintura se abrem."},{"type":"check","question":"Ao inspirar para cantar, onde você deve sentir a expansão?","options":["Cintura, costelas laterais e costas","Nos ombros, que sobem","Só no peito alto","Na garganta"],"answer":0,"explain":"O diafragma desce e as costelas se abrem para os lados e para trás. Ombros que sobem indicam uma respiração alta e tensa."}]},{"titulo":"Sinta com as mãos","tipo":"experimentar","blocos":[{"type":"p","text":"Mãos na cintura, polegares para trás. Inspire e sinta as mãos se afastarem, sem subir os ombros."},{"type":"breathing","inhale":4,"exhale":4,"rounds":3},{"type":"list","items":["Pelo nariz quando houver tempo; pela boca nas respirações rápidas, sem barulho.","Não encha ao máximo: ar demais gera tensão. Inspire o necessário para a frase."]}]},{"titulo":"Solte o ar aos poucos","tipo":"experimentar","blocos":[{"type":"p","text":"Agora o desafio: soltar o ar de forma constante, sem prender e sem empurrar. Mantenha as costelas “abertas” por mais tempo, em vez de esvaziar de uma vez."},{"type":"breathing","inhale":4,"exhale":8,"rounds":3,"exhaleOn":"sss"},{"type":"tip","title":"Próximo nível","text":"Conseguiu 8? Tente 12 e depois 16 tempos. Troque o “sss” por “fff” e depois por “vvv” (com som), com a mesma constância."},{"type":"toolLink","tool":"metronomo","label":"Abrir o metrônomo a 60 bpm (um tempo por segundo)"}]},{"titulo":"Uma frase, uma respiração","tipo":"ouvir","blocos":[{"type":"p","text":"Ouça e cante esta frase em “lu”, respirando só no início. Se faltar ar, cante mais suave, não mais forte."},{"type":"audio","label":"Frase para sustentar (vozes femininas)","notes":["G4","G4","A4","G4","F4","E4","D4","C4"],"tempo":66},{"type":"audio","label":"Frase para sustentar (vozes masculinas)","notes":["G3","G3","A3","G3","F3","E3","D3","C3"],"tempo":66},{"type":"trueFalse","items":[{"statement":"Quanto mais ar eu puxar, melhor vou cantar.","answer":false,"explain":"Ar demais gera tensão e dificulta o controle. Inspire o necessário para a frase."},{"statement":"Prender o ar antes de cantar dá mais apoio.","answer":false,"explain":"A inspiração deve virar som sem uma pausa travada na garganta."},{"statement":"Começar a frase com o mesmo fluxo de ar do final ajuda a economizar.","answer":true,"explain":"Quem gasta tudo nas primeiras notas fica sem ar no fim. Fluxo constante do início ao fim."}]}]},{"titulo":"Onde respirar?","tipo":"descobrir","blocos":[{"type":"illustration","name":"frase-respiracao","caption":"O “V” marca o lugar da respiração."},{"type":"p","text":"Fraseado é conduzir a frase do início ao fim. Respirar no meio de uma palavra ou de uma ideia quebra o sentido do texto. Por isso marcamos com vírgula ou “V” onde respirar: nas pausas, nas vírgulas do texto e no fim das frases."},{"type":"check","question":"Qual destas respirações quebra o sentido do texto?","options":["No meio da palavra “Se-nhor”","Na vírgula do texto","Na pausa entre duas frases","No fim da estrofe"],"answer":0,"explain":"Respirar no meio de uma palavra corta a mensagem. Pausas, vírgulas e finais de frase são os lugares naturais."}]},{"titulo":"Respirar em equipe","tipo":"descobrir","blocos":[{"type":"callout","icon":"coracao","title":"Respiração escalonada","text":"Em frases muito longas, cada pessoa do naipe respira num lugar diferente, discretamente. Assim o som do naipe nunca para. O regente indica quando usar."},{"type":"reveal","prompt":"Numa frase longa e sem pausa, o que aconteceria se o naipe inteiro respirasse no mesmo lugar?","answer":"O som pararia de repente, abrindo um buraco na música. Respirando em momentos diferentes, cada um sai e volta discretamente e o som continua."}]},{"titulo":"Sua vez: marque um hino","tipo":"aplicar","blocos":[{"type":"p","text":"Escolha um hino conhecido, escreva a letra de uma estrofe e marque com “V” onde vai respirar."},{"type":"checklist","title":"Confira suas marcações","items":["Nenhum “V” no meio de palavra","Respirações em vírgulas, pausas ou fins de frase","Nenhuma ideia do texto cortada ao meio","Cantei a estrofe respeitando as marcações"]},{"type":"toolLink","tool":"gravador","label":"Grave a estrofe: alguma respiração cortou uma palavra?"}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada problema à sua correção.","pairs":[{"left":"Ombros sobem ao inspirar","right":"Expandir cintura e costelas"},{"left":"Ar acaba nas primeiras notas","right":"Fluxo constante, costelas abertas"},{"left":"Inspiração barulhenta","right":"Garganta aberta, como num bocejo discreto"},{"left":"Respirar no meio da palavra","right":"Planejar as respirações no texto"}]}]}],"pratiqueSozinho":{"passos":["3 séries de “sss” por 12 a 16 tempos.","Cante a estrofe que você marcou respeitando as respirações planejadas.","Grave-se e confira: alguma respiração cortou uma palavra ou uma ideia?"],"minutos":8,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Inspirar ruidosamente ou com os ombros.","correcao":"Abra a garganta como num bocejo discreto e deixe o ar entrar embaixo."},{"erro":"Gastar todo o ar nas primeiras notas.","correcao":"Comece a frase com o mesmo fluxo que pretende ter no final; pense em “economizar” as costelas abertas."},{"erro":"Prender o ar antes de cantar.","correcao":"A inspiração deve se transformar em som sem pausa travada na garganta."},{"erro":"Respirar no meio de uma palavra.","correcao":"Planeje as respirações no texto antes de cantar."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo).","Não prenda a respiração em exercícios longos. Se ficar tonto(a), pare e respire normalmente."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e sustentar um “sss” constante por 12 tempos a 60 bpm."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'respiracao-fraseado' from public.lessons where slug = 'respiracao-e-fraseado' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:respiracao-pratica')::uuid, 'respiracao-pratica', (select id from public.lessons where slug = 'respiracao-e-fraseado'), 'Prática de sustentação do ar', 'Use o metrônomo a 60 bpm e marque o que conseguiu.', 'self_check', '{"minutes":6,"items":["Inspiração sem subir os ombros","“sss” constante por 8 tempos","“sss” constante por 12 tempos","Frase cantada inteira com uma respiração","Respirações marcadas numa estrofe"]}'::jsonb, 'respiracao-fraseado', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:respiracao-avaliacao')::uuid, 'respiracao-avaliacao', (select id from public.lessons where slug = 'respiracao-e-fraseado'), 'Avaliação: respiração e fraseado', 'Responda sobre respiração e planejamento das frases.', 'quiz', '{"questions":[{"q":"Onde sentimos a expansão numa inspiração adequada para cantar?","options":["Cintura, costelas laterais e costas","Somente no peito alto","Nos ombros","Na garganta"],"answer":0},{"q":"Se o ar está acabando antes do fim da frase, o que é melhor fazer no estudo?","options":["Cantar mais suave e planejar uma respiração em lugar adequado","Empurrar o ar com força","Prender a respiração e continuar","Encher o pulmão ao máximo, até ficar tenso"],"answer":0},{"q":"Onde normalmente marcamos as respirações?","options":["Nas pausas, vírgulas do texto e finais de frase","No meio das palavras mais longas","Em qualquer lugar, quando faltar ar","Somente no início da música"],"answer":0},{"q":"O que é respiração escalonada?","options":["Cada cantor respira em um momento diferente para o som do naipe não parar","Respirar em degraus, cada vez mais fundo","Todos respiram juntos no mesmo ponto","Respirar apenas pelo nariz"],"answer":0},{"q":"Inspirar ar demais pode…","options":["Gerar tensão e dificultar o controle","Garantir mais afinação","Deixar a voz mais aguda","Não tem efeito"],"answer":0}]}'::jsonb, 'respiracao-fraseado', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:emissao-confortavel')::uuid, (select id from public.learning_paths where slug = 'fundamentos-vocais'), 'emissao-confortavel', 'Emissão confortável e ressonância', 'Som livre e projetado sem apertar a garganta.', 3, 1, 20, '{"objetivo":"Produzir um som equilibrado — nem soproso, nem apertado — usando a ressonância para projetar a voz sem aumentar o esforço.","gancho":"Dá para ser ouvido(a) lá no fundo da igreja sem gritar? Dá! O segredo está no começo do som e nos espaços do seu rosto.","etapas":[{"titulo":"Três jeitos de começar um som","tipo":"descobrir","blocos":[{"type":"p","text":"A emissão é o início do som. Ela pode ser de três tipos, e o nosso objetivo é a equilibrada."},{"type":"list","items":["Soprosa: sai muito ar e pouca nota.","Apertada: a garganta fecha e o som fica duro.","Equilibrada: o som começa limpo, com o ar e as pregas vocais coordenados."]},{"type":"callout","icon":"ideia","title":"O “ã-hã” de concordância","text":"Diga “ã-hã” como quem concorda com algo agradável. Esse começo suave e limpo é o ataque equilibrado."}]},{"titulo":"Experimente os três","tipo":"experimentar","blocos":[{"type":"timer","instruction":"Numa nota confortável, cante “ah” soproso (com muito ar), depois “ah” apertado e, por fim, o “ah” equilibrado do “ã-hã”. Perceba a diferença.","seconds":30},{"type":"check","question":"Qual emissão é a mais saudável e eficiente?","options":["Equilibrada","Soprosa","Apertada"],"answer":0,"explain":"Na equilibrada, ar e pregas vocais trabalham juntos: som limpo, sem desperdiçar ar e sem apertar a garganta."}]},{"titulo":"Onde o som ganha corpo","tipo":"descobrir","blocos":[{"type":"illustration","name":"ressonancia","caption":"Garganta, boca e cavidade nasal amplificam o som."},{"type":"p","text":"Ressonância é a amplificação do som nas cavidades acima das pregas vocais: garganta, boca e cavidade nasal. Pequenos ajustes fazem a voz ser ouvida com clareza sem gritar."},{"type":"callout","icon":"musica","title":"Espaço de bocejo","text":"Sinta o início de um bocejo: o palato mole sobe e a boca ganha espaço. A língua fica relaxada, tocando os dentes de baixo, sem afundar."}]},{"titulo":"Do “hum” ao “á”","tipo":"experimentar","blocos":[{"type":"p","text":"Faça “hum” e abra para “á” sem perder a vibração à frente: “hummmm-á”. Sinta lábios, nariz e maçãs do rosto vibrando."},{"type":"singAlong","instruction":"Ouça a nota e cante “hummmm-á”, mantendo a vibração à frente.","note":"E4","seconds":4},{"type":"reveal","prompt":"Ao abrir para “á”, a vibração no rosto continuou?","answer":"Se sumiu, a garganta pode ter apertado ou a língua afundado. Volte ao “hum”, mantenha o espaço de bocejo e abra devagar."},{"type":"toolLink","tool":"afinador","label":"Sustente a nota no treinador de afinação"}]},{"titulo":"Brilho com “nhã”","tipo":"ouvir","blocos":[{"type":"audio","label":"Padrão “nhã-nhã-nhã” (Sol–Fá–Mi–Ré–Dó)","notes":["G4","F4","E4","D4","C4"],"tempo":100},{"type":"p","text":"Cante o padrão em “nhã”, descendo as cinco notas (vozes graves, uma oitava abaixo). Depois cante a mesma melodia em “lá”, mantendo o mesmo brilho."},{"type":"timer","instruction":"Alterne: uma vez em “nhã”, uma vez em “lá”. O “lá” ficou tão brilhante quanto o “nhã”?","seconds":10,"reps":3}]},{"titulo":"Mais forte sem apertar","tipo":"aplicar","blocos":[{"type":"p","text":"Para cantar mais forte, aumente o fluxo de ar e o espaço interno. O pescoço continua solto."},{"type":"trueFalse","items":[{"statement":"Para ser ouvido(a), preciso apertar a garganta.","answer":false,"explain":"Volume vem do equilíbrio entre ar e ressonância, não de força na garganta."},{"statement":"Afundar a língua cria mais espaço para o som.","answer":false,"explain":"O espaço vem do palato mole elevado. A língua fica relaxada, tocando os dentes de baixo."},{"statement":"Sentir o som “à frente” no rosto ajuda a projetar.","answer":true,"explain":"No “hum” e no “nhã”, a vibração nos lábios e no rosto mostra a ressonância trabalhando a seu favor."}]},{"type":"timer","instruction":"Cante uma frase de hino em volume médio e depois mais forte, só com mais ar e mais espaço.","seconds":30}]},{"titulo":"Sinais de alerta","tipo":"aplicar","blocos":[{"type":"warning","text":"Rouquidão frequente, dor ou sensação de “bola” na garganta não são normais. Interrompa o exercício e procure um profissional de saúde (otorrinolaringologista ou fonoaudiólogo). Esta plataforma não faz diagnóstico."},{"type":"check","question":"Você fica rouco(a) depois de quase todo ensaio. O que fazer?","options":["Procurar um otorrino ou fonoaudiólogo","Cantar mais forte para “abrir” a voz","Ignorar: é sinal de voz aquecida","Pigarrear até passar"],"answer":0,"explain":"Rouquidão frequente não é normal nem sinal de esforço “bom”. Quem avalia é um profissional de saúde."}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada termo ao que ele significa.","pairs":[{"left":"Emissão soprosa","right":"Muito ar e pouca nota"},{"left":"Emissão apertada","right":"Garganta fechada, som duro"},{"left":"Emissão equilibrada","right":"Ar e pregas vocais coordenados"},{"left":"Ressonância","right":"Amplificação nas cavidades acima das pregas"}]}]}],"pratiqueSozinho":{"passos":["5 repetições de “hum → á” em notas confortáveis.","Padrão “nhã” → “lá” subindo meio-tom por vez.","Uma frase de hino em três volumes: suave, médio e forte."],"minutos":8,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Confundir volume com força na garganta.","correcao":"Aumente o volume com mais fluxo de ar e espaço interno; o pescoço continua solto."},{"erro":"Afundar a língua para “fazer espaço”.","correcao":"O espaço vem do palato mole elevado. A língua fica relaxada, tocando os dentes de baixo."},{"erro":"Som soproso por insegurança.","correcao":"Comece com o “ã-hã” de concordância para coordenar ar e voz."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e sustentar uma nota por 3 segundos com estabilidade no treinador de afinação."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'emissao-ressonancia' from public.lessons where slug = 'emissao-confortavel' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:emissao-nota-sustentada')::uuid, 'emissao-nota-sustentada', (select id from public.lessons where slug = 'emissao-confortavel'), 'Nota sustentada com emissão equilibrada', 'Cante “lá” ou “ú” e sustente a nota. Com microfone, o sistema mede a estabilidade; sem microfone, faça a autoavaliação.', 'sing_note', '{"rounds":3,"holdSeconds":3,"toleranceCents":30}'::jsonb, 'afinacao-nota', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:emissao-avaliacao')::uuid, 'emissao-avaliacao', (select id from public.lessons where slug = 'emissao-confortavel'), 'Avaliação: emissão e ressonância', 'Responda sobre emissão e ressonância.', 'quiz', '{"questions":[{"q":"Qual é a emissão mais saudável e eficiente?","options":["Equilibrada","Soprosa","Apertada","Sussurrada"],"answer":0},{"q":"Ressonância é…","options":["A amplificação do som nas cavidades acima das pregas vocais","A força do ar no abdômen","O volume máximo da voz","Um tipo de respiração"],"answer":0},{"q":"Para cantar mais forte com segurança, devemos…","options":["Aumentar o fluxo de ar e o espaço interno, sem apertar a garganta","Apertar o pescoço","Erguer o queixo","Afundar a língua"],"answer":0},{"q":"Rouquidão frequente ao cantar indica que…","options":["É preciso parar e procurar um profissional de saúde","O exercício está funcionando","Deve-se cantar mais forte","A voz está aquecida"],"answer":0},{"q":"O “ã-hã” de concordância ajuda a…","options":["Coordenar o ar e as pregas vocais num ataque equilibrado","Treinar notas agudas","Respirar pelo nariz","Melhorar a dicção das consoantes"],"answer":0}]}'::jsonb, 'emissao-ressonancia', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:afinacao-basica')::uuid, (select id from public.learning_paths where slug = 'fundamentos-vocais'), 'afinacao-basica', 'Afinação básica', 'Encontrar a nota de referência, reproduzi-la e sustentá-la.', 4, 1, 25, '{"objetivo":"Entender o que é afinação, reproduzir notas a partir de uma referência, sustentá-las e reconhecer tendências de cantar acima ou abaixo da nota.","gancho":"No coral, uma voz simples e afinada soa melhor do que uma voz linda fora da nota. Vamos treinar ouvido e voz para acertar o alvo.","etapas":[{"titulo":"Acertar o alvo","tipo":"descobrir","blocos":[{"type":"p","text":"Afinar é fazer a frequência da sua voz coincidir com a nota esperada. No grupo, a afinação é o que faz os acordes soarem limpos."},{"type":"illustration","name":"onda-afinada","caption":"Voz e referência coincidem: o som fica limpo."},{"type":"trueFalse","items":[{"statement":"Uma voz bonita está sempre afinada.","answer":false,"explain":"Qualidade vocal e afinação são coisas diferentes. Uma voz simples pode estar perfeitamente afinada."},{"statement":"Errar uma tentativa prova que sou desafinado(a).","answer":false,"explain":"Uma tentativa não diz nada. Observe a tendência ao longo de vários dias."}]}]},{"titulo":"Ouça a diferença","tipo":"ouvir","blocos":[{"type":"p","text":"A distância entre alturas próximas é medida em cents: 100 cents são um semitom, de uma tecla para a vizinha. Até 10 a 20 cents quase ninguém percebe; acima de 25 a 30 cents já soa “fora”."},{"type":"compare","prompt":"As duas tentam cantar Lá. Qual está afinada?","options":[{"label":"afinada","notes":["A3"]},{"label":"35 cents abaixo","notes":["A3"],"cents":-35}],"answer":0,"explain":"A versão abaixo soa levemente “caída”. Com treino curto e frequente, essa diferença fica cada vez mais fácil de ouvir."}]},{"titulo":"Ouça, imagine, cante","tipo":"experimentar","blocos":[{"type":"callout","icon":"ouvido","title":"Ouça por dentro","text":"Ouça a referência, imagine o som em silêncio por 2 segundos e só então cante, suave, numa vogal fechada como “u”."},{"type":"singAlong","instruction":"Ouça o Dó, imagine o som e cante “u” suave na mesma altura.","note":"C4","seconds":3},{"type":"tip","title":"Comece suave","text":"Com volume moderado é mais fácil ajustar a altura. Repita com três notas diferentes dentro da sua região confortável."}]},{"titulo":"A mesma nota, outra oitava","tipo":"descobrir","blocos":[{"type":"p","text":"Se a nota estiver longe da sua região, cante-a uma oitava abaixo ou acima. A mesma nota em outra oitava também está afinada."},{"type":"keyboard","from":"C3","to":"C5","highlight":["C3","C4","C5"],"label":"As notas Dó em três oitavas"},{"type":"audio","label":"Mesma nota em duas oitavas (Dó3 e Dó4)","notes":["C3","C4"],"tempo":50},{"type":"check","question":"A referência é Dó4 e você canta Dó3, uma oitava abaixo. Você está…","options":["Afinado(a): é a mesma nota em outra oitava","Desafinado(a)","Cantando outra nota"],"answer":0,"explain":"Notas a uma oitava de distância têm o mesmo nome. Cantar a referência em outra oitava é uma forma afinada e segura de responder."}]},{"titulo":"Treine o controle","tipo":"experimentar","blocos":[{"type":"p","text":"No treinador de afinação, sustente a nota e observe o ponteiro. Ajuste devagar até ficar no centro."},{"type":"toolLink","tool":"afinador","label":"Abrir o treinador de afinação com microfone"},{"type":"timer","instruction":"Cante de propósito um pouco acima, depois um pouco abaixo, e volte ao centro.","seconds":15,"reps":3}]},{"titulo":"Por que a nota escapa?","tipo":"descobrir","blocos":[{"type":"match","prompt":"Ligue cada tipo de dificuldade ao que acontece.","pairs":[{"left":"Auditiva","right":"Não percebe se está acima ou abaixo"},{"left":"Técnica","right":"Percebe, mas a voz não obedece"},{"left":"De coordenação","right":"Acerta devagar, erra em frases rápidas ou com outras vozes"}]},{"type":"tip","text":"Dificuldade auditiva? Treine primeiro a escuta no Laboratório: grave e agudo, perceber desafinação. Técnica? Confira ar, tensão e se a nota está na sua região confortável."}]},{"titulo":"Acima ou abaixo?","tipo":"aplicar","blocos":[{"type":"p","text":"Quem tende a cantar abaixo (“calando”) costuma estar com pouco ar ou cansado. Quem tende a cantar acima costuma estar com tensão ou ansiedade nas entradas."},{"type":"compare","prompt":"As duas tentam cantar Mi, mas nenhuma acertou. Qual ficou acima?","options":[{"label":"acima","notes":["E4"],"cents":40},{"label":"abaixo","notes":["E4"],"cents":-40}],"answer":0,"explain":"Ouvir a direção do erro é o primeiro passo para corrigir. Anote se a sua tendência é ficar acima ou abaixo."},{"type":"reveal","prompt":"Fim de um ensaio longo, e o naipe começa a “calar”. Qual pode ser a causa?","answer":"Cansaço e pouco ar costumam puxar a afinação para baixo. Uma pausa curta e respirações tranquilas ajudam mais do que cantar mais forte."}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"order","prompt":"Coloque na ordem os passos para encontrar uma nota.","items":["Ouvir a referência","Imaginar o som em silêncio","Cantar suave em “u”","Ajustar devagar até o centro"]}]}],"pratiqueSozinho":{"passos":["Treinador de afinação: 5 notas sustentadas por dia.","Laboratório: “perceber desafinação” por 3 minutos.","Anote se a sua tendência é ficar acima ou abaixo."],"minutos":10,"frequencia":"5 vezes por semana"},"errosComuns":[{"erro":"Cantar antes de ouvir a nota por dentro.","correcao":"Ouça, imagine e só depois cante."},{"erro":"Começar a nota muito forte.","correcao":"Comece suave; é mais fácil ajustar a altura com volume moderado."},{"erro":"Desistir após uma tentativa errada.","correcao":"Afinação melhora com repetição curta e frequente. Compare a evolução por semanas, não por tentativas."},{"erro":"Forçar notas fora da região confortável.","correcao":"Cante a nota em outra oitava ou escolha outra nota de treino."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo).","A detecção pelo microfone é uma estimativa: ruído, eco e outros sons podem atrapalhar. Ela não é um diagnóstico."],"criterioAvanco":"Acertar pelo menos 70% nas avaliações desta aula (percepção de desafinação e conceitos)."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'afinacao-nota' from public.lessons where slug = 'afinacao-basica' on conflict do nothing;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'percepcao-afinacao' from public.lessons where slug = 'afinacao-basica' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:afinacao-sustentar-notas')::uuid, 'afinacao-sustentar-notas', (select id from public.lessons where slug = 'afinacao-basica'), 'Reproduzir e sustentar notas', 'Ouça a nota e cante-a sustentando. Use fones de ouvido se possível.', 'sing_note', '{"rounds":4,"holdSeconds":3,"toleranceCents":25}'::jsonb, 'afinacao-nota', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:afinacao-perceber-desafinacao')::uuid, 'afinacao-perceber-desafinacao', (select id from public.lessons where slug = 'afinacao-basica'), 'Avaliação: afinada, acima ou abaixo?', 'Ouça a referência e a segunda nota. Diga se a segunda está afinada, acima ou abaixo.', 'tuning_check', '{"rounds":8,"cents":45}'::jsonb, 'percepcao-afinacao', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:afinacao-avaliacao-conceitos')::uuid, 'afinacao-avaliacao-conceitos', (select id from public.lessons where slug = 'afinacao-basica'), 'Avaliação: conceitos de afinação', 'Responda sobre afinação.', 'quiz', '{"questions":[{"q":"Quantos cents há em um semitom?","options":["100","10","50","1200"],"answer":0},{"q":"Cantar a mesma nota uma oitava abaixo da referência é…","options":["Afinado: é a mesma nota em outra oitava","Desafinado","Uma terça","Um erro de ritmo"],"answer":0},{"q":"Uma pessoa percebe que está desafinada, mas a voz não obedece. Que tipo de dificuldade é mais provável?","options":["Técnica ou de coordenação","Auditiva","De leitura","Rítmica"],"answer":0},{"q":"O que fazer antes de cantar uma nota de referência?","options":["Ouvir e imaginar o som por dentro","Cantar o mais forte possível","Prender a respiração","Subir o queixo"],"answer":0},{"q":"Errar uma tentativa no treinador significa que a pessoa é desafinada?","options":["Não: é preciso observar a tendência ao longo de vários dias","Sim, sempre","Sim, se for a primeira tentativa","Depende do volume"],"answer":0}]}'::jsonb, 'afinacao-nota', 'avaliacao', 1, 2) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:diccao-e-articulacao')::uuid, (select id from public.learning_paths where slug = 'fundamentos-vocais'), 'diccao-e-articulacao', 'Dicção e articulação', 'Texto compreensível, vogais unificadas e consoantes claras.', 5, 1, 15, '{"objetivo":"Cantar com texto inteligível, unificando as vogais com o grupo e articulando as consoantes no tempo certo, sem quebrar o legato.","gancho":"Na música sacra, a letra é a mensagem. Se a congregação não entende as palavras, parte do propósito se perde. Vamos deixar cada palavra clara.","etapas":[{"titulo":"Vogal é som, consoante é moldura","tipo":"descobrir","blocos":[{"type":"p","text":"Cantando, sustentamos as vogais: é nelas que está o som. As consoantes aparecem rápidas e precisas, como molduras das vogais."},{"type":"callout","icon":"olho","title":"Quadro e moldura","text":"A vogal é o quadro; a consoante, a moldura. A moldura precisa estar lá, nítida, mas ninguém vai ao museu para ver só a moldura."},{"type":"check","question":"Numa nota longa na palavra “Deus”, o que você sustenta?","options":["O “ê”, colocando o “u” só no final","O “s” final","O “D” inicial","O “u”"],"answer":0,"explain":"Cante “Dê-us”: sustente o “ê” e coloque o “u” e o “s” só no último instante."}]},{"titulo":"Cinco vogais, uma nota","tipo":"experimentar","blocos":[{"type":"illustration","name":"vogais","caption":"Muda a vogal; a mandíbula quase não se mexe."},{"type":"audio","label":"Nota para exercitar vogais (mi-mê-má-mô-mu)","notes":["D4","D4","D4","D4","D4"],"tempo":80},{"type":"timer","instruction":"Fale e depois cante numa nota só: “mi – mê – má – mô – mu”. Mude apenas a vogal, sem mexer a mandíbula de forma exagerada.","seconds":30}]},{"titulo":"Ditongos sem pressa","tipo":"descobrir","blocos":[{"type":"p","text":"Nos ditongos, a segunda vogal entra só no último instante: “mãe” vira “mããã-e”, com o “e” bem no fim."},{"type":"trueFalse","items":[{"statement":"Em “mãe”, sustento o “ã” e coloco o “e” no final.","answer":true,"explain":"A primeira vogal carrega a nota; a segunda só fecha a palavra."},{"statement":"Sustentar consoantes deixa a palavra mais clara (“Deusssss”).","answer":false,"explain":"Consoante sustentada vira ruído. Sustente a vogal; a consoante é rápida."},{"statement":"Para articular bem, preciso fechar bastante a boca.","answer":false,"explain":"A articulação vem de lábios e língua ágeis, não da mandíbula travada."}]}]},{"titulo":"Consoantes no tempo certo","tipo":"descobrir","blocos":[{"type":"p","text":"Consoantes iniciais: articule um pouco antes do tempo, para a vogal cair no tempo. Consoantes finais: no grupo, todos soltam o “s” ou o “r” juntos, no corte indicado pelo regente."},{"type":"check","question":"Para a vogal cair exatamente no tempo, quando entra a consoante inicial?","options":["Um pouco antes do tempo","Exatamente no tempo","Depois do tempo"],"answer":0,"explain":"A consoante gasta um instante. Começando um pouco antes, a vogal, que carrega o som, cai certinha no tempo."},{"type":"tip","title":"E o “r”?","text":"Em português cantado, evite o “r” muito arrastado ou gutural. Prefira o “r” vibrante simples ou suave, conforme a orientação do grupo."}]},{"titulo":"Trava-línguas no ritmo","tipo":"experimentar","blocos":[{"type":"rhythm","pattern":"e e e e e e e e","bpm":80,"label":"Ritmo para trava-línguas em colcheias"},{"type":"timer","instruction":"No ritmo das colcheias: “Três pratos de trigo para três tigres tristes”. Sem tropeçar e sem pressa.","seconds":30},{"type":"toolLink","tool":"metronomo","label":"Abrir o metrônomo para treinar trava-línguas"}]},{"titulo":"“Senhor” sem arrastar","tipo":"experimentar","blocos":[{"type":"p","text":"Sustente “Se-” e “-nhô” e solte o “r” somente no final, no corte."},{"type":"singAlong","instruction":"Cante “Se-nhôôô” nesta nota e solte o “r” só no último instante.","note":"D4","seconds":4},{"type":"reveal","prompt":"Cinco pessoas soltam o “s” de “Deus”, cada uma num momento. Como isso soa para a congregação?","answer":"Como um chiado espalhado: “Deus-s-s-s-s”. Combinem o corte com o regente e soltem juntos, sem exagero."}]},{"titulo":"Um naipe, uma vogal","tipo":"aplicar","blocos":[{"type":"callout","icon":"ouvido","title":"Unidade de vogais","text":"Cinco pessoas cantando “é” de cinco jeitos soam como cinco vozes separadas. Combinem a forma da boca: lábios levemente arredondados ajudam a unificar o som."},{"type":"checklist","title":"Teste com um hino","items":["Li a estrofe em voz alta, com calma","Cantei com a mesma clareza da leitura","Sustentei as vogais, não as consoantes","Soltei as consoantes finais no tempo"]},{"type":"toolLink","tool":"gravador","label":"Grave a estrofe: o texto está compreensível?"}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada elemento à forma de cantá-lo.","pairs":[{"left":"Vogal","right":"Sustentada: carrega o som"},{"left":"Consoante inicial","right":"Um pouco antes do tempo"},{"left":"Consoante final","right":"Todos juntos, no corte"},{"left":"Ditongo","right":"Segunda vogal só no fim"}]}]}],"pratiqueSozinho":{"passos":["2 minutos de trava-línguas com metrônomo.","Cante uma estrofe sustentando as vogais e cortando as consoantes finais no tempo.","Grave e confira se o texto está compreensível."],"minutos":6,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Sustentar consoantes (“mmmmãe”, “Deusssss”).","correcao":"Sustente a vogal; a consoante é rápida."},{"erro":"Fechar a boca demais para articular.","correcao":"A articulação é feita com lábios e língua ágeis, não com a mandíbula travada."},{"erro":"Cada pessoa soltar o “s” final num momento diferente.","correcao":"Combine o corte com o regente e solte junto, sem exagero."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e gravar uma estrofe com o texto compreensível."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'diccao-articulacao' from public.lessons where slug = 'diccao-e-articulacao' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:diccao-pratica')::uuid, 'diccao-pratica', (select id from public.lessons where slug = 'diccao-e-articulacao'), 'Prática de dicção', 'Faça os exercícios e marque o que conseguiu com clareza.', 'self_check', '{"minutes":6,"items":["Vogais puras numa nota só","Trava-língua no ritmo sem tropeçar","Consoante final no tempo certo","Estrofe gravada com texto claro"]}'::jsonb, 'diccao-articulacao', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:diccao-avaliacao')::uuid, 'diccao-avaliacao', (select id from public.lessons where slug = 'diccao-e-articulacao'), 'Avaliação: dicção cantada', 'Responda sobre dicção e articulação.', 'quiz', '{"questions":[{"q":"Ao cantar, o som é sustentado principalmente nas…","options":["Vogais","Consoantes","Pausas","Respirações"],"answer":0},{"q":"Como cantar o ditongo de “mãe” numa nota longa?","options":["Sustentar “mã” e colocar o “e” no final","Sustentar o “e”","Alternar “ã” e “e”","Cantar só o “m”"],"answer":0},{"q":"Para que a vogal caia exatamente no tempo, a consoante inicial deve ser articulada…","options":["Um pouco antes do tempo","Depois do tempo","Junto com a respiração seguinte","Sem preocupação"],"answer":0},{"q":"Por que unificar as vogais no naipe?","options":["Para o naipe soar como uma só voz","Para cantar mais rápido","Para cantar mais agudo","Não é necessário"],"answer":0}]}'::jsonb, 'diccao-articulacao', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:extensao-tessitura-registros')::uuid, (select id from public.learning_paths where slug = 'fundamentos-vocais'), 'extensao-tessitura-registros', 'Extensão, tessitura e registros', 'Conhecer a própria região confortável e transitar entre registros sem forçar.', 6, 2, 25, '{"objetivo":"Diferenciar extensão e tessitura, conhecer os registros vocais e identificar a própria região confortável sem forçar notas extremas.","gancho":"Sua voz é de soprano, contralto, tenor ou baixo? Antes de responder, vamos descobrir onde ela canta feliz, sem esforço.","etapas":[{"titulo":"Extensão × tessitura","tipo":"descobrir","blocos":[{"type":"illustration","name":"extensao-tessitura","caption":"A tessitura fica dentro da extensão."},{"type":"p","text":"Extensão é tudo o que você consegue cantar, do mais grave ao mais agudo, inclusive com esforço. Tessitura é a região em que a voz canta com conforto, boa qualidade e por bastante tempo."},{"type":"callout","icon":"ideia","title":"Pense numa casa","text":"A extensão é a casa inteira, até o sótão apertado. A tessitura é a sala onde você mora e passa o dia."},{"type":"check","question":"Para escolher a sua parte num arranjo, o que conta mais?","options":["A tessitura, onde canto com conforto","A nota mais aguda que alcanço","A nota mais grave que alcanço"],"answer":0,"explain":"Uma música inteira pede conforto do começo ao fim. As notas extremas fazem parte da extensão, não da tessitura."}]},{"titulo":"Os registros da voz","tipo":"descobrir","blocos":[{"type":"illustration","name":"registros","caption":"Peito, mista e cabeça: a vibração muda de lugar."},{"type":"match","prompt":"Ligue cada registro à sua característica.","pairs":[{"left":"Voz de peito","right":"Vibra no peito, som mais denso, grave e médio"},{"left":"Voz de cabeça","right":"Vibra no rosto e na cabeça, som mais leve, agudo"},{"left":"Voz mista","right":"Equilíbrio entre os dois, transição suave"},{"left":"Região de passagem","right":"Notas em que a voz muda de registro"}]}]},{"titulo":"Sirene: sinta a mudança","tipo":"experimentar","blocos":[{"type":"p","text":"Faça a sirene em “u”, do grave ao agudo, bem suave. Observe onde a sensação de vibração muda do peito para a cabeça."},{"type":"timer","instruction":"Sirene suave em “u”: suba e desça devagar, sem empurrar.","seconds":10,"reps":3},{"type":"reveal","prompt":"Sua voz deu uma “quebrada” no meio da sirene?","answer":"Normal! É a região de passagem entre registros. Com treino suave, a transição fica lisa. A identificação precisa da passagem deve ser feita com um professor."}]},{"titulo":"Atravesse a passagem","tipo":"ouvir","blocos":[{"type":"audio","label":"Deslize por arpejo (vozes femininas)","notes":["C4","E4","G4","C5","G4","E4","C4"],"tempo":100},{"type":"audio","label":"Deslize por arpejo (vozes masculinas)","notes":["C3","E3","G3","C4","G3","E3","C3"],"tempo":100},{"type":"p","text":"Cante o arpejo Dó–Mi–Sol–Dó em “u”, passando pela região de passagem com volume suave."},{"type":"check","question":"Subindo o arpejo, a voz começa a pesar. O que fazer?","options":["Deixar a voz ficar mais leve, sem empurrar","Empurrar a voz de peito mais forte","Erguer o queixo para alcançar"],"answer":0,"explain":"Ao subir, a voz fica mais leve: a voz de cabeça e a voz mista existem para isso. Empurrar a voz de peito cansa e pode machucar."}]},{"titulo":"Mapeie a sua região","tipo":"experimentar","blocos":[{"type":"keyboard","from":"E2","to":"C6","highlight":["C4"],"label":"Teclado de referência (Dó4 = dó central)"},{"type":"p","text":"No mapeamento, cante cada nota proposta e marque: confortável, com esforço ou não alcanço."},{"type":"warning","text":"Pare de subir ou descer no primeiro sinal de esforço. As notas “com esforço” fazem parte da extensão, não da tessitura."},{"type":"toolLink","tool":"extensao","label":"Abrir o mapeamento da região confortável"}]},{"titulo":"Sem competição","tipo":"aplicar","blocos":[{"type":"callout","icon":"coracao","title":"O que importa no ministério","text":"Ninguém canta melhor por alcançar a nota mais aguda ou mais grave. O que importa é cantar a sua parte com conforto e qualidade. Exercícios extremos podem machucar a voz."},{"type":"check","question":"Ana alcança as notas do soprano, mas com esforço. No contralto, canta a música inteira com conforto. Onde ela deve cantar, por enquanto?","options":["No contralto, onde está a tessitura dela","No soprano, já que alcança as notas","Alternando, para treinar o agudo no culto"],"answer":0,"explain":"A parte certa é a da região confortável durante a música inteira. Com o estudo, isso pode mudar."}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"p","text":"Soprano, mezzo-soprano, contralto, tenor, barítono e baixo: a classificação considera tessitura, timbre e passagens. Aqui ela sempre começa provisória, porque vozes se desenvolvem com o estudo."},{"type":"trueFalse","items":[{"statement":"Minha classificação vocal é definitiva desde o primeiro teste.","answer":false,"explain":"Ela começa provisória e pode ser revista pelo professor."},{"statement":"A voz “falhar” na passagem é um defeito.","answer":false,"explain":"É uma transição natural, que se coordena com treino suave."},{"statement":"Ao sentir esforço numa nota, devo parar e voltar à região confortável.","answer":true,"explain":"Não procure as notas extremas. Pare no primeiro sinal de esforço."}]}]}],"pratiqueSozinho":{"passos":["Sirene suave em “u” por 1 minuto.","Arpejos leves atravessando a passagem em volume suave.","Refaça o mapeamento da região a cada 4 semanas para ver a evolução."],"minutos":6,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Empurrar a voz de peito cada vez mais alto.","correcao":"Deixe a voz ficar mais leve ao subir; a voz de cabeça e a voz mista existem para isso."},{"erro":"Achar que a voz “falhar” na passagem é defeito.","correcao":"É uma transição natural que se coordena com treino suave."},{"erro":"Escolher a parte do arranjo pela nota mais aguda que alcança.","correcao":"Escolha pela região onde canta com conforto durante a música inteira."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo).","Não procure as notas extremas: pare no primeiro sinal de esforço."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e concluir um mapeamento da região confortável."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'registros-extensao' from public.lessons where slug = 'extensao-tessitura-registros' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:registros-avaliacao')::uuid, 'registros-avaliacao', (select id from public.lessons where slug = 'extensao-tessitura-registros'), 'Avaliação: extensão, tessitura e registros', 'Responda sobre extensão, tessitura e registros.', 'quiz', '{"questions":[{"q":"Qual a diferença entre extensão e tessitura?","options":["Extensão é tudo o que se alcança; tessitura é a região confortável","São a mesma coisa","Tessitura é a nota mais aguda","Extensão é só a região grave"],"answer":0},{"q":"Para escolher a sua parte num arranjo, o mais importante é…","options":["A tessitura (região confortável)","A nota mais aguda que você alcança","A nota mais grave que você alcança","Cantar a melodia sempre"],"answer":0},{"q":"A voz “quebrar” ao passar do grave para o agudo indica…","options":["Uma região de passagem entre registros, que pode ser coordenada com treino","Que a pessoa não pode cantar","Uma doença","Que deve cantar mais forte"],"answer":0},{"q":"A classificação vocal nesta plataforma começa como…","options":["Provisória, podendo ser revista pelo professor","Definitiva","Obrigatória para cantar","Baseada só na nota mais aguda"],"answer":0},{"q":"Ao sentir esforço numa nota aguda, você deve…","options":["Parar de subir e voltar à região confortável","Insistir até conseguir","Cantar mais forte","Erguer o queixo"],"answer":0}]}'::jsonb, 'registros-extensao', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:interpretacao-musical')::uuid, (select id from public.learning_paths where slug = 'fundamentos-vocais'), 'interpretacao-musical', 'Interpretação musical', 'Dinâmica, fraseado, legato e intenção do texto sacro.', 7, 2, 20, '{"objetivo":"Usar dinâmica, fraseado, legato e articulação para comunicar o sentido do texto, equilibrando emoção, técnica e inteligibilidade, em unidade com o grupo.","gancho":"A mesma melodia pode soar como uma oração íntima ou como um hino de vitória. A diferença está em como você canta. Vamos dar sentido às notas.","etapas":[{"titulo":"Comece pelo texto","tipo":"descobrir","blocos":[{"type":"p","text":"Interpretar é dar sentido às notas. O ponto de partida é sempre o texto: o que ele diz, para quem e com que sentimento."},{"type":"callout","icon":"coracao","title":"Cante o texto, não só as notas","text":"O rosto e a expressão também comunicam. Quem ouve percebe quando você canta com intenção."},{"type":"check","question":"Qual é o ponto de partida para interpretar um hino?","options":["O sentido do texto","O volume máximo da voz","A nota mais aguda","O andamento mais rápido possível"],"answer":0,"explain":"Dinâmica, fraseado e articulação servem ao texto. Primeiro entenda o que se diz; depois decida como cantar."}]},{"titulo":"O volume conta uma história","tipo":"descobrir","blocos":[{"type":"illustration","name":"dinamica","caption":"Do pp ao ff, com crescendo e decrescendo."},{"type":"list","items":["Dinâmica: variações de intensidade, do pp (pianíssimo) e p (piano, suave) ao f (forte) e ff.","Crescendo: aumentar aos poucos. Decrescendo: diminuir aos poucos."]},{"type":"order","prompt":"Ordene do mais suave para o mais forte.","items":["pp","p","mp","mf","f","ff"]}]},{"titulo":"Notas de mãos dadas","tipo":"ouvir","blocos":[{"type":"p","text":"Legato é cantar as notas ligadas, sem buracos entre elas. É o padrão do canto coral sacro. Staccato e acentos são articulações curtas ou marcadas, usadas para efeito de texto."},{"type":"audio","label":"Frase em legato (Sol–Lá–Si–Dó–Si–Lá–Sol)","notes":["G4","A4","B4","C5","B4","A4","G4"],"tempo":72},{"type":"check","question":"Qual descrição combina com o legato?","options":["Notas ligadas, sem interrupções","Notas curtas e separadas","Notas sempre acentuadas"],"answer":0,"explain":"No legato, o som passa de uma nota à outra como um fio contínuo. Notas curtas e separadas são o staccato."}]},{"titulo":"Dê direção à frase","tipo":"experimentar","blocos":[{"type":"p","text":"Cante a frase anterior em “lu”, em legato (vozes graves, uma oitava abaixo). Depois cresça até a nota mais aguda, o Dó, e diminua até o fim."},{"type":"timer","instruction":"Primeira vez: só legato. Segunda: com crescendo até o Dó e decrescendo até o fim.","seconds":15,"reps":2},{"type":"tip","title":"Emoção não é volume","text":"Momentos suaves também emocionam. Planeje pelo menos um crescendo e um momento suave em cada estrofe."}]},{"titulo":"Para onde vai a frase?","tipo":"descobrir","blocos":[{"type":"p","text":"Cada frase tem uma direção, normalmente para uma palavra ou sílaba importante. Evite acentuar sílabas fracas: respeite a acentuação natural da fala."},{"type":"check","question":"Na palavra “glória”, qual sílaba recebe o acento natural?","options":["GLÓ","ri","a"],"answer":0,"explain":"Na fala dizemos “GLÓ-ri-a”. Cantando, mantenha esse acento e não empurre as sílabas fracas do fim."},{"type":"reveal","prompt":"Leia: “Grande é o Senhor e mui digno de louvor”. Para qual palavra você dirigiria a frase?","answer":"Não há uma única resposta: muitos escolheriam “grande” ou “digno”. O importante é decidir, combinar com o grupo e conduzir a frase até ela."}]},{"titulo":"Unidade sonora","tipo":"aplicar","blocos":[{"type":"callout","icon":"ouvido","title":"Todos juntos","text":"No grupo, todos crescem, respiram e cortam juntos. Emoção individual sem unidade vira desequilíbrio; técnica sem emoção vira execução fria. O regente conduz esse equilíbrio."},{"type":"trueFalse","items":[{"statement":"Quem sente mais a música deve cantar mais forte que o grupo.","answer":false,"explain":"Emoção individual sem unidade vira desequilíbrio. A interpretação é combinada."},{"statement":"Cantar tudo no mesmo volume deixa a música mais bonita.","answer":false,"explain":"Sem variação de dinâmica a música fica plana. Planeje crescendos e momentos suaves."},{"statement":"Momentos suaves também podem emocionar.","answer":true,"explain":"Emoção não depende de volume. Um pianíssimo bem cantado toca muito."}]}]},{"titulo":"Sua vez: prepare uma estrofe","tipo":"aplicar","blocos":[{"type":"checklist","title":"Passo a passo","items":["Sublinhei a palavra mais importante de cada frase","Marquei respirações e dinâmicas na letra","Cantei dirigindo cada frase para a palavra sublinhada","Gravei e ouvi: a interpretação combina com o texto?"]},{"type":"harmonyLink","arrangement":"hino-alegria-unissono","label":"Pratique dinâmica no “Hino da Alegria” em uníssono"},{"type":"toolLink","tool":"gravador","label":"Gravar a estrofe"}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada termo ao seu significado.","pairs":[{"left":"p","right":"Piano: suave"},{"left":"f","right":"Forte"},{"left":"Crescendo","right":"Aumentar aos poucos"},{"left":"Legato","right":"Notas ligadas"},{"left":"Staccato","right":"Notas curtas"}]}]}],"pratiqueSozinho":{"passos":["Escolha uma música do repertório e marque dinâmicas e respirações na letra.","Cante em três versões: sem dinâmica, com a dinâmica marcada e com exagero. Compare.","Leve as marcações para discutir no ensaio."],"minutos":10,"frequencia":"2 vezes por semana"},"errosComuns":[{"erro":"Acentuar a última sílaba das palavras (“Se-NHOR” em notas longas sem intenção).","correcao":"Respeite a acentuação natural da fala."},{"erro":"Cantar tudo no mesmo volume.","correcao":"Planeje pelo menos um crescendo e um momento suave em cada estrofe."},{"erro":"Confundir emoção com volume excessivo.","correcao":"Momentos suaves também emocionam; o grupo precisa de equilíbrio."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e apresentar ao professor uma estrofe com dinâmicas e respirações marcadas."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'interpretacao' from public.lessons where slug = 'interpretacao-musical' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:interpretacao-avaliacao')::uuid, 'interpretacao-avaliacao', (select id from public.lessons where slug = 'interpretacao-musical'), 'Avaliação: elementos de interpretação', 'Responda sobre interpretação musical.', 'quiz', '{"questions":[{"q":"O que significa “p” numa partitura?","options":["Piano: suave","Pausa","Pulsação","Passagem"],"answer":0},{"q":"Crescendo significa…","options":["Aumentar a intensidade aos poucos","Cantar mais agudo","Acelerar","Diminuir a intensidade"],"answer":0},{"q":"Legato é…","options":["Cantar as notas ligadas, sem interrupções","Cantar notas curtas","Cantar sem texto","Cantar mais forte"],"answer":0},{"q":"Qual deve ser o ponto de partida da interpretação de um hino?","options":["O sentido do texto","O volume máximo da voz","A nota mais aguda","O andamento mais rápido possível"],"answer":0},{"q":"Num grupo, a interpretação deve ser…","options":["Combinada, com unidade de dinâmicas, respirações e cortes","Individual, cada um do seu jeito","Sempre forte","Definida por quem canta mais alto"],"answer":0}]}'::jsonb, 'interpretacao', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.learning_paths (id, slug, code, title, subtitle, description, icon, sort) values (md5('path:percepcao-musical')::uuid, 'percepcao-musical', 'B', 'Percepção musical', 'Aprender a ouvir antes de cantar', 'Treino auditivo progressivo: altura, reprodução de notas, intervalos, memória melódica, ritmo e acordes. Cada aula combina exemplos sonoros, prática no teclado e avaliação com feedback imediato.', 'ear', 1) on conflict (slug) do update set code = excluded.code, title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, icon = excluded.icon, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:grave-e-agudo')::uuid, (select id from public.learning_paths where slug = 'percepcao-musical'), 'grave-e-agudo', 'Reconhecimento de notas graves e agudas', 'Perceber a direção do som: mais agudo, mais grave ou igual.', 0, 1, 15, '{"objetivo":"Perceber se uma nota é mais aguda, mais grave ou igual a outra, mesmo quando a diferença é pequena.","gancho":"Será que você percebe quando a melodia sobe só um pouquinho? Vamos treinar o ouvido com desafios rápidos, do mais fácil ao mais sutil.","etapas":[{"titulo":"Fino ou grosso?","tipo":"descobrir","blocos":[{"type":"p","text":"Altura é o que faz um som ser agudo (“fino”) ou grave (“grosso”). Ela depende da frequência: quanto mais vibrações por segundo, mais agudo o som."},{"type":"compare","prompt":"Ouça as duas notas. Qual é a mais aguda?","options":[{"label":"Dó5, a mais aguda","notes":["C5"]},{"label":"Dó4, a mais grave","notes":["C4"]}],"answer":0,"explain":"O Dó5 vibra duas vezes mais rápido que o Dó4: é a mesma nota, uma oitava acima."}]},{"titulo":"Esquerda grave, direita aguda","tipo":"descobrir","blocos":[{"type":"illustration","name":"intervalo-escada","caption":"Cada degrau acima é um som mais agudo."},{"type":"keyboard","from":"C3","to":"C5","label":"Toque teclas à esquerda (graves) e à direita (agudas)"},{"type":"check","question":"No teclado, para que lado as notas ficam mais agudas?","options":["Para a direita","Para a esquerda","Depende da cor da tecla"],"answer":0,"explain":"Da esquerda para a direita o som sobe. As teclas pretas seguem a mesma regra das brancas."}]},{"titulo":"Do grande ao pequeno","tipo":"ouvir","blocos":[{"type":"callout","icon":"maos","title":"Use a mão","text":"Ao ouvir cada par, mova a mão para cima ou para baixo junto com a segunda nota. Muita gente percebe melhor a direção com um gesto."},{"type":"audio","label":"Grande diferença: Dó4 → Dó5","notes":["C4","C5"],"tempo":60},{"type":"audio","label":"Diferença média: Dó4 → Sol4","notes":["C4","G4"],"tempo":60},{"type":"audio","label":"Diferença pequena: Dó4 → Ré4","notes":["C4","D4"],"tempo":60},{"type":"audio","label":"Descendo: Sol4 → Mi4","notes":["G4","E4"],"tempo":60}]},{"titulo":"Desafio: para onde foi?","tipo":"ouvir","blocos":[{"type":"p","text":"Ouça até o fim da segunda nota antes de responder. Pode repetir quantas vezes quiser."},{"type":"check","question":"A segunda nota é…","options":["Mais aguda","Mais grave","Igual"],"answer":1,"explain":"Mi4 → Dó4: a melodia desceu. Sua mão deveria ter ido para baixo.","audio":{"notes":["E4","C4"],"tempo":60}},{"type":"check","question":"E agora, a segunda nota é…","options":["Mais aguda","Mais grave","Igual"],"answer":0,"explain":"Ré4 → Mi4: subiu só um tom. Diferenças pequenas exigem atenção, mas o ouvido aprende rápido.","audio":{"notes":["D4","E4"],"tempo":60}},{"type":"check","question":"E neste par?","options":["Mais aguda","Mais grave","Igual"],"answer":2,"explain":"Lá3 → Lá3: a mesma nota repetida. “Igual” também é uma resposta possível!","audio":{"notes":["A3","A3"],"tempo":60}}]},{"titulo":"Altura não é volume","tipo":"descobrir","blocos":[{"type":"p","text":"Um som pode ser grave e forte, ou agudo e suave. E timbre é outra coisa: um violão e uma voz podem tocar exatamente a mesma altura."},{"type":"trueFalse","items":[{"statement":"Um som mais forte é sempre mais agudo.","answer":false,"explain":"Volume e altura são independentes. Os exercícios tocam as notas com o mesmo volume para você focar só na altura."},{"statement":"Uma voz e um violão podem tocar a mesma nota.","answer":true,"explain":"A cor do som (timbre) muda, mas a altura pode ser idêntica."},{"statement":"Uma nota grave pode ser cantada bem suave.","answer":true,"explain":"Grave não quer dizer forte. O baixo do coral canta pianíssimo muitas vezes."}]}]},{"titulo":"Sua voz sobe","tipo":"experimentar","blocos":[{"type":"p","text":"Agora sinta a diferença de altura na própria voz. Cante em “lá”, sem esforço."},{"type":"singAlong","instruction":"Ouça e cante o Dó em “lá”, sustentando.","note":"C4","seconds":3},{"type":"singAlong","instruction":"Agora uma nota mais aguda: Mi. Sinta a voz subir, sem apertar.","note":"E4","seconds":3}]},{"titulo":"Nos hinos","tipo":"aplicar","blocos":[{"type":"p","text":"Toda melodia é feita de notas que sobem, descem ou repetem. Ouça este trecho conhecido."},{"type":"check","question":"No “Parabéns pra você”, a primeira frase termina mais aguda ou mais grave do que começou?","options":["Mais aguda","Mais grave","Na mesma nota"],"answer":0,"explain":"Sol–Sol–Lá–Sol–Dó–Si: a frase começa no Sol e chega ao Si, acima. Faça o mesmo exercício ao ouvir os hinos do culto.","audio":{"notes":["G4","G4","A4","G4","C5","B4"],"tempo":90}}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada ideia ao que ela significa.","pairs":[{"left":"Mais vibrações por segundo","right":"Som mais agudo"},{"left":"Teclas à esquerda","right":"Notas mais graves"},{"left":"Volume","right":"Forte ou suave"},{"left":"Timbre","right":"A cor do som (voz ou violão)"}]}]}],"pratiqueSozinho":{"passos":["Laboratório: “Grave ou agudo”, 5 minutos.","Ao ouvir hinos, perceba se cada frase sobe ou desce."],"minutos":5,"frequencia":"Diariamente na primeira semana"},"errosComuns":[{"erro":"Confundir “mais forte” com “mais agudo”.","correcao":"Preste atenção apenas na altura. O exercício toca as notas com o mesmo volume."},{"erro":"Responder antes de ouvir a segunda nota inteira.","correcao":"Espere a nota terminar; repita o áudio quantas vezes precisar."}],"seguranca":["Use volume moderado nos fones de ouvido: a audição também precisa de cuidado.","Faça pausas a cada 15 minutos de exercícios de escuta."],"criterioAvanco":"Acertar pelo menos 70% na avaliação com diferenças de 2 a 5 semitons."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'discriminacao-altura' from public.lessons where slug = 'grave-e-agudo' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:altura-pratica')::uuid, 'altura-pratica', (select id from public.lessons where slug = 'grave-e-agudo'), 'Prática: grande e média diferença', 'A segunda nota é mais aguda ou mais grave?', 'pitch_compare', '{"rounds":8,"minSemitones":5,"maxSemitones":12}'::jsonb, 'discriminacao-altura', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:altura-avaliacao')::uuid, 'altura-avaliacao', (select id from public.lessons where slug = 'grave-e-agudo'), 'Avaliação: grave ou agudo', 'As diferenças agora são menores.', 'pitch_compare', '{"rounds":10,"minSemitones":2,"maxSemitones":5}'::jsonb, 'discriminacao-altura', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:reproducao-de-notas')::uuid, (select id from public.learning_paths where slug = 'percepcao-musical'), 'reproducao-de-notas', 'Reprodução de notas', 'Encontrar no teclado e na voz a nota que você ouviu.', 1, 1, 20, '{"objetivo":"Reproduzir notas isoladas com a voz e encontrá-las no teclado a partir de uma referência.","gancho":"No ensaio, o pianista toca a sua nota e você precisa cantá-la na hora. Vamos ligar o ouvido à voz e ao teclado, passo a passo.","etapas":[{"titulo":"Ouvir, pensar, cantar","tipo":"descobrir","blocos":[{"type":"p","text":"Reproduzir uma nota é ligar o que o ouvido percebe ao que a voz faz. O segredo é a escuta interna: “cantar por dentro” antes de cantar em voz alta."},{"type":"callout","icon":"ouvido","title":"Um segundo de silêncio","text":"Entre ouvir e cantar, faça uma pausa curta e imagine a nota na cabeça. Esse segundo evita o “chute”."},{"type":"order","prompt":"Coloque o caminho na ordem certa.","items":["Ouvir a nota","Cantar por dentro, em silêncio","Cantar em voz alta","Conferir no teclado ou no afinador"]}]},{"titulo":"O mapa do teclado","tipo":"descobrir","blocos":[{"type":"keyboard","from":"C4","to":"C5","highlight":["C4","D4","E4","F4","G4","A4","B4","C5"],"label":"Notas naturais de Dó4 a Dó5"},{"type":"list","items":["Teclas brancas: Dó, Ré, Mi, Fá, Sol, Lá, Si; depois o Dó se repete uma oitava acima.","Teclas pretas: sustenidos (♯) e bemóis (♭).","O dó central do piano é o Dó4."]},{"type":"check","question":"Dó♯ e Ré♭ são…","options":["A mesma tecla preta","Duas teclas diferentes","Uma tecla branca e uma preta"],"answer":0,"explain":"É a mesma tecla, entre o Dó e o Ré, com dois nomes possíveis."}]},{"titulo":"Sua vez: cante o Dó","tipo":"experimentar","blocos":[{"type":"p","text":"Vozes masculinas costumam cantar uma oitava abaixo das femininas. Se for o seu caso, use o botão “Voz grave”."},{"type":"singAlong","instruction":"Ouça o Dó4, cante por dentro e depois cante em “lá”, sustentando.","note":"C4","seconds":3},{"type":"singAlong","instruction":"Agora o Mi4. Mesmo caminho: ouvir, pensar, cantar.","note":"E4","seconds":3}]},{"titulo":"Acima ou abaixo? Perto ou longe?","tipo":"ouvir","blocos":[{"type":"p","text":"Para achar uma nota no teclado, use o Dó como referência. A nota misteriosa está acima ou abaixo dele? Perto ou longe?"},{"type":"compare","prompt":"Em qual opção a segunda nota está mais longe do Dó?","options":[{"label":"Dó4 → Mi4 (perto)","notes":["C4","E4"],"tempo":50},{"label":"Dó4 → Lá4 (mais longe)","notes":["C4","A4"],"tempo":50}],"answer":1,"explain":"Do Dó ao Lá são cinco teclas brancas de distância; do Dó ao Mi, só duas. Perceber a distância encurta a busca."}]},{"titulo":"Desafio: qual é a nota?","tipo":"ouvir","blocos":[{"type":"check","question":"Primeiro o Dó4 de referência, depois a nota misteriosa. Qual é ela?","options":["Ré4","Sol4","Dó5"],"answer":1,"explain":"É o Sol4: acima do Dó, distância média. O Ré seria bem perto e o Dó5 soaria como o mesmo Dó, só mais agudo.","audio":{"notes":["C4","G4"],"tempo":50}},{"type":"keyboard","from":"C4","to":"C5","highlight":["C4"],"label":"Confira: toque o Dó e procure a nota pelas vizinhas"}]},{"titulo":"Bem no centro da nota","tipo":"ouvir","blocos":[{"type":"illustration","name":"onda-afinada","caption":"Afinado: as ondas da voz e da referência se encaixam."},{"type":"compare","prompt":"Qual das duas notas está afinada?","options":[{"label":"Afinada","notes":["C4"]},{"label":"Um pouco abaixo","notes":["C4"],"cents":-35}],"answer":0,"explain":"A outra estava levemente abaixo. Cantar a nota certa é só metade: sustentar no centro dela é a outra metade."},{"type":"toolLink","tool":"afinador","label":"Treinador de afinação: sustente 3 notas e veja se ficam no centro"}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"trueFalse","items":[{"statement":"O jeito mais rápido de achar a nota é testar teclas aleatórias.","answer":false,"explain":"Compare com a referência: acima ou abaixo, perto ou longe. Depois teste as vizinhas."},{"statement":"O dó central do piano é o Dó4.","answer":true,"explain":"Ele é o ponto de partida dos exercícios desta trilha."},{"statement":"Um homem que canta a nota uma oitava abaixo da referência está cantando a mesma nota.","answer":true,"explain":"Mesmo nome, uma oitava abaixo. É o natural para vozes masculinas."}]},{"type":"toolLink","tool":"teclado","label":"Abrir o teclado interativo com nomes das notas"}]}],"pratiqueSozinho":{"passos":["Exercício “Encontre a nota” (5 minutos).","Treinador de afinação: 3 notas sustentadas."],"minutos":8,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Procurar a nota aleatoriamente no teclado.","correcao":"Compare com a referência: acima ou abaixo? Perto ou longe? Depois teste as vizinhas."},{"erro":"Cantar a nota antes de ouvi-la por dentro.","correcao":"Faça um segundo de silêncio entre ouvir e cantar."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Use volume moderado nos fones de ouvido: a audição também precisa de cuidado.","Faça pausas a cada 15 minutos de exercícios de escuta."],"criterioAvanco":"Acertar pelo menos 70% em “Encontre a nota” com notas naturais."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'afinacao-nota' from public.lessons where slug = 'reproducao-de-notas' on conflict do nothing;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'discriminacao-altura' from public.lessons where slug = 'reproducao-de-notas' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:reproducao-cantar')::uuid, 'reproducao-cantar', (select id from public.lessons where slug = 'reproducao-de-notas'), 'Cantar a nota ouvida', 'Ouça e cante sustentando. Com microfone, o sistema estima a afinação.', 'sing_note', '{"rounds":3,"holdSeconds":3}'::jsonb, 'afinacao-nota', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:reproducao-teclado-avaliacao')::uuid, 'reproducao-teclado-avaliacao', (select id from public.lessons where slug = 'reproducao-de-notas'), 'Avaliação: encontre a nota no teclado', 'Ouça o Dó de referência e a nota misteriosa; encontre-a no teclado.', 'note_match', '{"rounds":8,"range":[60,72],"naturalOnly":true}'::jsonb, 'discriminacao-altura', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:intervalos-simples')::uuid, (select id from public.learning_paths where slug = 'percepcao-musical'), 'intervalos-simples', 'Intervalos simples', 'Terças, quintas e oitavas: as distâncias que formam as harmonias.', 2, 1, 25, '{"objetivo":"Reconhecer pelo som e pelo nome os intervalos de terça maior, terça menor, quinta justa e oitava, ascendentes e simultâneos.","gancho":"Toda harmonia bonita do coral é feita de distâncias entre notas. Aprenda a reconhecer quatro delas e você começa a ouvir onde a sua voz se encaixa.","etapas":[{"titulo":"A distância entre duas notas","tipo":"descobrir","blocos":[{"type":"illustration","name":"intervalo-escada","caption":"Intervalo: quantos degraus separam duas notas."},{"type":"p","text":"Intervalo é a distância entre duas notas. Medimos em semitons (cada tecla vizinha) e damos o nome contando as notas da escala: de Dó a Mi há três notas (Dó, Ré, Mi), então é uma terça."},{"type":"check","question":"Contando Dó, Ré, Mi, Fá, Sol: que intervalo há de Dó a Sol?","options":["Quinta","Quarta","Terça","Oitava"],"answer":0,"explain":"São cinco notas, do Dó ao Sol: uma quinta."}]},{"titulo":"Quatro distâncias para conhecer","tipo":"ouvir","blocos":[{"type":"list","items":["Terça menor (3 semitons): Dó → Mi♭ ou Lá → Dó. Som mais introspectivo.","Terça maior (4 semitons): Dó → Mi. Som luminoso.","Quinta justa (7 semitons): Dó → Sol. Som aberto, estável.","Oitava (12 semitons): Dó → Dó. A mesma nota mais aguda."]},{"type":"intervals","root":"C4","semitones":[3,4,7,12]}]},{"titulo":"Luminosa ou introspectiva?","tipo":"ouvir","blocos":[{"type":"compare","prompt":"Ouça as duas terças, uma depois da outra.","options":[{"label":"Terça maior: Dó → Mi","notes":["C4","E4"],"tempo":60},{"label":"Terça menor: Dó → Mi♭","notes":["C4","Eb4"],"tempo":60}],"explain":"Só um semitom de diferença muda o caráter: a maior soa luminosa, a menor mais introspectiva."},{"type":"compare","prompt":"Desafio: agora as notas soam juntas. Qual é a terça maior?","options":[{"label":"Terça menor: Lá + Dó","notes":[["A3","C4"]]},{"label":"Terça maior: Fá + Lá","notes":[["F3","A3"]]}],"answer":1,"explain":"Fá–Lá tem 4 semitons; Lá–Dó tem 3. Pense em acorde maior e acorde menor."}]},{"titulo":"Quinta ou oitava?","tipo":"ouvir","blocos":[{"type":"callout","icon":"ouvido","title":"A pista da oitava","text":"A oitava soa como a mesma nota repetida mais aguda. A quinta soa como duas notas diferentes que combinam muito bem."},{"type":"check","question":"Que intervalo é este?","options":["Terça maior","Quinta justa","Oitava"],"answer":2,"explain":"Dó4 → Dó5: a mesma nota, mais aguda. É a oitava.","audio":{"notes":["C4","C5"],"tempo":60}},{"type":"check","question":"E este?","options":["Terça menor","Quinta justa","Oitava"],"answer":1,"explain":"Ré4 → Lá4: notas diferentes, som aberto e estável. Quinta justa, 7 semitons.","audio":{"notes":["D4","A4"],"tempo":60}}]},{"titulo":"Uma depois da outra, ou juntas?","tipo":"descobrir","blocos":[{"type":"p","text":"Melódico: as notas soam uma depois da outra. Harmônico: soam juntas. Cantar em harmonia é cantar intervalos harmônicos com outras pessoas."},{"type":"compare","prompt":"A mesma quinta, de dois jeitos.","options":[{"label":"Melódica","notes":["C4","G4"],"tempo":60},{"label":"Harmônica","notes":[["C4","G4"]]}],"explain":"Mesmas notas, mesma distância. Muda só se elas soam em sequência ou ao mesmo tempo."},{"type":"staff","clef":"sol","notes":["C4","E4","G4","C5"],"label":"Dó, Mi, Sol e Dó na pauta"}]},{"titulo":"Cante a escada de terças","tipo":"experimentar","blocos":[{"type":"singAlong","instruction":"Cante a nota grave do intervalo: Dó.","note":"C4","seconds":3},{"type":"singAlong","instruction":"Agora a terça maior acima: Mi.","note":"E4","seconds":3},{"type":"timer","instruction":"Cante devagar, em “lá”, as terças da escala de Dó: Dó–Mi, Ré–Fá, Mi–Sol. Homens, uma oitava abaixo.","seconds":30}]},{"titulo":"Intervalos que você já conhece","tipo":"aplicar","blocos":[{"type":"callout","icon":"musica","title":"Memorize com músicas","text":"A quinta justa está em “Brilha, brilha, estrelinha”; a quarta justa, no início de “Graça Excelsa”. Associar intervalos a melodias conhecidas acelera o reconhecimento."},{"type":"check","question":"Ouça o início de “Brilha, brilha”. Que intervalo há entre a segunda e a terceira nota?","options":["Terça maior","Quinta justa","Oitava"],"answer":1,"explain":"Dó–Dó–Sol–Sol: o salto de Dó para Sol é uma quinta justa.","audio":{"notes":["C4","C4","G4","G4","A4","A4","G4"],"tempo":90}},{"type":"harmonyLink","arrangement":"tercas-paralelas","label":"Cante terças paralelas no treinador de harmonia"}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada intervalo ao seu tamanho e exemplo.","pairs":[{"left":"Terça menor","right":"3 semitons (Lá → Dó)"},{"left":"Terça maior","right":"4 semitons (Dó → Mi)"},{"left":"Quinta justa","right":"7 semitons (Dó → Sol)"},{"left":"Oitava","right":"12 semitons (Dó → Dó)"}]}]}],"pratiqueSozinho":{"passos":["Laboratório de intervalos no nível recomendado (5 minutos).","Cante as terças da escala de Dó: Dó–Mi, Ré–Fá, Mi–Sol…"],"minutos":8,"frequencia":"5 vezes por semana"},"errosComuns":[{"erro":"Confundir terça maior e menor.","correcao":"Pense em acorde maior (alegre) e menor (introspectivo). Ouça os dois lado a lado."},{"erro":"Confundir quinta e oitava.","correcao":"A oitava soa como a mesma nota repetida mais aguda; a quinta, como notas diferentes que combinam."}],"seguranca":["Use volume moderado nos fones de ouvido: a audição também precisa de cuidado.","Faça pausas a cada 15 minutos de exercícios de escuta."],"criterioAvanco":"Acertar pelo menos 70% na avaliação com terças, quinta e oitava."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'intervalos' from public.lessons where slug = 'intervalos-simples' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:intervalos-pratica')::uuid, 'intervalos-pratica', (select id from public.lessons where slug = 'intervalos-simples'), 'Prática: terça maior, quinta e oitava', 'Identifique o intervalo ascendente.', 'interval_id', '{"rounds":8,"intervals":[4,7,12],"direction":"asc"}'::jsonb, 'intervalos', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:intervalos-avaliacao')::uuid, 'intervalos-avaliacao', (select id from public.lessons where slug = 'intervalos-simples'), 'Avaliação: intervalos simples', 'Inclui a terça menor e intervalos harmônicos.', 'interval_id', '{"rounds":10,"intervals":[3,4,7,12],"direction":"mixed"}'::jsonb, 'intervalos', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:memoria-de-sequencias')::uuid, (select id from public.learning_paths where slug = 'percepcao-musical'), 'memoria-de-sequencias', 'Memorização de sequências', 'Guardar e reproduzir pequenas melodias.', 3, 1, 20, '{"objetivo":"Memorizar sequências de 3 a 5 notas e reproduzi-las no teclado e com a voz.","gancho":"Já esqueceu a sua voz do arranjo logo depois de ouvi-la? Existe um jeito de guardar melodias que não depende de decorar nota por nota.","etapas":[{"titulo":"Desenho, não nota por nota","tipo":"descobrir","blocos":[{"type":"p","text":"Aprender a sua voz num arranjo depende de memória melódica. A estratégia é perceber o desenho da melodia (sobe, desce, repete), os saltos e a nota de chegada."},{"type":"callout","icon":"ideia","title":"Como um caminho conhecido","text":"Você não decora cada passo até a igreja: lembra das curvas e dos pontos de referência. Com a melodia é igual."},{"type":"check","question":"O que ajuda mais a memorizar uma linha melódica?","options":["Perceber o desenho, os saltos e a nota de chegada","Decorar cada nota isolada","Tocar rápido no teclado até acertar"],"answer":0,"explain":"O desenho organiza a memória. Nota por nota sobrecarrega, e o teclado só confirma o que você já ouviu."}]},{"titulo":"Três desenhos","tipo":"ouvir","blocos":[{"type":"p","text":"Ouça cada sequência e desenhe no ar o caminho com o dedo."},{"type":"audio","label":"Sobe por graus: Dó–Ré–Mi","notes":["C4","D4","E4"],"tempo":84},{"type":"audio","label":"Com repetição: Sol–Sol–Mi–Dó","notes":["G4","G4","E4","C4"],"tempo":84},{"type":"audio","label":"Com salto: Dó–Sol–Mi–Ré","notes":["C4","G4","E4","D4"],"tempo":84},{"type":"illustration","name":"intervalo-escada","caption":"Grau: degrau vizinho. Salto: pula degraus."}]},{"titulo":"Que desenho é esse?","tipo":"ouvir","blocos":[{"type":"check","question":"Qual é o desenho desta sequência?","options":["Repete e depois desce","Sobe, sobe","Desce e depois sobe"],"answer":0,"explain":"Sol–Sol–Mi–Dó: duas notas iguais e depois desce até o Dó.","audio":{"notes":["G4","G4","E4","C4"],"tempo":84}},{"type":"compare","prompt":"Qual das duas sequências tem um salto?","options":[{"label":"Só graus: Dó–Ré–Mi–Ré","notes":["C4","D4","E4","D4"],"tempo":84},{"label":"Com salto: Dó–Sol–Mi–Ré","notes":["C4","G4","E4","D4"],"tempo":84}],"answer":1,"explain":"De Dó para Sol a melodia pula vários degraus. Saltos são ótimos pontos de referência para a memória."}]},{"titulo":"O método em quatro passos","tipo":"descobrir","blocos":[{"type":"order","prompt":"Coloque os passos na ordem certa.","items":["Ouvir uma vez só observando o desenho","Ouvir de novo cantando por dentro","Cantar em voz alta, em “lá” ou com os nomes das notas","Procurar no teclado a partir da primeira nota"]},{"type":"tip","title":"O teclado vem por último","text":"Cante primeiro; o teclado confirma o que você já sabe."}]},{"titulo":"Sua vez: Dó–Ré–Mi","tipo":"experimentar","blocos":[{"type":"singAlong","instruction":"A primeira nota é Dó. Cante-a em “lá” para se localizar.","note":"C4","seconds":3},{"type":"timer","instruction":"Cante Dó–Ré–Mi em “lá” e depois com os nomes. Desenhe no ar: sobe, sobe.","seconds":15,"reps":2},{"type":"keyboard","from":"C4","to":"G4","highlight":["C4"],"label":"Agora toque a sequência a partir do Dó destacado"}]},{"titulo":"Desafio de memória","tipo":"ouvir","blocos":[{"type":"audio","label":"Modelo: ouça bem e guarde","notes":["C4","E4","G4","E4"],"tempo":84},{"type":"compare","prompt":"Sem voltar ao modelo: qual opção repete exatamente o que você ouviu?","options":[{"label":"Dó–Mi–Lá–Mi","notes":["C4","E4","A4","E4"],"tempo":84},{"label":"Dó–Mi–Sol–Mi (igual ao modelo)","notes":["C4","E4","G4","E4"],"tempo":84},{"label":"Dó–Mi–Sol–Dó","notes":["C4","E4","G4","C4"],"tempo":84}],"answer":1,"explain":"Sobe, sobe, desce um degrau e chega no Mi. Lembrar do ponto mais agudo e da nota de chegada resolve."}]},{"titulo":"No ensaio","tipo":"aplicar","blocos":[{"type":"illustration","name":"escuta-ativa","caption":"Ouça primeiro, cante depois."},{"type":"check","question":"O regente toca a linha do seu naipe uma vez. O que fazer antes de cantar?","options":["Observar o desenho e a nota de chegada, cantando por dentro","Cantar junto logo de primeira, bem forte","Esperar o naipe ao lado cantar e imitar"],"answer":0,"explain":"Ouvir com atenção ao desenho é o que faz a linha ficar na memória."}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"trueFalse","items":[{"statement":"Memorizar nota por nota é o jeito mais eficiente.","answer":false,"explain":"Memorize o desenho e os pontos de chegada."},{"statement":"Saltos e notas repetidas ajudam a guardar a melodia.","answer":true,"explain":"Eles funcionam como pontos de referência no caminho."},{"statement":"Tocar rápido no teclado acelera a memorização.","answer":false,"explain":"Cante primeiro e vá devagar: o teclado só confirma."}]}]}],"pratiqueSozinho":{"passos":["Laboratório: memória melódica (5 minutos).","Escolha um trecho curto de um hino e aprenda de ouvido, sem partitura."],"minutos":8,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Tentar memorizar nota por nota.","correcao":"Memorize o desenho e os pontos de chegada."},{"erro":"Tocar rápido demais no teclado.","correcao":"Cante primeiro; o teclado confirma o que você já sabe."}],"seguranca":["Use volume moderado nos fones de ouvido: a audição também precisa de cuidado.","Faça pausas a cada 15 minutos de exercícios de escuta."],"criterioAvanco":"Acertar pelo menos 70% das notas em sequências de 4 notas."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'memoria-melodica' from public.lessons where slug = 'memoria-de-sequencias' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:memoria-pratica')::uuid, 'memoria-pratica', (select id from public.lessons where slug = 'memoria-de-sequencias'), 'Prática: sequências de 3 notas', 'Ouça e reproduza no teclado.', 'melody_memory', '{"rounds":5,"minLength":3,"maxLength":3,"maxLeap":2}'::jsonb, 'memoria-melodica', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:memoria-avaliacao')::uuid, 'memoria-avaliacao', (select id from public.lessons where slug = 'memoria-de-sequencias'), 'Avaliação: sequências de 4 notas', 'Ouça e reproduza no teclado.', 'melody_memory', '{"rounds":5,"minLength":4,"maxLength":4,"maxLeap":3}'::jsonb, 'memoria-melodica', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:ritmo-e-pulsacao')::uuid, (select id from public.learning_paths where slug = 'percepcao-musical'), 'ritmo-e-pulsacao', 'Ritmo e pulsação', 'Sentir o pulso e reproduzir padrões rítmicos.', 4, 1, 20, '{"objetivo":"Sentir a pulsação, manter o andamento e reproduzir padrões rítmicos simples com semínimas, mínimas e colcheias.","gancho":"Num grupo, entrar meio tempo atrasado aparece tanto quanto desafinar. Vamos colocar o pulso da música no seu corpo.","etapas":[{"titulo":"O coração da música","tipo":"descobrir","blocos":[{"type":"illustration","name":"pulso","caption":"Batidas regulares, como um coração."},{"type":"p","text":"Pulsação é a batida regular que sentimos na música: a que marcamos com o pé. Ouça e bata o pé junto."},{"type":"rhythm","pattern":"q q q q","bpm":80,"label":"Quatro semínimas: uma em cada pulso"}]},{"titulo":"Pulso, andamento e ritmo","tipo":"descobrir","blocos":[{"type":"p","text":"O andamento é a velocidade da pulsação, medida em batidas por minuto (bpm). O ritmo é a combinação de durações curtas e longas sobre a pulsação."},{"type":"compare","prompt":"Qual das duas tem o andamento mais rápido?","options":[{"label":"100 bpm","notes":["C4","C4","C4","C4"],"tempo":100},{"label":"60 bpm","notes":["C4","C4","C4","C4"],"tempo":60}],"answer":0,"explain":"Mais batidas por minuto, pulso mais rápido. As notas são as mesmas: só muda a velocidade."}]},{"titulo":"Longas e curtas","tipo":"ouvir","blocos":[{"type":"illustration","name":"figuras-ritmicas"},{"type":"list","items":["Semínima: dura 1 tempo.","Mínima: dura 2 tempos.","Colcheia: dura meio tempo (duas colcheias por tempo)."]},{"type":"rhythm","pattern":"h h","bpm":80,"label":"Duas mínimas"},{"type":"rhythm","pattern":"q e e q q","bpm":80,"label":"Semínima, duas colcheias, duas semínimas"}]},{"titulo":"Fale o ritmo","tipo":"experimentar","blocos":[{"type":"toolLink","tool":"metronomo","label":"Abrir o metrônomo em 80 bpm"},{"type":"timer","instruction":"Bata o pé em cada clique e fale “tá” em cada tempo (semínimas).","seconds":20},{"type":"timer","instruction":"Agora “tá-a”, segurando dois tempos (mínimas). O pé continua batendo.","seconds":20},{"type":"timer","instruction":"Agora “ti-ti”: duas colcheias dentro de cada tempo, sem acelerar o pé.","seconds":20}]},{"titulo":"Conte os tempos","tipo":"checar","blocos":[{"type":"check","question":"Quantas semínimas cabem numa mínima?","options":["Duas","Uma","Quatro"],"answer":0,"explain":"A mínima dura 2 tempos; cada semínima, 1.","illustration":"figuras-ritmicas"},{"type":"check","question":"Quando aparecem colcheias, o que acontece com o pulso?","options":["Continua igual; as colcheias cabem dentro do tempo","Acelera junto com elas","Fica mais lento"],"answer":0,"explain":"As notas curtas dividem o tempo, mas o pé segue no mesmo andamento."}]},{"titulo":"O compasso 4/4","tipo":"ouvir","blocos":[{"type":"illustration","name":"compasso","caption":"Quatro tempos por compasso; o 1 é o mais forte."},{"type":"p","text":"No compasso 4/4 contamos quatro tempos, e o primeiro é o mais forte. Conte em voz alta: UM, dois, três, quatro."},{"type":"rhythm","pattern":"q q h","bpm":80,"label":"Duas semínimas e uma mínima: um compasso completo"}]},{"titulo":"Entradas seguras no ensaio","tipo":"aplicar","blocos":[{"type":"callout","icon":"coracao","title":"Cantar junto começa no ritmo","text":"Sentir a pulsação no corpo (pé, mão) dá segurança para as entradas. O pulso é o mesmo para todos os naipes."},{"type":"check","question":"O regente marca quatro tempos antes da entrada do coral. O que fazer?","options":["Sentir o pulso desde a marcação e entrar junto no tempo certo","Esperar ouvir alguém começar e então entrar","Entrar quando se sentir pronto(a)"],"answer":0,"explain":"Quem espera os outros entra atrasado. Quem já está no pulso entra junto."}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada termo ao seu significado.","pairs":[{"left":"Pulsação","right":"Batida regular da música"},{"left":"Andamento","right":"Velocidade, em bpm"},{"left":"Mínima","right":"Dura 2 tempos"},{"left":"Colcheia","right":"Dura meio tempo"}]}]}],"pratiqueSozinho":{"passos":["Metrônomo: bata o pé por 1 minuto em 60, 80 e 100 bpm.","Laboratório de ritmo (5 minutos)."],"minutos":7,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Acelerar nas notas curtas.","correcao":"As colcheias cabem dentro do tempo: o pulso não muda."},{"erro":"Encurtar notas longas.","correcao":"Conte mentalmente os tempos das mínimas até o fim."}],"seguranca":["Use volume moderado nos fones de ouvido: a audição também precisa de cuidado.","Faça pausas a cada 15 minutos de exercícios de escuta."],"criterioAvanco":"Acertar pelo menos 70% na avaliação de padrões rítmicos."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'ritmo-pulsacao' from public.lessons where slug = 'ritmo-e-pulsacao' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:ritmo-pratica')::uuid, 'ritmo-pratica', (select id from public.lessons where slug = 'ritmo-e-pulsacao'), 'Prática: semínimas e mínimas', 'Ouça a contagem e o ritmo; depois toque o mesmo ritmo.', 'rhythm_tap', '{"rounds":4,"patterns":["q q q q","h h","q q h","h q q"],"bpm":80}'::jsonb, 'ritmo-pulsacao', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:ritmo-avaliacao')::uuid, 'ritmo-avaliacao', (select id from public.lessons where slug = 'ritmo-e-pulsacao'), 'Avaliação: padrões com colcheias', 'Reproduza os padrões tocando no botão.', 'rhythm_tap', '{"rounds":5,"patterns":["q e e q q","e e q h","q q e e q","h e e q","q e e e e q"],"bpm":76}'::jsonb, 'ritmo-pulsacao', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:acordes-basicos')::uuid, (select id from public.learning_paths where slug = 'percepcao-musical'), 'acordes-basicos', 'Reconhecimento de acordes básicos', 'Maior, menor e as notas extremas de um acorde.', 5, 2, 25, '{"objetivo":"Distinguir acordes maiores e menores, ouvir a nota mais grave e a mais aguda de um acorde e reconhecer consonância e dissonância.","gancho":"Quando o coral canta junto, cada voz é uma peça do acorde. Vamos aprender a ouvir o acorde inteiro e achar o seu lugar dentro dele.","etapas":[{"titulo":"Três notas, um acorde","tipo":"descobrir","blocos":[{"type":"illustration","name":"triade","caption":"Fundamental, terça e quinta empilhadas."},{"type":"p","text":"Um acorde é a combinação de três ou mais notas soando juntas. A tríade básica tem fundamental, terça e quinta."},{"type":"audio","label":"Dó maior: notas separadas e depois juntas","notes":["C4","E4","G4",["C4","E4","G4"]],"tempo":70}]},{"titulo":"A terça decide","tipo":"ouvir","blocos":[{"type":"p","text":"O que muda entre maior e menor é a terça: maior fica 4 semitons acima da fundamental; menor, 3 semitons. Fundamental e quinta não mudam."},{"type":"chords","root":"C4","qualities":["maior","menor"]},{"type":"compare","prompt":"Compare Dó maior e Dó menor: só uma nota muda.","options":[{"label":"Dó maior: Dó–Mi–Sol","notes":[["C4","E4","G4"]]},{"label":"Dó menor: Dó–Mi♭–Sol","notes":[["C4","Eb4","G4"]]}],"explain":"O Mi desce meio-tom para Mi♭ e o acorde muda de cor."}]},{"titulo":"Desafio: maior ou menor?","tipo":"ouvir","blocos":[{"type":"compare","prompt":"Qual destes acordes é maior?","options":[{"label":"Ré menor","notes":[["D4","F4","A4"]]},{"label":"Fá maior","notes":[["F3","A3","C4"]]}],"answer":1,"explain":"Fá–Lá tem 4 semitons: terça maior. Ré–Fá tem 3: terça menor."},{"type":"check","question":"E este acorde, é maior ou menor?","options":["Maior","Menor"],"answer":1,"explain":"Lá–Dó–Mi: de Lá a Dó são 3 semitons, terça menor. É Lá menor.","audio":{"notes":["A3","C4","E4",["A3","C4","E4"]],"tempo":70}}]},{"titulo":"Cante as notas do acorde","tipo":"experimentar","blocos":[{"type":"audio","label":"Lá menor arpejado e em bloco","notes":["A3","C4","E4",["A3","C4","E4"]],"tempo":70},{"type":"singAlong","instruction":"Cante a fundamental: Lá.","note":"A3","seconds":3},{"type":"timer","instruction":"Cante devagar, em “lá”, as três notas: Lá–Dó–Mi, e depois de volta. Sem esforço.","seconds":20},{"type":"singAlong","instruction":"Agora sustente a quinta, a nota mais aguda do acorde: Mi.","note":"E4","seconds":3}]},{"titulo":"A mais grave e a mais aguda","tipo":"ouvir","blocos":[{"type":"p","text":"No grupo, a nota mais grave costuma ser do baixo, e a mais aguda, da melodia. Ouvi-las ajuda você a se localizar: “minha nota está no meio, acima do baixo”."},{"type":"compare","prompt":"Cada opção toca o acorde e depois uma nota. Qual nota é a mais grave do acorde?","options":[{"label":"Mi, a do meio","notes":[["C4","E4","G4"],"E4"],"tempo":60},{"label":"Dó, a mais grave","notes":[["C4","E4","G4"],"C4"],"tempo":60},{"label":"Sol, a mais aguda","notes":[["C4","E4","G4"],"G4"],"tempo":60}],"answer":1,"explain":"O Dó é a base. Dica: enquanto o acorde soa, cante baixinho a nota que você acha que é a mais grave."}]},{"titulo":"Repouso e tensão","tipo":"descobrir","blocos":[{"type":"list","items":["Consonâncias soam estáveis: oitava, quinta, terças, sextas.","Dissonâncias soam tensas e pedem resolução: segundas, sétimas, trítono."]},{"type":"intervals","root":"C4","semitones":[2,4,7,11]},{"type":"trueFalse","items":[{"statement":"Dissonância é sempre um erro.","answer":false,"explain":"Ela cria movimento e tensão na música. Mas uma dissonância fora do lugar indica que alguém saiu da própria nota."},{"statement":"A quinta justa é uma consonância.","answer":true,"explain":"Soa aberta e estável."},{"statement":"Acorde menor é sempre triste.","answer":false,"explain":"O caráter depende do contexto. Use a terça como referência, não a emoção."}]}]},{"titulo":"Alguém saiu da nota?","tipo":"aplicar","blocos":[{"type":"compare","prompt":"Três vozes cantam Dó maior. Em qual versão alguém saiu da própria nota?","options":[{"label":"Todos certos: Dó–Mi–Sol","notes":[["C4","E4","G4"]]},{"label":"Alguém cantou Fá♯ em vez de Sol","notes":[["C4","E4","F#4"]]}],"answer":1,"explain":"O Fá♯ cria uma tensão que não estava no acorde. É esse “atrito” que você aprende a notar no ensaio."},{"type":"harmonyLink","arrangement":"triades-tres-vozes","label":"Cante tríades a três vozes no treinador de harmonia"}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada termo ao seu significado.","pairs":[{"left":"Acorde maior","right":"Terça de 4 semitons"},{"left":"Acorde menor","right":"Terça de 3 semitons"},{"left":"Consonância","right":"Som estável"},{"left":"Dissonância","right":"Som tenso, pede resolução"}]}]}],"pratiqueSozinho":{"passos":["Laboratório de acordes no nível recomendado.","Laboratório de consonância e dissonância."],"minutos":8,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Achar que acorde menor é “triste” sempre.","correcao":"O caráter depende do contexto; use a terça como referência, não a emoção."},{"erro":"Perder a nota grave quando o acorde é longo.","correcao":"Cante baixinho a nota que você acha que é a mais grave enquanto o acorde soa."}],"seguranca":["Use volume moderado nos fones de ouvido: a audição também precisa de cuidado.","Faça pausas a cada 15 minutos de exercícios de escuta."],"criterioAvanco":"Acertar pelo menos 70% nas avaliações de tipo de acorde e de nota extrema."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
