insert into public.lesson_skills (lesson_id, skill_slug) select id, 'consonancia' from public.lessons where slug = 'acordes-basicos' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:acordes-maior-menor-avaliacao')::uuid, 'acordes-maior-menor-avaliacao', (select id from public.lessons where slug = 'acordes-basicos'), 'Avaliação: maior ou menor?', 'Ouça o acorde arpejado e em bloco.', 'chord_quality', '{"rounds":8,"qualities":["maior","menor"],"play":"ambos"}'::jsonb, 'acordes', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:acordes-extremos-avaliacao')::uuid, 'acordes-extremos-avaliacao', (select id from public.lessons where slug = 'acordes-basicos'), 'Avaliação: a nota mais grave', 'Ouça o acorde e escolha qual opção é a nota mais grave dele.', 'chord_extreme', '{"rounds":6,"ask":"grave","size":3}'::jsonb, 'acordes', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:consonancia-pratica')::uuid, 'consonancia-pratica', (select id from public.lessons where slug = 'acordes-basicos'), 'Prática: consonante ou dissonante?', 'Ouça as duas notas juntas.', 'consonance', '{"rounds":8}'::jsonb, 'consonancia', 'pratica', 2, 2) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.learning_paths (id, slug, code, title, subtitle, description, icon, sort) values (md5('path:canto-em-conjunto')::uuid, 'canto-em-conjunto', 'C', 'Canto em conjunto', 'Do uníssono à escuta ativa', 'Antes de dividir vozes, o grupo aprende a soar como um só: mesma altura, mesmo ritmo, entradas e cortes juntos, equilíbrio e escuta. A trilha termina com o desafio de manter a própria linha enquanto outras melodias soam.', 'users', 2) on conflict (slug) do update set code = excluded.code, title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, icon = excluded.icon, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:unissono')::uuid, (select id from public.learning_paths where slug = 'canto-em-conjunto'), 'unissono', 'Uníssono', 'Cantar a mesma melodia como uma só voz.', 0, 1, 20, '{"objetivo":"Cantar a mesma melodia com unidade de altura, ritmo, respiração, dicção e finalização.","gancho":"Vinte pessoas, vinte timbres, uma melodia. Será que dá para soar como uma voz só? Dá, e o segredo está mais nos ouvidos do que na garganta.","etapas":[{"titulo":"Muitas vozes, um só som","tipo":"descobrir","blocos":[{"type":"illustration","name":"unissono","caption":"Todos na mesma melodia, como uma voz só."},{"type":"p","text":"Uníssono é quando todos cantam a mesma melodia. Parece fácil, mas cada pessoa tem um timbre, um volume e um jeito de pronunciar."},{"type":"callout","icon":"ideia","title":"Pense num remo","text":"Num barco a remo, ninguém ganha remando mais forte que os outros. O barco anda quando todos remam juntos, no mesmo ritmo."},{"type":"check","question":"Qual é o objetivo do uníssono num grupo?","options":["Soar como uma única voz bem afinada","Cada um mostrar o seu timbre","Quem tem a voz mais forte puxar o grupo"],"answer":0,"explain":"No uníssono, o resultado é uma voz só. Quem se destaca quebra a unidade."}]},{"titulo":"Desafio: uma voz ou duas?","tipo":"ouvir","blocos":[{"type":"compare","prompt":"Duas pessoas tentam cantar a mesma nota. Em qual opção elas estão em uníssono?","options":[{"label":"uníssono: as duas na mesma nota","notes":[["A3","A3"]],"mode":"chord","tempo":40},{"label":"uma delas um pouco acima (25 cents)","notes":[["A3","A3"]],"voiceCents":[0,25],"mode":"chord","tempo":40}],"answer":0,"explain":"No uníssono as vozes se fundem num som liso. Quando uma escapa só um pouquinho, aparece um “balanço” (uá-uá-uá): são as ondas batendo uma na outra. Quanto mais lento o balanço, mais perto da afinação."},{"type":"illustration","name":"onda-desafinada","caption":"Ondas desencontradas: o som “treme”."},{"type":"compare","prompt":"O grupo está cantando A3. Qual destas entradas combina com o grupo?","options":[{"label":"afinada","notes":["A3"]},{"label":"um pouco abaixo","notes":["A3"],"cents":-35}],"answer":0,"explain":"A diferença é pequena, mas o ouvido percebe. Quem ouve o grupo se ajusta ao som dele, não o contrário."}]},{"titulo":"Homens e mulheres juntos","tipo":"ouvir","blocos":[{"type":"p","text":"Quando homens e mulheres cantam “em uníssono”, na verdade cantam em oitavas: a mesma melodia, os homens uma oitava abaixo. Para o grupo, isso também é uníssono."},{"type":"audio","label":"Mesma melodia em oitavas (vozes femininas e masculinas)","notes":[["E4","E3"],["E4","E3"],["F4","F3"],["G4","G3"]],"tempo":90},{"type":"check","question":"Os homens cantam a melodia uma oitava abaixo das mulheres. O grupo está…","options":["Em uníssono (em oitavas)","Em duas vozes diferentes","Desafinado","Cantando em terças"],"answer":0,"explain":"É a mesma melodia, só que na região de cada voz. O ouvido reconhece como “a mesma música”."}]},{"titulo":"As cinco combinações do grupo","tipo":"descobrir","blocos":[{"type":"match","prompt":"Ligue cada combinação ao que o grupo faz.","pairs":[{"left":"Mesma altura","right":"Ouvir o vizinho e se ajustar ao grupo"},{"left":"Mesmo ritmo","right":"Sílabas juntas, seguindo o regente"},{"left":"Mesma respiração","right":"Todos respiram no lugar combinado"},{"left":"Mesma vogal","right":"Mesmo formato de boca nas notas longas"},{"left":"Mesmo corte","right":"A nota termina no gesto do regente"}]},{"type":"tip","title":"Volume a serviço do grupo","text":"Só ouve a sua voz? Está forte demais. Não ouve nada da sua voz? Talvez esteja fraco demais. O ponto certo é ouvir a si e aos vizinhos."}]},{"titulo":"Sua vez: cante junto","tipo":"experimentar","blocos":[{"type":"singAlong","instruction":"Imagine que a nota é o som do grupo. Cante “lu” junto, suave, até sentir que as duas viram uma só.","note":"C4","seconds":4},{"type":"harmonyLink","arrangement":"hino-alegria-unissono","label":"Praticar o “Hino da Alegria” em uníssono no treinador"},{"type":"checklist","title":"No treinador","items":["Ouvi a melodia no modo solo","Cantei junto em “lu”, depois com o texto","Marquei a respiração no fim de cada linha","A última nota durou até o fim do tempo 4"]}]},{"titulo":"No ensaio de domingo","tipo":"aplicar","blocos":[{"type":"illustration","name":"regente","caption":"O corte acontece no gesto do regente."},{"type":"check","question":"No último verso do hino, metade do grupo solta a nota e a outra metade continua. O que resolve?","options":["Todos olharem o regente e cortarem no gesto dele","Cada um cortar quando o ar acabar","Seguir quem canta mais alto","Encurtar a nota para garantir"],"answer":0,"explain":"A finalização é combinada: o fim da nota e a consoante final acontecem juntos, no gesto do regente."},{"type":"trueFalse","items":[{"statement":"Cantar mais forte que o grupo “ajuda” o uníssono.","answer":false,"explain":"No uníssono, quem se destaca quebra a unidade. Ajude ouvindo e se ajustando."},{"statement":"Nas notas longas, o grupo combina a vogal e o formato da boca.","answer":true,"explain":"Vogais diferentes deixam o som “espalhado”, mesmo com todos afinados."}]}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada problema à sua correção.","pairs":[{"left":"Cantar mais forte para ajudar","right":"Ouvir os vizinhos e se ajustar"},{"left":"Cada um termina num momento","right":"Cortar no gesto do regente"},{"left":"Vogais diferentes na nota longa","right":"Combinar vogal e formato da boca"},{"left":"Respirar cada um num lugar","right":"Marcar a respiração na letra"}]}]}],"pratiqueSozinho":{"passos":["Treinador de harmonia: uníssono, 3 repetições.","Grave-se cantando junto com a referência e confira se as sílabas começam juntas."],"minutos":8,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Cantar mais forte que o grupo para “ajudar”.","correcao":"No uníssono, quem se destaca quebra a unidade. Ajude ouvindo e se ajustando."},{"erro":"Cada um terminar a nota num momento.","correcao":"O corte é um gesto do regente; olhe para ele nas finalizações."},{"erro":"Vogais diferentes nas notas longas.","correcao":"Combinem a vogal e o formato da boca."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e cantar o uníssono no treinador do início ao fim."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'canto-unissono' from public.lessons where slug = 'unissono' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:unissono-pratica-treinador')::uuid, 'unissono-pratica-treinador', (select id from public.lessons where slug = 'unissono'), 'Prática no treinador de harmonia', 'Cante o Hino da Alegria em uníssono e avalie.', 'harmony_part', '{"voices":1,"arrangementSlug":"hino-alegria-unissono"}'::jsonb, 'canto-unissono', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:unissono-avaliacao')::uuid, 'unissono-avaliacao', (select id from public.lessons where slug = 'unissono'), 'Avaliação: princípios do uníssono', 'Responda sobre canto em uníssono.', 'quiz', '{"questions":[{"q":"Homens e mulheres cantando a mesma melodia, os homens uma oitava abaixo, estão…","options":["Em uníssono (oitavas)","Em duas vozes diferentes","Desafinados","Em terças"],"answer":0},{"q":"Se você só ouve a sua própria voz no grupo, provavelmente…","options":["Está cantando forte demais","Está cantando perfeitamente","Precisa cantar mais forte","Está fora do ritmo"],"answer":0},{"q":"Quem define o momento da finalização?","options":["O regente, com o gesto de corte","Quem canta mais alto","Cada pessoa","O instrumentista"],"answer":0},{"q":"Para unificar o som nas notas longas, o naipe deve combinar…","options":["A vogal e o formato da boca","O volume máximo","A posição dos pés","A cor da roupa"],"answer":0},{"q":"Ouça: as duas notas formam uníssono (a mesma nota) ou não?","options":["Uníssono","Notas diferentes"],"answer":0,"audio":{"notes":[["G4","G4"]],"mode":"chord","tempo":40}}]}'::jsonb, 'canto-unissono', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:entradas-e-finalizacoes')::uuid, (select id from public.learning_paths where slug = 'canto-em-conjunto'), 'entradas-e-finalizacoes', 'Entradas e finalizações', 'Começar e terminar juntos, no tempo certo.', 1, 1, 15, '{"objetivo":"Entrar no tempo exato após pausas e contagens e finalizar as notas juntos, respeitando a duração escrita.","gancho":"O teclado faz a introdução, o regente levanta a mão… e metade do coral entra atrasada. Vamos garantir que, com você, isso não aconteça.","etapas":[{"titulo":"O momento mais exposto","tipo":"descobrir","blocos":[{"type":"illustration","name":"regente","caption":"Respiração e entrada no gesto do regente."},{"type":"p","text":"Na entrada, todo mundo percebe quem chegou cedo ou tarde. Uma entrada segura nasce de três coisas: contar a pausa, respirar no tempo anterior e já “ouvir por dentro” a primeira nota."},{"type":"check","question":"Qual destas NÃO faz parte de uma entrada segura?","options":["Esperar o vizinho começar para ir junto","Contar os tempos da pausa","Respirar no tempo anterior à entrada","Ter a primeira nota pronta na mente"],"answer":0,"explain":"Quem espera o vizinho entra sempre um pouco atrasado. A referência é a contagem e o regente."}]},{"titulo":"A pausa também é música","tipo":"ouvir","blocos":[{"type":"callout","icon":"ouvido","title":"Silêncio contado","text":"Durante a pausa, a música continua. Conte mentalmente “1, 2, 3, 4” no andamento, como se estivesse cantando."},{"type":"rhythm","pattern":"rq q q q","bpm":80,"label":"Entrada após pausa de um tempo"},{"type":"rhythm","pattern":"rh q q","bpm":80,"label":"Entrada após pausa de dois tempos"},{"type":"reveal","prompt":"No segundo padrão, em que tempo acontece a entrada?","answer":"No tempo 3. A pausa de dois tempos ocupa o 1 e o 2. A respiração acontece no tempo 2."}]},{"titulo":"Sua vez: palma e entrada","tipo":"experimentar","blocos":[{"type":"toolLink","tool":"metronomo","label":"Abra o metrônomo a 80 bpm"},{"type":"timer","instruction":"Conte em voz alta “1, 2, 3, 4” e bata palma apenas no tempo 2.","seconds":30},{"type":"timer","instruction":"Inspire no tempo 1 e cante “lá” no tempo 2, sustentando até o fim do tempo 4. Depois, tente entrando no tempo 3.","seconds":30,"reps":2}]},{"titulo":"Até onde vai a última nota?","tipo":"descobrir","blocos":[{"type":"rhythm","pattern":"q q h","bpm":80,"label":"Finalização em mínima (dura até o fim do compasso)"},{"type":"illustration","name":"compasso","caption":"Em 4/4, cada compasso tem quatro tempos."},{"type":"check","question":"Em 4/4, uma mínima que começa no tempo 3 termina…","options":["No início do próximo compasso","No tempo 4","No tempo 3 e meio","Quando faltar ar"],"answer":0,"explain":"A mínima vale dois tempos: o 3 e o 4 inteiros. Encurtar a última nota é tão perceptível quanto atrasar a entrada."}]},{"titulo":"Ouça por dentro antes de cantar","tipo":"experimentar","blocos":[{"type":"p","text":"A primeira nota precisa estar pronta na mente. No ensaio, peça a nota ao instrumentista ou use a nota de referência."},{"type":"singAlong","instruction":"Ouça a nota. Conte “1, 2, 3” em silêncio, respire no 4 e entre no próximo 1 com “lá”.","note":"C4","seconds":4}]},{"titulo":"No culto","tipo":"aplicar","blocos":[{"type":"check","question":"O teclado toca quatro compassos de introdução antes de o coral entrar. O que você faz?","options":["Conto os compassos e respiro no tempo anterior à entrada","Respiro fundo no começo da introdução e seguro o ar","Espero ouvir os outros para entrar","Entro quando o teclado parar"],"answer":0,"explain":"Contando, você sabe exatamente quando entrar. A respiração faz parte do ritmo: no tempo anterior, no andamento da música."},{"type":"trueFalse","items":[{"statement":"Respirar bem cedo e prender o ar até a entrada deixa a entrada mais segura.","answer":false,"explain":"Prender o ar gera tensão. Inspire no tempo anterior, no andamento."},{"statement":"A finalização é tão importante quanto a entrada.","answer":true,"explain":"Conte até o fim da última nota e corte junto com o grupo."}]}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"order","prompt":"Coloque em ordem: do silêncio até o fim da frase.","items":["Ouvir a primeira nota por dentro","Contar os tempos da pausa","Respirar no tempo anterior","Entrar junto, no tempo","Sustentar a última nota e cortar no gesto"]}]}],"pratiqueSozinho":{"passos":["Exercício de entradas (5 minutos).","Em um hino conhecido, conte as pausas entre as frases em voz baixa."],"minutos":6,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Respirar cedo demais e prender o ar até a entrada.","correcao":"A respiração faz parte do ritmo: inspire no tempo anterior."},{"erro":"Encurtar a última nota.","correcao":"Conte até o fim; a finalização é tão importante quanto a entrada."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo."],"criterioAvanco":"Acertar pelo menos 70% na avaliação de entradas após pausas."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'ritmo-pulsacao' from public.lessons where slug = 'entradas-e-finalizacoes' on conflict do nothing;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'canto-unissono' from public.lessons where slug = 'entradas-e-finalizacoes' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:entradas-avaliacao')::uuid, 'entradas-avaliacao', (select id from public.lessons where slug = 'entradas-e-finalizacoes'), 'Avaliação: entradas após pausas', 'Ouça a contagem; toque somente onde há nota (as pausas ficam em silêncio).', 'rhythm_tap', '{"rounds":5,"patterns":["rq q q q","rh q q","rq q h","q rq q q","rh h"],"bpm":80,"toleranceMs":140}'::jsonb, 'ritmo-pulsacao', 'avaliacao', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:finalizacoes-avaliacao')::uuid, 'finalizacoes-avaliacao', (select id from public.lessons where slug = 'entradas-e-finalizacoes'), 'Avaliação: duração das finalizações', 'Responda sobre entradas e finalizações.', 'quiz', '{"questions":[{"q":"Em 4/4, uma mínima que começa no tempo 3 termina…","options":["No início do próximo compasso","No tempo 4","No tempo 3 e meio","Quando faltar ar"],"answer":0},{"q":"Quando respirar para uma entrada no tempo 2?","options":["No tempo 1, no andamento da música","Dois compassos antes","Durante o tempo 2","Não é preciso respirar"],"answer":0},{"q":"O que fazer durante uma pausa longa?","options":["Contar os tempos mentalmente","Conversar com o vizinho","Esperar o vizinho começar","Cantar baixinho"],"answer":0}]}'::jsonb, 'canto-unissono', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:equilibrio-sonoro')::uuid, (select id from public.learning_paths where slug = 'canto-em-conjunto'), 'equilibrio-sonoro', 'Equilíbrio sonoro', 'Nenhuma voz sobrando, nenhuma faltando.', 2, 2, 15, '{"objetivo":"Compreender o equilíbrio entre naipes e entre vozes do mesmo naipe, e ajustar a própria intensidade ao conjunto.","gancho":"Já reparou quando uma única voz “fura” o coral inteiro? Equilíbrio é a arte de ninguém sobrar e ninguém faltar. Vamos treinar o ouvido para isso.","etapas":[{"titulo":"Uma balança de vozes","tipo":"descobrir","blocos":[{"type":"illustration","name":"equilibrio","caption":"Equilíbrio: a proporção de volume entre as vozes."},{"type":"p","text":"A melodia precisa ser ouvida com clareza. O baixo sustenta a harmonia. As vozes do meio preenchem o acorde sem encobrir a melodia. E, dentro de um naipe, nenhuma voz individual se destaca."},{"type":"check","question":"Num hino a quatro vozes, o que precisa ficar mais claro para quem ouve?","options":["A melodia","A voz de quem canta mais forte","As vozes do meio","Nenhuma voz em especial"],"answer":0,"explain":"A congregação reconhece o hino pela melodia. As outras vozes a enriquecem, sem cobri-la."}]},{"titulo":"Desafio: onde está a melodia?","tipo":"ouvir","blocos":[{"type":"audio","label":"Acorde equilibrado (todas as vozes com o mesmo volume)","notes":[["C3","G3","C4","E4"]],"mode":"chord","tempo":30},{"type":"compare","prompt":"Num destes acordes, a voz mais aguda (a melodia) foi encoberta e sumiu. Qual?","options":[{"label":"completo: melodia por cima","notes":[["C3","G3","C4","E4"]],"mode":"chord","tempo":30},{"label":"sem a melodia","notes":[["C3","G3","C4"]],"mode":"chord","tempo":30}],"answer":1,"explain":"Sem a nota de cima, o acorde fica “oco” e a música perde o rumo. É o que acontece quando os outros naipes cobrem o soprano."}]},{"titulo":"A pirâmide sonora","tipo":"descobrir","blocos":[{"type":"illustration","name":"naipes-satb","caption":"Baixo na base, vozes agudas mais leves."},{"type":"callout","icon":"olho","title":"Imagine uma pirâmide","text":"Base larga embaixo, ponta leve em cima. Na dúvida, o baixo fica mais presente e as vozes agudas mais leves."},{"type":"trueFalse","items":[{"statement":"Notas agudas tendem a soar mais fortes.","answer":true,"explain":"Sopranos e tenores precisam cuidar do volume nos agudos."},{"statement":"Um naipe com muitas pessoas deve cantar mais forte.","answer":false,"explain":"É o contrário: naipe numeroso canta mais suave; naipe pequeno pode precisar de mais presença."},{"statement":"Com microfones, o equilíbrio é combinado com quem opera o som.","answer":true,"explain":"Em grupos amplificados, o volume que chega ao público depende também da mesa de som."}]}]},{"titulo":"Mexa nos volumes","tipo":"experimentar","blocos":[{"type":"harmonyLink","arrangement":"hino-alegria-satb","label":"No treinador, ajuste o volume de cada naipe e ouça o efeito no equilíbrio"},{"type":"checklist","title":"No modo conjunto","items":["Baixei o soprano e ouvi a melodia “sumir”","Voltei o soprano ao normal","Aumentei só o contralto e ouvi o desequilíbrio","Achei uma mistura com melodia clara e acorde cheio"]}]},{"titulo":"Teste da vizinhança","tipo":"experimentar","blocos":[{"type":"callout","icon":"ouvido","title":"A regra de ouro","text":"Você deve ouvir as pessoas ao seu lado. Se não ouve, reduza seu volume até ouvi-las."},{"type":"timer","instruction":"Toque o Hino da Alegria no treinador e cante junto. Ajuste o seu volume até ouvir a gravação e a sua voz ao mesmo tempo, sem esforço.","seconds":40},{"type":"reveal","prompt":"No ensaio, você só ouve a própria voz. O que isso indica?","answer":"Que você está acima do grupo. Ajudar é ser ouvido junto, não por cima: reduza até ouvir os vizinhos."}]},{"titulo":"No louvor com microfones","tipo":"aplicar","blocos":[{"type":"check","question":"No ensaio do grupo de louvor, o técnico avisa que as contraltos estão cobrindo a melodia. O que fazer?","options":["Reduzir o volume do naipe e combinar o ajuste com o técnico de som","Pedir ao soprano para cantar mais forte","Afastar todos os microfones","Manter como está, pois o técnico corrige depois"],"answer":0,"explain":"O equilíbrio nasce nas vozes e é finalizado na mesa de som. Forçar o soprano só cansa a voz e desequilibra de novo."}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada situação ao ajuste certo.","pairs":[{"left":"Naipe com muita gente","right":"Cantar mais suave"},{"left":"Trecho agudo do soprano","right":"Aliviar o volume"},{"left":"Não ouço o vizinho","right":"Reduzir minha voz"},{"left":"Grupo amplificado","right":"Combinar com o técnico de som"}]}]}],"pratiqueSozinho":{"passos":["Repita o experimento de volumes com outro arranjo.","No próximo ensaio, aplique o teste da vizinhança."],"minutos":5,"frequencia":"1 vez por semana"},"errosComuns":[{"erro":"Achar que cantar mais forte é ajudar o naipe.","correcao":"Ajudar é ser ouvido junto, não por cima."},{"erro":"Ignorar o equilíbrio nos agudos.","correcao":"Notas agudas projetam mais: alivie o volume."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes."],"criterioAvanco":"Acertar pelo menos 70% da avaliação."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'escuta-ativa' from public.lessons where slug = 'equilibrio-sonoro' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:equilibrio-avaliacao')::uuid, 'equilibrio-avaliacao', (select id from public.lessons where slug = 'equilibrio-sonoro'), 'Avaliação: equilíbrio sonoro', 'Responda sobre equilíbrio entre vozes.', 'quiz', '{"questions":[{"q":"Qual voz geralmente precisa ser ouvida com clareza?","options":["A melodia","A voz mais grave sempre","A voz de quem canta mais alto","Nenhuma"],"answer":0},{"q":"Notas agudas tendem a…","options":["Soar mais fortes e precisar de cuidado com o volume","Soar mais fracas","Não interferir no equilíbrio","Ser sempre desafinadas"],"answer":0},{"q":"Um naipe com muitas pessoas deve…","options":["Cantar mais suave para não encobrir os outros","Cantar mais forte","Cantar sempre a melodia","Diminuir apenas no final"],"answer":0},{"q":"No teste da vizinhança, se você não ouve quem está ao lado…","options":["Reduza seu volume","Aumente seu volume","Troque de lugar","Pare de cantar"],"answer":0}]}'::jsonb, 'escuta-ativa', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:escuta-ativa')::uuid, (select id from public.learning_paths where slug = 'canto-em-conjunto'), 'escuta-ativa', 'Escuta ativa', 'Ouvir o conjunto enquanto canta: entradas, vozes e frases.', 3, 2, 20, '{"objetivo":"Perceber quantas vozes estão soando, qual voz entrou, e comparar frases melódicas — habilidades de quem canta ouvindo o grupo.","gancho":"Cantar é metade boca, metade ouvido. Hoje você vai treinar a metade que quase ninguém treina: ouvir o grupo enquanto canta.","etapas":[{"titulo":"Ouvidos abertos","tipo":"descobrir","blocos":[{"type":"illustration","name":"escuta-ativa","caption":"Cantar e ouvir o conjunto ao mesmo tempo."},{"type":"p","text":"Escuta ativa é cantar com os ouvidos abertos para o conjunto. Quem ouve o grupo se ajusta em tempo real."},{"type":"check","question":"Quem só ouve a própria voz tem dificuldade de perceber…","options":["Quando o grupo desafina, acelera ou outra voz entra","A letra do hino","A própria respiração","A cor da partitura"],"answer":0,"explain":"Sem ouvir o conjunto, não há como se ajustar. A escuta é o que mantém o grupo unido."}]},{"titulo":"Quantas vozes entraram?","tipo":"ouvir","blocos":[{"type":"callout","icon":"ouvido","title":"Entradas em camadas","text":"Em muitos arranjos, as vozes entram uma de cada vez e continuam soando. Perceber cada entrada ajuda você a saber onde o grupo está."},{"type":"check","question":"Ouça: as vozes entram uma de cada vez. Quantas estão soando no final?","options":["Uma","Duas","Três","Quatro"],"answer":2,"explain":"Primeiro uma voz, depois a segunda, depois a terceira. No final, três notas soam juntas.","audio":{"notes":["C4",["C4","E4"],["C4","E4","G4"]],"tempo":50}}]},{"titulo":"A frase voltou igual?","tipo":"ouvir","blocos":[{"type":"compare","prompt":"Ouça as duas frases com atenção. Elas são iguais?","options":[{"label":"Frase 1","notes":["C4","D4","E4","C4"],"tempo":90},{"label":"Frase 2","notes":["C4","D4","F4","C4"],"tempo":90}],"explain":"Quase iguais: só uma nota mudou. Num hino, o refrão às vezes volta com um detalhe diferente, e quem ouve percebe."},{"type":"check","question":"Qual nota da frase 2 ficou diferente?","options":["A 1ª","A 2ª","A 3ª","A 4ª"],"answer":2,"explain":"A 3ª nota subiu um pouco (de E4 para F4). O resto é igual."}]},{"titulo":"Onde está a sua voz?","tipo":"descobrir","blocos":[{"type":"audio","label":"Acorde de quatro vozes, de baixo para cima","notes":["C3","G3","C4","E4",["C3","G3","C4","E4"]],"tempo":70},{"type":"p","text":"Saber sua posição no acorde ajuda a se orientar: você está acima do baixo? Abaixo da melodia?"},{"type":"check","question":"No SATB, onde fica o contralto?","options":["Abaixo do soprano e acima do tenor","Acima do soprano","Abaixo do baixo","Sempre na mesma nota do tenor"],"answer":0,"explain":"De cima para baixo: soprano, contralto, tenor e baixo. O contralto é uma voz interna."}]},{"titulo":"Siga uma voz no cânone","tipo":"experimentar","blocos":[{"type":"harmonyLink","arrangement":"canone-solfejo","label":"Ouça o cânone: as vozes entram uma de cada vez"},{"type":"checklist","title":"No modo conjunto","items":["Contei quantas vozes entram","Ouvi de novo seguindo só a 2ª voz até o fim","Percebi quando cada voz entra"]},{"type":"tip","text":"Use volume moderado nos fones de ouvido."}]},{"titulo":"No ensaio","tipo":"aplicar","blocos":[{"type":"check","question":"No meio do hino, você percebe que o grupo está acelerando. O que fazer?","options":["Olhar o regente e manter o andamento dele","Acelerar junto com quem está mais rápido","Parar de cantar","Cantar mais forte para segurar o grupo"],"answer":0,"explain":"Siga o regente, não a pessoa mais rápida. Ouvir o grupo é o que permite perceber a mudança a tempo."},{"type":"reveal","prompt":"Desafio para o próximo culto: escolha uma voz interna (contralto ou tenor) e tente segui-la do início ao fim. Qual a dificuldade?","answer":"O ouvido vai “escorregar” para a melodia, que chama mais atenção. Tudo bem: volte para a voz escolhida. Isso é escuta ativa em treino."}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada habilidade à pergunta que ela responde.","pairs":[{"left":"Perceber entradas","right":"Quantas vozes estão soando?"},{"left":"Comparar frases","right":"O refrão voltou igual?"},{"left":"Saber sua posição","right":"Estou acima ou abaixo de quem?"},{"left":"Seguir uma voz interna","right":"O que o contralto está cantando?"}]}]}],"pratiqueSozinho":{"passos":["Laboratório: entradas vocais e frases (5 minutos).","Ouça uma gravação coral e tente seguir uma voz interna."],"minutos":7,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Prestar atenção só na melodia.","correcao":"Escolha uma voz interna e siga-a do início ao fim."}],"seguranca":["Use volume moderado nos fones de ouvido."],"criterioAvanco":"Acertar pelo menos 70% nas avaliações de entradas e frases."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'escuta-ativa' from public.lessons where slug = 'escuta-ativa' on conflict do nothing;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'memoria-melodica' from public.lessons where slug = 'escuta-ativa' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:escuta-entradas-avaliacao')::uuid, 'escuta-entradas-avaliacao', (select id from public.lessons where slug = 'escuta-ativa'), 'Avaliação: quantas vozes entraram?', 'As vozes entram uma de cada vez e continuam soando.', 'entry_detect', '{"rounds":6,"maxVoices":3,"ask":"quantidade"}'::jsonb, 'escuta-ativa', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:escuta-frases-avaliacao')::uuid, 'escuta-frases-avaliacao', (select id from public.lessons where slug = 'escuta-ativa'), 'Avaliação: frases iguais ou diferentes', 'Compare as duas frases melódicas.', 'phrase_compare', '{"rounds":6,"length":4}'::jsonb, 'memoria-melodica', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:manter-a-propria-linha')::uuid, (select id from public.learning_paths where slug = 'canto-em-conjunto'), 'manter-a-propria-linha', 'Manutenção da própria linha vocal', 'Sustentar a sua nota enquanto outras vozes cantam melodias diferentes.', 4, 2, 25, '{"objetivo":"Sustentar uma nota ou uma linha própria enquanto outra melodia soa, sem ser “arrastado” por ela.","gancho":"Você ensaiou sua voz sozinho(a) e estava perfeita. Aí o soprano entra com a melodia… e de repente você está cantando a melodia também. Vamos resolver isso, passo a passo.","etapas":[{"titulo":"O ímã da melodia","tipo":"descobrir","blocos":[{"type":"p","text":"Quando outra voz faz uma melodia diferente, a tendência é seguir a mais forte, normalmente a principal, e abandonar a própria linha. Isso é normal e se treina com passos pequenos."},{"type":"callout","icon":"ideia","title":"Como um ímã","text":"A melodia principal atrai o ouvido como um ímã. Quanto mais perto da sua nota ela passa, mais forte é a atração."},{"type":"check","question":"Quando é mais fácil ser “arrastado(a)” pela outra voz?","options":["Quando a melodia se aproxima da sua nota","Quando a melodia está bem longe da sua nota","Quando você está cantando sozinho(a)"],"answer":0,"explain":"Perto da sua nota, a outra voz “puxa” mais. Pense na sua nota com antecedência e mantenha-a firme."}]},{"titulo":"Ouça: pedal e melodia","tipo":"ouvir","blocos":[{"type":"illustration","name":"movimentos-vozes","caption":"Uma voz parada, outra em movimento."},{"type":"audio","label":"Nota pedal (C3) parada enquanto a melodia sobe","notes":[["C3","C4"],["C3","D4"],["C3","E4"],["C3","F4"],["C3","G4"]],"tempo":70},{"type":"compare","prompt":"Agora ouça a voz de baixo das terças paralelas, sozinha e com a voz de cima. Ela continua a mesma?","options":[{"label":"Voz 2 sozinha","notes":["C4","D4","E4","F4"],"tempo":80},{"label":"Voz 2 com a voz 1","notes":[["C4","E4"],["D4","F4"],["E4","G4"],["F4","A4"]],"tempo":80}],"explain":"A voz 2 é exatamente a mesma nas duas opções. O que muda é a voz de cima, que tenta “puxar” o seu ouvido. Seu trabalho é não largar a sua linha."}]},{"titulo":"Quatro degraus","tipo":"descobrir","blocos":[{"type":"order","prompt":"Coloque os degraus do treino na ordem, do mais fácil ao mais difícil.","items":["Sustentar uma única nota enquanto outra melodia se move","Cantar uma linha curta com notas repetidas contra uma melodia","Cantar a linha completa com a melodia baixinha (modo guiado)","Cantar com todas as vozes no mesmo volume (modo conjunto)"]},{"type":"tip","title":"Âncoras","text":"Marque na sua parte as notas “âncora”: notas longas ou repetidas que você conhece bem. Quando se perder, volte para a próxima âncora."}]},{"titulo":"Sua vez: segure a nota","tipo":"experimentar","blocos":[{"type":"warning","text":"Para usar o microfone aqui, use fones de ouvido: assim ele capta só a sua voz, não a referência."},{"type":"singAlong","instruction":"Ouça a nota e sustente “u” firme, em volume moderado e sem esforço. Imagine uma melodia passando por cima.","note":"C4","seconds":5},{"type":"timer","instruction":"Peça a alguém (ou ao celular) para tocar um hino enquanto você sustenta a sua nota em “u”. Respire quando precisar e volte à mesma nota.","seconds":30,"reps":2}]},{"titulo":"No treinador","tipo":"experimentar","blocos":[{"type":"harmonyLink","arrangement":"pedal-e-melodia","label":"Exercício “Nota pedal e melodia”: sustente a nota enquanto a melodia se move"},{"type":"checklist","title":"Passo a passo","items":["Escolhi a voz do pedal e o modo guiado","Cantei com a melodia baixinha","Aumentei a melodia aos poucos","Fiz o exercício de sustentação com distração (com fones)"]},{"type":"toolLink","tool":"afinador","label":"Treinador de afinação (use fones)"}]},{"titulo":"Um passo além: terças","tipo":"aplicar","blocos":[{"type":"harmonyLink","arrangement":"tercas-paralelas","label":"Agora cante a voz de baixo em “Terças paralelas”"},{"type":"check","question":"No ensaio, o soprano entra forte e passa perto da sua nota. O que fazer?","options":["Pensar na sua nota antes e mantê-la firme, em volume moderado","Cantar mais forte para não ouvir o soprano","Ir junto com o soprano até achar a nota","Parar e esperar a próxima frase"],"answer":0,"explain":"Forçar o volume cansa a voz e desequilibra o grupo. Antecipe a nota na mente e, se se perder, volte à próxima âncora."}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"trueFalse","items":[{"statement":"Tampar um ouvido pode ajudar no começo, mas o objetivo é cantar ouvindo o conjunto.","answer":true,"explain":"É uma muleta útil no início. Aos poucos, cante com os dois ouvidos abertos."},{"statement":"Quem se perdeu deve parar até o fim do hino.","answer":false,"explain":"Volte para a próxima nota âncora e continue com o grupo."},{"statement":"Para não ser arrastado(a), o melhor é cantar mais forte que a melodia.","answer":false,"explain":"Firmeza vem da atenção à sua nota, não do volume. Cante em volume moderado."}]}]}],"pratiqueSozinho":{"passos":["3 repetições do pedal com a melodia em volume normal.","Exercício de sustentação com distração (3 notas)."],"minutos":10,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Seguir a melodia quando ela se aproxima da sua nota.","correcao":"Pense na sua nota com antecedência e mantenha-a firme, em volume moderado."},{"erro":"Tampar um ouvido para não ouvir a outra voz.","correcao":"É útil no início, mas o objetivo é cantar ouvindo o conjunto."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Média de pelo menos 70% na sustentação da própria nota com outra melodia soando."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'independencia-vocal' from public.lessons where slug = 'manter-a-propria-linha' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:linha-propria-pedal')::uuid, 'linha-propria-pedal', (select id from public.lessons where slug = 'manter-a-propria-linha'), 'Prática: pedal no treinador', 'Cante a voz do pedal no exercício “Nota pedal e melodia”.', 'harmony_part', '{"voices":2,"arrangementSlug":"pedal-e-melodia"}'::jsonb, 'independencia-vocal', 'pratica', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:linha-propria-avaliacao')::uuid, 'linha-propria-avaliacao', (select id from public.lessons where slug = 'manter-a-propria-linha'), 'Avaliação: sustente a sua nota com distração', 'Sustente a nota enquanto outra melodia toca. Com microfone, use fones de ouvido.', 'sing_note', '{"rounds":3,"holdSeconds":4,"toleranceCents":30,"distractor":true}'::jsonb, 'independencia-vocal', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.learning_paths (id, slug, code, title, subtitle, description, icon, sort) values (md5('path:harmonia-vocal')::uuid, 'harmonia-vocal', 'D', 'Harmonia vocal', 'De duas a quatro vozes, com independência', 'O coração da formação: cantar uma linha própria mantendo afinação, ritmo e equilíbrio com as outras vozes. Progride de duas vozes em terças e sextas até acordes a quatro vozes, quarteto masculino e arranjos com contracanto e pedal.', 'git-merge', 3) on conflict (slug) do update set code = excluded.code, title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, icon = excluded.icon, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:duas-vozes')::uuid, (select id from public.learning_paths where slug = 'harmonia-vocal'), 'duas-vozes', 'Duas vozes', 'Melodia principal e segunda voz; movimento paralelo e contrário.', 0, 2, 25, '{"objetivo":"Cantar uma segunda voz contra a melodia principal, reconhecendo movimento paralelo, contrário e nota sustentada contra melodia em movimento.","gancho":"Já reparou como um hino ganha vida quando alguém canta uma segunda voz por baixo da melodia? Hoje você aprende a ser essa voz, sem ser arrastado(a) pela melodia.","etapas":[{"titulo":"Uma melodia ganha companhia","tipo":"ouvir","blocos":[{"type":"p","text":"Na harmonia a duas vozes, uma voz canta a melodia principal e a outra canta uma linha de apoio: a “segunda voz”."},{"type":"compare","prompt":"Ouça a mesma frase sozinha e com uma segunda voz por baixo.","options":[{"label":"Só a melodia","notes":["E4","F4","G4","F4","E4"],"tempo":70},{"label":"Melodia + segunda voz","notes":[["E4","C4"],["F4","D4"],["G4","E4"],["F4","D4"],["E4","C4"]],"tempo":70}],"explain":"A melodia é a mesma. A segunda voz não é uma melodia qualquer: ela caminha em intervalos consonantes (aqui, terças) e deixa o som mais cheio."},{"type":"check","question":"Qual é o papel da segunda voz?","options":["Apoiar a melodia, soando um pouco mais suave","Competir com a melodia, soando mais forte","Cantar a mesma nota da melodia o tempo todo"],"answer":0,"explain":"A melodia lidera; a segunda voz apoia. Se ela fica mais forte, a congregação perde a melodia."}]},{"titulo":"Três jeitos de caminhar juntas","tipo":"descobrir","blocos":[{"type":"illustration","name":"movimentos-vozes","caption":"Paralelo, contrário e oblíquo."},{"type":"list","items":["Paralelo: as duas vozes sobem e descem juntas, mantendo o mesmo intervalo (ex.: terças paralelas).","Contrário: uma voz sobe enquanto a outra desce. Dá independência e riqueza.","Oblíquo: uma voz fica parada (nota sustentada) enquanto a outra se move."]},{"type":"callout","icon":"ideia","title":"Pense em dois amigos andando","text":"Lado a lado no mesmo passo (paralelo), indo em direções opostas (contrário) ou um parado esperando o outro (oblíquo)."}]},{"titulo":"Ouça os movimentos","tipo":"ouvir","blocos":[{"type":"compare","prompt":"Desafio: qual destes exemplos está em movimento contrário?","options":[{"label":"Paralelo (terças subindo juntas)","notes":[["E4","C4"],["F4","D4"],["G4","E4"]],"tempo":70},{"label":"Contrário (aguda sobe, grave desce)","notes":[["E4","C4"],["F4","A3"],["G4","G3"]],"tempo":70},{"label":"Oblíquo (grave parada em Dó)","notes":[["E4","C4"],["F4","C4"],["G4","C4"]],"tempo":70}],"answer":1,"explain":"No contrário, as vozes se afastam: a aguda sobe (Mi–Fá–Sol) e a grave desce (Dó–Lá–Sol)."},{"type":"check","question":"Ouça: o que a voz grave faz?","audio":{"notes":[["C4","E4"],["C4","F4"],["C4","G4"],["C4","E4"]],"mode":"seq","tempo":70},"options":["Fica parada no Dó (movimento oblíquo)","Sobe junto com a aguda (paralelo)","Desce enquanto a aguda sobe (contrário)"],"answer":0,"explain":"A voz grave sustenta Dó enquanto a aguda se move: é o movimento oblíquo."}]},{"titulo":"Sua vez: cante a segunda voz","tipo":"experimentar","blocos":[{"type":"audio","label":"Sua linha: a segunda voz sozinha (Dó–Ré–Mi–Ré–Dó)","notes":["C4","D4","E4","D4","C4"],"tempo":70},{"type":"timer","instruction":"Cante essa linha em “lu”, devagar e em volume confortável. Repita até conseguir sem ouvir de novo.","seconds":20,"reps":2},{"type":"singAlong","instruction":"Termine na nota-âncora: sustente o Dó com segurança.","note":"C4","seconds":4},{"type":"tip","title":"Nota-âncora","text":"Âncoras são notas fáceis de lembrar (início, fim, notas longas). Se a melodia te puxar, volte para elas."}]},{"titulo":"Solo, guiado, conjunto","tipo":"descobrir","blocos":[{"type":"callout","icon":"estrela","title":"Como não ser arrastado(a) pela melodia","text":"Aprenda a sua voz sozinho(a), depois com a melodia baixinha e só então com as duas no mesmo volume. No movimento contrário, pense na direção da SUA linha."},{"type":"order","prompt":"Coloque os passos de estudo na ordem certa.","items":["Modo solo: só a sua voz","Modo guiado: a outra voz soa baixinho","Modo conjunto: as duas no mesmo volume","Gravar e ouvir: a sua voz se manteve?"]}]},{"titulo":"No treinador de harmonia","tipo":"aplicar","blocos":[{"type":"harmonyLink","arrangement":"movimento-contrario","label":"Exercício: movimento contrário"},{"type":"harmonyLink","arrangement":"hino-alegria-duas-vozes","label":"Hino da Alegria a duas vozes"},{"type":"checklist","title":"Roteiro de estudo","items":["Ouvi “Movimento contrário” no modo conjunto","Cantei a voz 2 no modo solo","Cantei a voz 2 no modo guiado","Repeti no Hino da Alegria a duas vozes","Gravei no modo conjunto e ouvi"]}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada termo ao que ele significa.","pairs":[{"left":"Movimento paralelo","right":"Sobem e descem juntas, mesmo intervalo"},{"left":"Movimento contrário","right":"Uma sobe enquanto a outra desce"},{"left":"Movimento oblíquo","right":"Uma sustenta, a outra se move"},{"left":"Segunda voz","right":"Apoia a melodia, sem encobri-la"}]}]}],"pratiqueSozinho":{"passos":["Treinador: segunda voz do Hino da Alegria (modo guiado → conjunto).","Marque os compassos difíceis e repita só esses trechos."],"minutos":12,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Passar para a melodia sem perceber.","correcao":"Cante a sua linha em volume confortável e use as notas-âncora."},{"erro":"Cantar a segunda voz mais forte que a melodia.","correcao":"A melodia lidera; a segunda voz apoia."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e cantar a segunda voz do Hino da Alegria no modo conjunto."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'harmonia-duas-vozes' from public.lessons where slug = 'duas-vozes' on conflict do nothing;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'independencia-vocal' from public.lessons where slug = 'duas-vozes' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:duas-vozes-treinador')::uuid, 'duas-vozes-treinador', (select id from public.lessons where slug = 'duas-vozes'), 'Prática: segunda voz no treinador', 'Cante a segunda voz do Hino da Alegria e avalie.', 'harmony_part', '{"voices":2,"arrangementSlug":"hino-alegria-duas-vozes"}'::jsonb, 'harmonia-duas-vozes', 'pratica', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:duas-vozes-avaliacao')::uuid, 'duas-vozes-avaliacao', (select id from public.lessons where slug = 'duas-vozes'), 'Avaliação: movimentos entre vozes', 'Responda e ouça os exemplos.', 'quiz', '{"questions":[{"q":"Duas vozes que sobem e descem juntas mantendo o intervalo estão em movimento…","options":["Paralelo","Contrário","Oblíquo","Uníssono"],"answer":0},{"q":"Uma voz sobe enquanto a outra desce. Que movimento é esse?","options":["Contrário","Paralelo","Oblíquo","Direto"],"answer":0},{"q":"Uma voz sustenta a nota enquanto a outra se move:","options":["Movimento oblíquo","Movimento paralelo","Movimento contrário","Cânone"],"answer":0},{"q":"Ouça: a voz aguda sobe e a grave desce. Que movimento você ouviu?","options":["Contrário","Paralelo"],"answer":0,"audio":{"notes":[["E4","C4"],["F4","A3"],["G4","G3"]],"mode":"seq","tempo":70}},{"q":"Qual é a sequência recomendada para aprender a sua voz?","options":["Solo → guiado → conjunto","Conjunto → solo","Só conjunto","Só ler a partitura"],"answer":0}]}'::jsonb, 'harmonia-duas-vozes', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:tercas-e-sextas')::uuid, (select id from public.learning_paths where slug = 'harmonia-vocal'), 'tercas-e-sextas', 'Terças e sextas', 'Os intervalos mais usados entre duas vozes.', 1, 2, 25, '{"objetivo":"Cantar terças e sextas paralelas com afinação e reconhecer esses intervalos entre duas vozes.","gancho":"Por que quase toda segunda voz de louvor soa tão “doce”? O segredo está em dois intervalos: a terça e a sexta.","etapas":[{"titulo":"Contando degraus","tipo":"descobrir","blocos":[{"type":"illustration","name":"intervalo-escada","caption":"Cada degrau é uma nota da escala."},{"type":"list","items":["Terça abaixo: a segunda voz canta duas notas da escala abaixo da melodia (Mi → Dó, Fá → Ré).","Sexta abaixo: cinco notas da escala abaixo (Dó → Mi, Ré → Fá)."]},{"type":"check","question":"A melodia canta Sol. Qual nota fica uma terça abaixo?","options":["Mi","Fá","Ré","Dó"],"answer":0,"explain":"Desça duas notas da escala: Sol → Fá → Mi. A terça abaixo de Sol é Mi."}]},{"titulo":"Ouça terças e sextas","tipo":"ouvir","blocos":[{"type":"p","text":"Terças e sextas são consonâncias imperfeitas: soam doces e cheias e permitem caminhar em paralelo sem perder a independência."},{"type":"intervals","root":"C4","semitones":[3,4,8,9]},{"type":"compare","prompt":"Desafio: qual destes dois intervalos é a sexta?","options":[{"label":"Terça (Dó–Mi)","notes":[["C4","E4"]],"mode":"chord"},{"label":"Sexta (Mi–Dó)","notes":[["E3","C4"]],"mode":"chord"}],"answer":1,"explain":"A sexta é mais aberta, mas continua doce. A terça é mais “fechadinha”, as notas bem próximas."}]},{"titulo":"A terça que vira sexta","tipo":"descobrir","blocos":[{"type":"p","text":"Pegue a terça Dó–Mi e suba o Dó uma oitava. Agora Mi–Dó é uma sexta! Terça e sexta são inversões uma da outra."},{"type":"audio","label":"Terça Dó–Mi e depois sexta Mi–Dó","notes":[["C4","E4"],["E4","C5"]],"tempo":40},{"type":"reveal","prompt":"Some uma terça maior (4 semitons) com uma sexta menor (8 semitons). O que dá?","answer":"12 semitons: uma oitava. Por isso, ao inverter uma terça (levar a nota de baixo uma oitava acima), ela vira sexta."}]},{"titulo":"Cuidado com o som “oco”","tipo":"ouvir","blocos":[{"type":"compare","prompt":"Compare a mesma melodia acompanhada em terças e em quintas paralelas.","options":[{"label":"Terças paralelas","notes":[["E4","C4"],["F4","D4"],["G4","E4"]],"tempo":70},{"label":"Quintas paralelas","notes":[["G4","C4"],["A4","D4"],["B4","E4"]],"tempo":70}],"explain":"Quintas (e oitavas) paralelas soam “ocas” e fazem as vozes perderem a independência. Na segunda voz, prefira terças e sextas."},{"type":"trueFalse","items":[{"statement":"Na escala, todas as terças têm o mesmo número de semitons.","answer":false,"explain":"Elas alternam entre maiores (4 semitons) e menores (3). Siga as notas da escala, não um número fixo."},{"statement":"A terça maior bem afinada num acorde soa um pouco mais baixa que a do teclado.","answer":true,"explain":"Quando ela “encaixa”, o acorde parece vibrar. Ouça o grupo, não só o teclado."},{"statement":"Quintas paralelas são ótimas para a segunda voz.","answer":false,"explain":"Soam ocas e tiram a independência da segunda voz."}]}]},{"titulo":"Sua vez: a escada de terças","tipo":"experimentar","blocos":[{"type":"audio","label":"Escala de Dó em terças","notes":[["C4","E4"],["D4","F4"],["E4","G4"],["F4","A4"],["G4","B4"],["A4","C5"],["B4","D5"],["C5","E5"]],"tempo":60},{"type":"keyboard","from":"C4","to":"E5","highlight":["C4","E4","D4","F4"],"label":"Dó–Mi, Ré–Fá… sempre pulando uma tecla branca"},{"type":"timer","instruction":"Toque a escada e cante a nota de BAIXO de cada par (Dó, Ré, Mi…) em “lu”, ouvindo a terça se encaixar. Sem forçar o agudo.","seconds":30}]},{"titulo":"No treinador de harmonia","tipo":"aplicar","blocos":[{"type":"harmonyLink","arrangement":"tercas-paralelas","label":"Terças paralelas"},{"type":"harmonyLink","arrangement":"sextas-paralelas","label":"Sextas paralelas"},{"type":"checklist","title":"Roteiro de estudo","items":["Terças: voz 2 no modo solo","Terças: modo guiado e depois conjunto","Gravei uma vez no modo conjunto","Repeti tudo com as sextas"]}]},{"titulo":"Terça ou sexta?","tipo":"checar","blocos":[{"type":"check","question":"Ouça o intervalo. É uma terça ou uma sexta?","audio":{"notes":[["E3","C4"]],"mode":"chord","tempo":30},"options":["Sexta","Terça"],"answer":0,"explain":"Mi3–Dó4 é uma sexta: o som é mais aberto que a terça Dó–Mi."},{"type":"match","prompt":"Ligue cada situação ao intervalo.","pairs":[{"left":"Melodia Mi, segunda voz Dó abaixo","right":"Terça abaixo"},{"left":"Melodia Dó, segunda voz Mi abaixo","right":"Sexta abaixo"},{"left":"Dó–Sol subindo para Ré–Lá","right":"Quintas paralelas: evite"},{"left":"Terça com a nota de baixo uma oitava acima","right":"Vira sexta"}]}]}],"pratiqueSozinho":{"passos":["Cante a escala de Dó em terças com o teclado (Dó–Mi, Ré–Fá, Mi–Sol…).","Treinador: terças e sextas paralelas no modo conjunto."],"minutos":10,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Cantar sempre a mesma distância em semitons.","correcao":"Na escala, as terças alternam entre maiores e menores. Siga as notas, não um número fixo de semitons."},{"erro":"Escorregar para a quinta.","correcao":"Ouça o intervalo: a quinta soa mais aberta e “oca”."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes."],"criterioAvanco":"Acertar pelo menos 70% na avaliação de terças e sextas."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
