insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:tercas-treinador')::uuid, 'tercas-treinador', (select id from public.lessons where slug = 'tercas-e-sextas'), 'Prática: terças paralelas', 'Cante a voz 2 de “Terças paralelas”.', 'harmony_part', '{"voices":2,"arrangementSlug":"tercas-paralelas"}'::jsonb, 'harmonia-duas-vozes', 'pratica', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:tercas-sextas-avaliacao')::uuid, 'tercas-sextas-avaliacao', (select id from public.lessons where slug = 'tercas-e-sextas'), 'Avaliação: terça ou sexta?', 'Identifique o intervalo harmônico.', 'interval_id', '{"rounds":10,"intervals":[3,4,8,9],"direction":"harmonic"}'::jsonb, 'intervalos', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:tres-vozes')::uuid, (select id from public.learning_paths where slug = 'harmonia-vocal'), 'tres-vozes', 'Três vozes', 'Acordes, função de cada linha e entradas em momentos diferentes.', 2, 2, 30, '{"objetivo":"Cantar a sua linha numa textura de três vozes, compreendendo a distribuição das notas do acorde, notas comuns e entradas independentes.","gancho":"Com três vozes, o acorde fica completo pela primeira vez. Vamos descobrir onde a sua voz se encaixa nele.","etapas":[{"titulo":"Um acorde, três vozes","tipo":"descobrir","blocos":[{"type":"illustration","name":"triade","caption":"Fundamental, terça e quinta."},{"type":"p","text":"Com três vozes já dá para cantar uma tríade completa: uma voz para cada nota (fundamental, terça e quinta)."},{"type":"audio","label":"Dó maior nota por nota e depois junto","notes":["C4","E4","G4",["C4","E4","G4"]],"tempo":60},{"type":"check","question":"Na tríade de Dó maior (Dó–Mi–Sol), qual nota é a terça?","options":["Mi","Dó","Sol"],"answer":0,"explain":"Dó é a fundamental, Mi é a terça e Sol é a quinta."}]},{"titulo":"Quem faz o quê","tipo":"descobrir","blocos":[{"type":"list","items":["Voz aguda: normalmente canta a melodia.","Voz grave: dá a base do acorde.","Voz do meio: completa o acorde."]},{"type":"callout","icon":"ouvido","title":"O recheio do sanduíche","text":"A voz do meio é a mais difícil de ouvir. Ela precisa estar presente, sem encobrir a melodia."},{"type":"chords","root":"C4","qualities":["maior","menor"]}]},{"titulo":"O segredo das notas comuns","tipo":"ouvir","blocos":[{"type":"p","text":"Quando dois acordes vizinhos têm uma nota em comum, a voz que canta essa nota costuma ficar nela. Isso facilita a afinação."},{"type":"audio","label":"I – vi – IV – V – I a três vozes (Dó – Lám – Fá – Sol – Dó)","notes":[["C4","E4","G4"],["C4","E4","A4"],["C4","F4","A4"],["B3","D4","G4"],["C4","E4","G4"]],"tempo":50},{"type":"check","question":"De Dó maior (Dó–Mi–Sol) para Lá menor (Lá–Dó–Mi), quais notas ficaram iguais?","options":["Dó e Mi","Só o Sol","Nenhuma","Todas"],"answer":0,"explain":"Dó e Mi são comuns aos dois acordes. Só o Sol se move, subindo um degrau para Lá."}]},{"titulo":"O menor caminho","tipo":"ouvir","blocos":[{"type":"compare","prompt":"Os dois exemplos vão de Dó maior para Fá maior. Qual é mais fácil de cantar?","options":[{"label":"Cada voz anda o mínimo","notes":[["C4","E4","G4"],["C4","F4","A4"]],"tempo":50},{"label":"Todas as vozes saltam","notes":[["C4","E4","G4"],["F3","A4","C5"]],"tempo":50}],"answer":0,"explain":"Na boa condução, cada voz vai pelo menor caminho para a próxima nota do acorde e mantém as notas comuns (aqui, o Dó)."}]},{"titulo":"Entradas em momentos diferentes","tipo":"experimentar","blocos":[{"type":"p","text":"Em cânones e arranjos com imitação, as vozes entram em momentos diferentes. Num cânone, todas cantam a mesma melodia, cada uma no seu momento."},{"type":"rhythm","pattern":"q q q q q q q q","bpm":80,"label":"Conte dois compassos: 1-2-3-4, 1-2-3-4"},{"type":"timer","instruction":"Conte “1-2-3-4, 1-2-3-4” em voz alta com a pulsação e entre cantando Dó–Ré–Mi–Fá–Sol exatamente no próximo tempo 1.","seconds":15,"reps":2},{"type":"tip","text":"Não espere a outra voz para entrar: conte os tempos. A sua entrada tem um momento próprio."}]},{"titulo":"No treinador de harmonia","tipo":"aplicar","blocos":[{"type":"harmonyLink","arrangement":"triades-tres-vozes","label":"Tríades a três vozes (I – vi – IV – V – I)"},{"type":"harmonyLink","arrangement":"canone-solfejo","label":"Cânone do solfejo: entradas em momentos diferentes"},{"type":"harmonyLink","arrangement":"hino-alegria-tres-vozes","label":"Hino da Alegria a três vozes"},{"type":"checklist","title":"Roteiro de estudo","items":["Tríades: cantei as três vozes no modo solo e achei as notas comuns","Escolhi a voz da minha região e cantei no guiado e no conjunto","Cânone: entrei como voz 2, depois da voz 1","Cantei a minha voz no Hino da Alegria a três vozes"]}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"trueFalse","items":[{"statement":"Quando há uma nota comum entre dois acordes, a voz que a canta costuma permanecer nela.","answer":true,"explain":"Permanecer na nota comum dá segurança e ajuda a afinação."},{"statement":"Num cânone, todas as vozes começam juntas.","answer":false,"explain":"No cânone, a mesma melodia entra em momentos diferentes."},{"statement":"A voz do meio deve cantar mais forte para aparecer.","answer":false,"explain":"Ela precisa estar presente, mas sem encobrir a melodia."}]}]}],"pratiqueSozinho":{"passos":["Treinador: Hino da Alegria a três vozes (sua voz).","Cânone do solfejo entrando como voz 2 ou 3."],"minutos":12,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Abandonar a nota comum entre acordes.","correcao":"Se a nota se repete, permaneça nela com segurança."},{"erro":"Esperar a outra voz para entrar.","correcao":"Conte os tempos: a sua entrada tem um momento próprio."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e cantar a sua voz a três vozes no modo conjunto."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
