insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:tres-vozes-treinador')::uuid, 'tres-vozes-treinador', (select id from public.lessons where slug = 'tres-vozes'), 'Prática: três vozes no treinador', 'Cante a sua voz no Hino da Alegria a três vozes.', 'harmony_part', '{"voices":3,"arrangementSlug":"hino-alegria-tres-vozes"}'::jsonb, 'harmonia-tres-quatro-vozes', 'pratica', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:tres-vozes-acordes-avaliacao')::uuid, 'tres-vozes-acordes-avaliacao', (select id from public.lessons where slug = 'tres-vozes'), 'Avaliação: a nota mais aguda do acorde', 'Ouça o acorde de três notas e encontre a nota mais aguda.', 'chord_extreme', '{"rounds":6,"ask":"aguda","size":3}'::jsonb, 'acordes', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:tres-vozes-avaliacao')::uuid, 'tres-vozes-avaliacao', (select id from public.lessons where slug = 'tres-vozes'), 'Avaliação: conceitos de três vozes', 'Responda sobre harmonia a três vozes.', 'quiz', '{"questions":[{"q":"Uma tríade é formada por…","options":["Fundamental, terça e quinta","Três fundamentais","Fundamental, segunda e quarta","Três notas quaisquer"],"answer":0},{"q":"Quando dois acordes vizinhos têm uma nota em comum, a voz que a canta geralmente…","options":["Permanece na mesma nota","Salta uma oitava","Faz uma pausa","Canta mais forte"],"answer":0},{"q":"Qual voz costuma ser a mais difícil de ouvir numa textura a três vozes?","options":["A voz do meio","A melodia","O baixo","Nenhuma"],"answer":0},{"q":"Em um cânone, as vozes…","options":["Cantam a mesma melodia entrando em momentos diferentes","Cantam melodias diferentes ao mesmo tempo, começando juntas","Cantam em uníssono","Não têm letra"],"answer":0}]}'::jsonb, 'harmonia-tres-quatro-vozes', 'avaliacao', 2, 2) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:acordes-a-quatro-vozes')::uuid, (select id from public.learning_paths where slug = 'harmonia-vocal'), 'acordes-a-quatro-vozes', 'Acordes a quatro vozes (SATB)', 'Soprano, contralto, tenor e baixo: formação, condução e estudo da própria parte.', 3, 3, 30, '{"objetivo":"Compreender a formação tradicional SATB, como os acordes são distribuídos em quatro vozes e como estudar a própria parte ouvindo o conjunto.","gancho":"Abra um hinário: as quatro linhas de notas são Soprano, Contralto, Tenor e Baixo. Hoje você descobre como elas formam o acorde e como estudar a sua.","etapas":[{"titulo":"Quatro naipes, um coro","tipo":"descobrir","blocos":[{"type":"illustration","name":"naipes-satb","caption":"Soprano, Contralto (Alto), Tenor e Baixo."},{"type":"list","items":["Soprano: normalmente canta a melodia.","Contralto: voz feminina intermediária, logo abaixo do soprano.","Tenor: voz masculina aguda.","Baixo: voz masculina grave; costuma cantar a fundamental e define a harmonia."]},{"type":"check","question":"Uma tríade tem três notas, mas o coro tem quatro vozes. O que acontece?","options":["Uma nota é dobrada, geralmente a fundamental","Uma das vozes fica calada","Alguém inventa uma quarta nota qualquer"],"answer":0,"explain":"Duas vozes cantam a mesma nota (em oitavas ou em uníssono). Em geral, dobra-se a fundamental."}]},{"titulo":"Ouça o acorde se montar","tipo":"ouvir","blocos":[{"type":"audio","label":"Baixo (Dó3), tenor (Sol3), contralto (Dó4), soprano (Mi4)… e todos juntos","notes":["C3","G3","C4","E4",["C3","G3","C4","E4"]],"tempo":50},{"type":"check","question":"Ouça este acorde de Sol maior. Qual nota está no baixo?","audio":{"notes":[["G2","D3","B3","G4"]],"mode":"chord","tempo":30},"options":["Sol","Si","Ré"],"answer":0,"explain":"O baixo canta Sol, a fundamental. Repare que o Sol aparece duas vezes: é a nota dobrada."}]},{"titulo":"O baixo manda no acorde","tipo":"ouvir","blocos":[{"type":"compare","prompt":"As vozes de cima são iguais. Só o baixo muda.","options":[{"label":"Baixo na fundamental (Dó)","notes":[["C3","E4","G4","C5"]],"mode":"chord"},{"label":"Baixo na terça (Mi)","notes":[["E3","E4","G4","C5"]],"mode":"chord"}],"explain":"Os dois são Dó maior, mas com Mi no baixo o acorde soa menos “assentado”. Por isso o baixo estuda a sua nota com prioridade e canta com firmeza."},{"type":"illustration","name":"inversoes","caption":"A nota do baixo muda a cara do acorde."}]},{"titulo":"Tenor: a pegadinha da clave","tipo":"descobrir","blocos":[{"type":"illustration","name":"partitura-vocal"},{"type":"p","text":"Nas partituras, o tenor costuma ser escrito na clave de Sol com um 8 embaixo. Isso quer dizer: soa uma oitava abaixo do escrito. Às vezes ele aparece na clave de Fá."},{"type":"check","question":"Na parte do tenor (clave de Sol com 8 embaixo) está escrito este Dó. Que nota o tenor canta?","staff":{"clef":"sol","notes":["C5"]},"options":["Dó central (Dó4)","O Dó escrito (Dó5)","Dó duas oitavas abaixo (Dó3)"],"answer":0,"explain":"O 8 embaixo da clave manda descer uma oitava: o Dó5 escrito soa como Dó4, o Dó central."}]},{"titulo":"As regras de ouro da condução","tipo":"descobrir","blocos":[{"type":"list","items":["Mover cada voz pelo menor caminho.","Manter as notas comuns.","Evitar quintas e oitavas paralelas.","Não cruzar as vozes sem motivo."]},{"type":"audio","label":"Exemplo: I – IV – V7 – I a quatro vozes, com passos curtos","notes":[["C3","G3","E4","C5"],["F3","A3","F4","C5"],["G3","D4","F4","B4"],["C3","C4","E4","C5"]],"tempo":40},{"type":"callout","icon":"ouvido","title":"Repare no soprano","text":"Ele fica no Dó, desce ao Si e volta ao Dó. Quase não se move, e mesmo assim o acorde muda inteiro."}]},{"titulo":"Como estudar a sua parte","tipo":"experimentar","blocos":[{"type":"order","prompt":"Monte o roteiro de estudo na ordem certa.","items":["Ler o texto e o ritmo","Ouvir a sua voz no modo solo","Cantar com a sua voz destacada (guiado)","Cantar no conjunto","Repetir os compassos difíceis","Voltar ao conjunto ouvindo quem está acima e abaixo"]},{"type":"toolLink","tool":"extensao","label":"Ainda não sabe o seu naipe? Teste a sua extensão"}]},{"titulo":"No treinador de harmonia","tipo":"aplicar","blocos":[{"type":"harmonyLink","arrangement":"acordes-sustentados-satb","label":"Acordes sustentados SATB (para afinação vertical)"},{"type":"harmonyLink","arrangement":"hino-alegria-satb","label":"Hino da Alegria a quatro vozes (SATB)"},{"type":"timer","instruction":"Nos acordes sustentados, cante a sua nota e ouça o acorde completo se formar ao redor dela.","seconds":20},{"type":"check","question":"No ensaio, um baixo está inseguro e começa a cantar a melodia uma oitava abaixo. Qual é o problema?","options":["O acorde perde a fundamental e a base da harmonia","Nenhum, desde que cante afinado","O soprano vai cantar mais baixo"],"answer":0,"explain":"A nota do baixo define o acorde. Estude-a com prioridade e cante-a com firmeza."}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada naipe à sua função mais comum.","pairs":[{"left":"Soprano","right":"Melodia"},{"left":"Contralto","right":"Voz feminina logo abaixo do soprano"},{"left":"Tenor","right":"Voz masculina aguda, soa uma oitava abaixo do escrito"},{"left":"Baixo","right":"Fundamental do acorde"}]}]}],"pratiqueSozinho":{"passos":["Treinador: sua voz no Hino da Alegria SATB.","Acordes sustentados SATB no modo conjunto."],"minutos":15,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Tenores lendo a clave de Sol na altura escrita.","correcao":"Na clave de Sol com o 8 embaixo, o tenor soa uma oitava abaixo do escrito."},{"erro":"Baixos fugindo da fundamental por insegurança.","correcao":"A nota do baixo define o acorde: estude-a com prioridade e firmeza."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e cantar a sua parte no Hino da Alegria SATB no modo conjunto."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'harmonia-tres-quatro-vozes' from public.lessons where slug = 'acordes-a-quatro-vozes' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:satb-treinador')::uuid, 'satb-treinador', (select id from public.lessons where slug = 'acordes-a-quatro-vozes'), 'Prática: sua parte no SATB', 'Cante a sua parte no Hino da Alegria SATB e avalie.', 'harmony_part', '{"voices":4,"arrangementSlug":"hino-alegria-satb"}'::jsonb, 'harmonia-tres-quatro-vozes', 'pratica', 3, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:satb-avaliacao')::uuid, 'satb-avaliacao', (select id from public.lessons where slug = 'acordes-a-quatro-vozes'), 'Avaliação: formação SATB', 'Responda sobre a escrita a quatro vozes.', 'quiz', '{"questions":[{"q":"Em SATB, quem normalmente canta a melodia?","options":["Soprano","Contralto","Tenor","Baixo"],"answer":0},{"q":"Numa tríade a quatro vozes, qual nota costuma ser dobrada?","options":["A fundamental","A terça","A quinta","Nenhuma"],"answer":0},{"q":"O tenor escrito na clave de Sol com um 8 embaixo soa…","options":["Uma oitava abaixo do escrito","Uma oitava acima","Exatamente como escrito","Uma quinta abaixo"],"answer":0},{"q":"Qual destas é uma regra de condução de vozes?","options":["Evitar quintas e oitavas paralelas","Sempre saltar uma oitava","Cruzar as vozes em todos os acordes","Mudar todas as notas a cada acorde"],"answer":0},{"q":"Ouça o acorde. Qual nota está no baixo?","options":["Dó","Mi","Sol"],"answer":0,"audio":{"notes":[["C3","G3","E4","C5"]],"mode":"chord","tempo":30}}]}'::jsonb, 'harmonia-tres-quatro-vozes', 'avaliacao', 3, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:quarteto-masculino')::uuid, (select id from public.learning_paths where slug = 'harmonia-vocal'), 'quarteto-masculino', 'Quarteto masculino', 'Primeiro tenor, segundo tenor, barítono e baixo.', 4, 3, 25, '{"objetivo":"Conhecer a formação TTBB, a função de cada voz e cantar uma parte num quarteto masculino.","gancho":"Quatro vozes masculinas bem pertinho umas das outras: quando o acorde encaixa, parece um órgão. Vamos ver como cada voz do quarteto trabalha.","etapas":[{"titulo":"TTBB: quem é quem","tipo":"descobrir","blocos":[{"type":"illustration","name":"quarteto-ttbb","caption":"Primeiro tenor, segundo tenor, barítono e baixo."},{"type":"list","items":["Primeiro tenor: a voz mais aguda; muitas vezes canta acima da melodia, com voz leve.","Segundo tenor: em muitos arranjos canta a melodia (no barbershop, é o “lead”).","Barítono: completa o acorde; às vezes acima, às vezes abaixo da melodia.","Baixo: a fundamental e o alicerce rítmico."]},{"type":"callout","icon":"olho","title":"Os nomes variam","text":"A nomenclatura e a distribuição mudam conforme o arranjo e a tradição (hinódia, gospel, barbershop). Confira sempre na partitura."}]},{"titulo":"Vozes próximas, som unido","tipo":"ouvir","blocos":[{"type":"compare","prompt":"O mesmo acorde de Sol maior em duas formações.","options":[{"label":"Coral misto (vozes espalhadas)","notes":[["G2","D3","B3","G4"]],"mode":"chord"},{"label":"Quarteto masculino (vozes próximas)","notes":[["G2","D3","G3","B3"]],"mode":"chord"}],"explain":"No quarteto masculino as quatro vozes ficam numa região próxima. O som fica muito unido, e qualquer desafinação aparece mais."},{"type":"reveal","prompt":"Por que vozes tão próximas exigem afinação mais cuidadosa?","answer":"Com as notas perto umas das outras, o som se funde num bloco só. Uma nota um pouco fora “briga” com a vizinha e o acorde perde o brilho."}]},{"titulo":"Onde está a melodia?","tipo":"descobrir","blocos":[{"type":"p","text":"No arranjo de treino desta aula (melodia NEW BRITAIN, conhecida como “Amazing Grace”, de domínio público, com texto original da plataforma), a melodia está no segundo tenor."},{"type":"check","question":"Se a melodia está no segundo tenor, onde costuma ficar o primeiro tenor?","options":["Acima da melodia, com voz leve","Abaixo do baixo","Cantando a melodia junto, em uníssono"],"answer":0,"explain":"O primeiro tenor é a voz mais aguda e frequentemente canta acima da melodia, com voz leve."}]},{"titulo":"O barítono que cruza","tipo":"ouvir","blocos":[{"type":"p","text":"O barítono é a voz que mais “cruza”: às vezes canta abaixo da melodia, às vezes acima. Nesses pontos, é fácil ser puxado para a melodia."},{"type":"audio","label":"Exemplo: melodia Sol–Lá–Si com o barítono uma terça ACIMA","notes":[["G3","B3"],["A3","C4"],["B3","D4"]],"tempo":60},{"type":"check","question":"Qual é a melhor forma de o barítono estudar os cruzamentos?","options":["Marcar esses trechos e estudá-los separadamente","Seguir a melodia nesses pontos","Cantar mais forte para não se perder"],"answer":0,"explain":"Isolar os pontos de cruzamento e repeti-los no modo solo e guiado evita cair na melodia."}]},{"titulo":"Agudo leve, sem empurrar","tipo":"experimentar","blocos":[{"type":"warning","text":"Primeiro tenor: não force a voz de peito no agudo. Use voz leve (mista ou de cabeça) e volume moderado. Se doer, pare."},{"type":"timer","instruction":"Faça uma sirene suave em “u”, do grave ao agudo e de volta, sem empurrar e em volume moderado.","seconds":10,"reps":3},{"type":"toolLink","tool":"extensao","label":"Escolha a sua voz pela região confortável: teste a extensão"}]},{"titulo":"Hora do quarteto","tipo":"aplicar","blocos":[{"type":"harmonyLink","arrangement":"que-grande-amor-ttbb","label":"“Que grande amor”: quarteto masculino"},{"type":"checklist","title":"Roteiro de estudo","items":["Ouvi no modo conjunto acompanhando a melodia no 2º tenor","Escolhi a minha voz pela região confortável","Estudei no solo e no guiado, marcando os cruzamentos","Cantei no modo conjunto e gravei","Sustentei o acorde final ouvindo as outras vozes"]}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada voz do quarteto à sua função.","pairs":[{"left":"Primeiro tenor","right":"Acima da melodia, voz leve"},{"left":"Segundo tenor","right":"Melodia (o “lead”)"},{"left":"Barítono","right":"Completa o acorde e cruza a melodia"},{"left":"Baixo","right":"Fundamental e alicerce rítmico"}]}]}],"pratiqueSozinho":{"passos":["Treinador: sua voz em “Que grande amor”.","Afinação vertical: sustente o acorde final ouvindo as outras vozes."],"minutos":12,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Barítono seguindo a melodia quando ela cruza a sua linha.","correcao":"Estude os pontos de cruzamento separadamente."},{"erro":"Primeiro tenor forçando a voz de peito no agudo.","correcao":"Use voz leve (mista ou de cabeça) e volume moderado."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação e cantar uma parte do quarteto no modo conjunto."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'harmonia-tres-quatro-vozes' from public.lessons where slug = 'quarteto-masculino' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:quarteto-treinador')::uuid, 'quarteto-treinador', (select id from public.lessons where slug = 'quarteto-masculino'), 'Prática: sua voz no quarteto', 'Cante uma voz de “Que grande amor” no treinador.', 'harmony_part', '{"voices":4,"arrangementSlug":"que-grande-amor-ttbb"}'::jsonb, 'harmonia-tres-quatro-vozes', 'pratica', 3, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:quarteto-avaliacao')::uuid, 'quarteto-avaliacao', (select id from public.lessons where slug = 'quarteto-masculino'), 'Avaliação: vozes do quarteto masculino', 'Responda sobre a formação TTBB.', 'quiz', '{"questions":[{"q":"No estilo barbershop, o segundo tenor costuma ser chamado de “lead” porque…","options":["Canta a melodia","Rege o grupo","Canta mais forte","É o mais grave"],"answer":0},{"q":"Qual voz do quarteto mais frequentemente cruza a melodia?","options":["Barítono","Baixo","Primeiro tenor","Nenhuma"],"answer":0},{"q":"A nomenclatura das vozes num quarteto…","options":["Pode variar conforme o arranjo e a tradição","É sempre a mesma","Não existe","Depende só da altura dos cantores"],"answer":0},{"q":"Por que a afinação é tão sensível no quarteto masculino?","options":["As vozes ficam numa região próxima e o som é muito unido","Porque são só quatro pessoas","Porque não há melodia","Não é sensível"],"answer":0}]}'::jsonb, 'harmonia-tres-quatro-vozes', 'avaliacao', 3, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:afinacao-de-acordes')::uuid, (select id from public.learning_paths where slug = 'harmonia-vocal'), 'afinacao-de-acordes', 'Afinação de acordes', 'Afinação vertical: quando o acorde “encaixa”.', 5, 3, 20, '{"objetivo":"Perceber e ajustar a afinação vertical de acordes sustentados e reconhecer quando uma voz está acima ou abaixo.","gancho":"Sabe aquele acorde final que parece “brilhar” e arrepia a igreja? Isso tem nome: afinação vertical. E dá para treinar.","etapas":[{"titulo":"Horizontal e vertical","tipo":"descobrir","blocos":[{"type":"list","items":["Afinação horizontal: a de cada voz ao longo da melodia.","Afinação vertical: a do acorde, o quanto as notas cantadas ao mesmo tempo se encaixam."]},{"type":"illustration","name":"onda-afinada","caption":"Notas que se encaixam: o som fica estável."},{"type":"callout","icon":"estrela","title":"O acorde que brilha","text":"Quando o acorde está bem afinado, ele parece mais forte. Às vezes ouvimos até notas que ninguém está cantando: os harmônicos."},{"type":"check","question":"Quatro cantores sustentam um acorde final. Que afinação está em jogo?","options":["Vertical: as notas soando juntas","Horizontal: a melodia de cada um","Nenhuma, é só manter o volume"],"answer":0,"explain":"Notas cantadas ao mesmo tempo formam a afinação vertical."}]},{"titulo":"Ouça a diferença","tipo":"ouvir","blocos":[{"type":"compare","prompt":"O mesmo acorde de Dó maior duas vezes. Em qual deles TODAS as vozes estão afinadas?","options":[{"label":"acorde afinado","notes":[["C3","G3","C4","E4"]],"mode":"chord"},{"label":"soprano (Mi) um pouco abaixo","notes":[["C3","G3","C4","E4"]],"mode":"chord","voiceCents":[0,0,0,-35]}],"answer":0,"explain":"Basta uma voz fora do lugar para o acorde ondular e perder o brilho. No afinado, o som fica estável."},{"type":"illustration","name":"onda-desafinada","caption":"Notas fora do encaixe: o som “bate”."}]},{"titulo":"Esqueleto e recheio","tipo":"descobrir","blocos":[{"type":"list","items":["Afine a partir do baixo: ele dá a referência.","Oitavas e quintas precisam estar exatas: são o “esqueleto” do acorde.","A terça maior encaixa um pouco mais baixa que no teclado; a menor, um pouco mais alta."]},{"type":"audio","label":"Quinta justa (Dó3–Sol3) e depois o acorde com a terça","notes":[["C3","G3"],["C3","G3","E4"]],"tempo":25},{"type":"trueFalse","items":[{"statement":"O certo é afinar pela voz mais forte do grupo.","answer":false,"explain":"Afine pelo baixo e pela fundamental do acorde."},{"statement":"Oitavas e quintas precisam estar exatas.","answer":true,"explain":"Elas sustentam o acorde. Com o esqueleto firme, a terça encontra o seu lugar."}]}]},{"titulo":"Sustente sem deixar cair","tipo":"experimentar","blocos":[{"type":"tip","text":"Notas longas tendem a cair. Mantenha o fluxo de ar e o espaço interno até o corte."},{"type":"breathing","inhale":4,"exhale":8,"rounds":2,"exhaleOn":"sss"},{"type":"singAlong","instruction":"Sustente a nota em “u” até o fim, sem deixar cair. Observe o ponteiro no final.","note":"C4","seconds":5}]},{"titulo":"Desafio: só 25 cents","tipo":"ouvir","blocos":[{"type":"audio","label":"Referência: Fá maior afinado (o contralto canta Lá3)","notes":[["F2","C3","A3","F4"]],"mode":"chord","tempo":30},{"type":"compare","prompt":"Diferença pequena! Em qual destes acordes o contralto (Lá) está ABAIXO?","options":[{"label":"todos afinados","notes":[["F2","C3","A3","F4"]],"mode":"chord"},{"label":"contralto um pouco acima","notes":[["F2","C3","A3","F4"]],"mode":"chord","voiceCents":[0,0,25,0]},{"label":"contralto um pouco abaixo","notes":[["F2","C3","A3","F4"]],"mode":"chord","voiceCents":[0,0,-25,0]}],"answer":2,"explain":"25 cents é um quarto de semitom. Ouvir isso dentro do acorde exige atenção, e é exatamente o ajuste fino da afinação vertical."}]},{"titulo":"No ensaio","tipo":"aplicar","blocos":[{"type":"harmonyLink","arrangement":"acordes-sustentados-satb","label":"Acordes sustentados SATB"},{"type":"timer","instruction":"Cante a sua voz no modo guiado ouvindo o baixo. Sustente cada acorde por 4 tempos, prestando atenção ao “encaixe”.","seconds":30},{"type":"check","question":"No ensaio, o acorde está “batendo” e uma voz está bem mais forte que as outras. Por onde você se guia?","options":["Pelo baixo e pela fundamental do acorde","Pela voz mais forte","Pelo teclado, ignorando o grupo"],"answer":0,"explain":"O baixo dá a referência. A voz mais forte pode estar justamente fora do lugar."},{"type":"toolLink","tool":"afinador","label":"Confira a sua nota sustentada no afinador"}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"order","prompt":"Coloque na ordem para afinar um acorde sustentado.","items":["O baixo firma a fundamental","Oitavas e quintas se ajustam ao baixo","A terça encontra o encaixe","Todos mantêm o apoio do ar até o corte"]}]}],"pratiqueSozinho":{"passos":["Laboratório: perceber desafinação no nível recomendado.","Acordes sustentados no modo conjunto."],"minutos":8,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Afinar pela voz mais forte do grupo.","correcao":"Afine pelo baixo e pela fundamental do acorde."},{"erro":"Deixar a nota cair no final.","correcao":"Mantenha o fluxo de ar e o espaço interno até o corte."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes."],"criterioAvanco":"Acertar pelo menos 70% na avaliação com diferenças de 25 cents."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
