insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:afinacao-acordes-avaliacao')::uuid, 'afinacao-acordes-avaliacao', (select id from public.lessons where slug = 'afinacao-de-acordes'), 'Avaliação: afinada, acima ou abaixo (25 cents)', 'Diferenças menores exigem atenção.', 'tuning_check', '{"rounds":10,"cents":25}'::jsonb, 'percepcao-afinacao', 'avaliacao', 3, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:afinacao-acordes-treinador')::uuid, 'afinacao-acordes-treinador', (select id from public.lessons where slug = 'afinacao-de-acordes'), 'Prática: acordes sustentados', 'Cante a sua voz nos acordes sustentados.', 'harmony_part', '{"voices":4,"arrangementSlug":"acordes-sustentados-satb"}'::jsonb, 'harmonia-tres-quatro-vozes', 'pratica', 3, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:independencia-vocal')::uuid, (select id from public.learning_paths where slug = 'harmonia-vocal'), 'independencia-vocal', 'Independência vocal', 'Ouvir o conjunto sem abandonar a própria voz.', 6, 3, 25, '{"objetivo":"Manter a própria linha com todas as vozes soando no mesmo volume, inclusive com entradas independentes e melodias em movimento contrário.","gancho":"Quem nunca se pegou cantando a melodia sem querer, quando a ideia era cantar o contralto ou o tenor? Hoje você treina para ficar firme na sua linha, ouvindo todo mundo.","etapas":[{"titulo":"Ouvir sem se perder","tipo":"descobrir","blocos":[{"type":"illustration","name":"escuta-ativa"},{"type":"p","text":"Independência vocal é cantar a sua linha com segurança enquanto ouve o conjunto. Não é ignorar os outros: é ouvir, se localizar e continuar na sua parte."},{"type":"check","question":"Qual frase descreve melhor a independência vocal?","options":["Ouvir o conjunto e continuar na sua parte","Tapar um ouvido e ignorar as outras vozes","Cantar mais alto que os outros para não se perder"],"answer":0,"explain":"Independência não é isolamento: as outras vozes são suas referências."}]},{"titulo":"Suas âncoras","tipo":"descobrir","blocos":[{"type":"illustration","name":"equilibrio"},{"type":"list","items":["Conheça a sua parte de cor antes do conjunto.","Saiba onde estão as notas-âncora e as entradas.","Ouça a voz logo acima e logo abaixo da sua: elas são suas referências."]},{"type":"callout","icon":"ideia","title":"Pense num GPS","text":"As vozes vizinhas e as notas-âncora mostram onde você está. Se o sinal cair, você recalcula a rota na próxima âncora."}]},{"titulo":"Firme contra a correnteza","tipo":"experimentar","blocos":[{"type":"audio","label":"A melodia que vai tentar te puxar","notes":["E4","F4","G4","A4","G4","F4","E4","D4"],"tempo":90},{"type":"singAlong","instruction":"Agora sustente o Dó em “u” por 5 segundos, firme, pensando só na sua nota.","note":"C4","seconds":5},{"type":"reveal","prompt":"Toque a melodia de novo e, enquanto ela soa, sustente o mesmo Dó. Você sentiu vontade de seguir a melodia?","answer":"É normal sentir o “puxão”. Pense na sua nota antes de cantá-la e mantenha o volume confortável. Com prática, a sua linha fica firme mesmo com outra melodia ao lado."}]},{"titulo":"Movimento contrário: o grande teste","tipo":"ouvir","blocos":[{"type":"p","text":"Quando as vozes vão em direções opostas, é fácil ser arrastado(a). Pense na direção da SUA linha antes de cada nota."},{"type":"check","question":"Ouça as duas vozes. A voz grave sobe ou desce?","audio":{"notes":[["G4","G3"],["F4","A3"],["E4","B3"],["D4","C4"]],"mode":"seq","tempo":60},"options":["Sobe (Sol–Lá–Si–Dó)","Desce junto com a aguda","Fica parada"],"answer":0,"explain":"A aguda desce de Sol para Ré enquanto a grave sobe de Sol para Dó: movimento contrário."}]},{"titulo":"Se errar, não pare","tipo":"checar","blocos":[{"type":"callout","icon":"coracao","title":"O grupo segue junto","text":"Se você se perder, não pare o grupo. Fique em silêncio um instante, ouça e volte na próxima âncora ou na próxima frase."},{"type":"trueFalse","items":[{"statement":"Se me perder no culto, devo parar e esperar o grupo recomeçar.","answer":false,"explain":"Continue e retome na próxima âncora. O grupo não para."},{"statement":"Saber a parte de cor ajuda a ouvir melhor as outras vozes.","answer":true,"explain":"Sem precisar pensar em cada nota, sobra atenção para ouvir o conjunto."},{"statement":"A voz logo acima e logo abaixo da minha são boas referências.","answer":true,"explain":"São as vizinhas que mostram onde você está no acorde."}]}]},{"titulo":"Treine no modo conjunto","tipo":"aplicar","blocos":[{"type":"harmonyLink","arrangement":"canone-solfejo","label":"Cânone a quatro vozes"},{"type":"harmonyLink","arrangement":"hino-alegria-satb","label":"SATB no modo conjunto"},{"type":"checklist","title":"Desafio da semana","items":["Cantei a voz 3 do cânone no modo conjunto","Cantei a minha voz do SATB no mesmo volume das outras","Fiz a avaliação de sustentação com distração","Cada dia, uma voz diferente do cânone"]}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada momento à atitude certa.","pairs":[{"left":"Antes do conjunto","right":"Saber a parte de cor"},{"left":"Antes da sua entrada","right":"Contar os tempos"},{"left":"Para se localizar","right":"Ouvir as vozes vizinhas"},{"left":"Se se perder","right":"Voltar na próxima âncora"}]}]}],"pratiqueSozinho":{"passos":["Cânone: cada dia uma voz diferente.","Sustentação com distração: 3 notas por dia."],"minutos":10,"frequencia":"4 vezes por semana"},"errosComuns":[{"erro":"Parar quando erra.","correcao":"No grupo, continue e retome na próxima âncora."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Média de 70% na sustentação com distração e voz cantada no modo conjunto."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
