insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:independencia-canone')::uuid, 'independencia-canone', (select id from public.lessons where slug = 'independencia-vocal'), 'Prática: cânone a quatro vozes', 'Cante uma voz do cânone no modo conjunto.', 'harmony_part', '{"voices":4,"arrangementSlug":"canone-solfejo"}'::jsonb, 'independencia-vocal', 'pratica', 3, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:independencia-avaliacao')::uuid, 'independencia-avaliacao', (select id from public.lessons where slug = 'independencia-vocal'), 'Avaliação: sustentação com distração', 'Sustente a sua nota enquanto outra melodia soa (use fones com o microfone).', 'sing_note', '{"rounds":4,"holdSeconds":5,"toleranceCents":25,"distractor":true}'::jsonb, 'independencia-vocal', 'avaliacao', 3, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:arranjos-avancados')::uuid, (select id from public.learning_paths where slug = 'harmonia-vocal'), 'arranjos-avancados', 'Arranjos avançados', 'Contracanto, pedal, dinâmica por naipe, modulação e adaptação de tonalidade.', 7, 3, 30, '{"objetivo":"Conhecer recursos de arranjo vocal — contracanto, pedal harmônico, introduções e interlúdios vocais, modulação, dinâmica por naipe e construção de clímax — e saber adaptar a tonalidade ao grupo.","gancho":"Por que a última estrofe às vezes “sobe” e arrepia a igreja inteira? Hoje você conhece os recursos de arranjo que fazem um hino crescer.","etapas":[{"titulo":"Uma melodia por cima da melodia","tipo":"ouvir","blocos":[{"type":"p","text":"Contracanto é uma segunda melodia independente, geralmente acima da principal (o descante), que dialoga com ela."},{"type":"compare","prompt":"Ouça a melodia sozinha e depois com um contracanto acima.","options":[{"label":"Só a melodia","notes":["E4","D4","C4","D4","E4"],"tempo":70},{"label":"Melodia + contracanto","notes":[["E4","G4"],["D4","B4"],["C4","C5"],["D4","B4"],["E4","G4"]],"tempo":70}],"explain":"Quando a melodia desce, o contracanto sobe: as duas linhas conversam. O contracanto colore, mas a melodia continua sendo a principal."},{"type":"check","question":"Qual das duas deve soar mais?","options":["A melodia","O contracanto","Tanto faz"],"answer":0,"explain":"O contracanto mais forte que a melodia é um erro comum. Ele enfeita; a melodia lidera."}]},{"titulo":"Pedal: a nota que não sai do lugar","tipo":"ouvir","blocos":[{"type":"callout","icon":"musica","title":"Como o pedal do órgão","text":"Pedal harmônico é uma nota sustentada, muitas vezes a tônica ou a dominante no baixo, enquanto os acordes mudam acima dela."},{"type":"check","question":"Ouça. Qual voz está parada?","audio":{"notes":[["G3","E4"],["G3","D4"],["G3","C4"],["G3","B3"],["G3","C4"]],"mode":"seq","tempo":70},"options":["A grave (Sol sustentado)","A aguda","Nenhuma das duas"],"answer":0,"explain":"A voz grave sustenta Sol (a dominante de Dó) enquanto a aguda se move: um pedal."},{"type":"tip","text":"Quem canta o pedal mantém a nota firme, mesmo quando a melodia passa por notas que “brigam” com ela."}]},{"titulo":"Subir um tom na última estrofe","tipo":"ouvir","blocos":[{"type":"compare","prompt":"A mesma frase antes e depois de uma modulação.","options":[{"label":"Em Dó maior","notes":["C4","E4","G4","E4","C4"],"tempo":80},{"label":"Um tom acima, em Ré maior","notes":["D4","F#4","A4","F#4","D4"],"tempo":80}],"explain":"Modulação é mudar de tonalidade. Subir um tom na última estrofe dá a sensação de elevação."},{"type":"warning","text":"Não module sem preparar a nova nota de entrada: ensaiem a passagem separadamente."}]},{"titulo":"Mais cores no arranjo","tipo":"descobrir","blocos":[{"type":"illustration","name":"campo-harmonico","caption":"Os acordes disponíveis numa tonalidade."},{"type":"list","items":["Introduções e interlúdios vocais: trechos em “u”, “m” ou sílabas que preparam o texto.","Rearmonização: trocar alguns acordes mantendo a melodia (ex.: vi no lugar de I).","Acordes de passagem: acordes rápidos que ligam dois acordes principais."]},{"type":"compare","prompt":"A melodia canta Mi nos dois. Só o acorde muda.","options":[{"label":"Com Dó maior (I)","notes":[["C3","G3","C4","E4"]],"mode":"chord"},{"label":"Com Lá menor (vi)","notes":[["A2","A3","C4","E4"]],"mode":"chord"}],"explain":"Mi pertence aos dois acordes. Trocar o I pelo vi deixa a mesma nota mais suave e reflexiva."}]},{"titulo":"Clímax e dinâmica por naipe","tipo":"descobrir","blocos":[{"type":"illustration","name":"dinamica"},{"type":"p","text":"Os naipes podem entrar aos poucos, a dinâmica cresce e o ponto mais alto coincide com a frase mais importante do texto."},{"type":"reveal","prompt":"Pense num hino que o seu grupo canta. Em qual frase do texto você colocaria o clímax?","answer":"Escolha a frase que carrega a mensagem central. Planeje para chegar nela com todos os naipes e a dinâmica mais forte, e não antes."}]},{"titulo":"A tonalidade certa para todos","tipo":"aplicar","blocos":[{"type":"p","text":"A melhor tonalidade coloca a melodia na região confortável do grupo e da congregação. Para louvor congregacional, mantenha a melodia aproximadamente entre Si♭3 e Ré5."},{"type":"keyboard","from":"A3","to":"E5","highlight":["Bb3","D5"],"label":"Região confortável da melodia congregacional"},{"type":"check","question":"A melodia de um louvor vai até Fá5 e a congregação sofre no refrão. O que fazer?","options":["Descer a tonalidade até a melodia caber na região confortável","Manter, porque é o tom da gravação","Pedir para todos cantarem mais forte"],"answer":0,"explain":"O critério é a região confortável do grupo e da congregação, não a gravação original."}]},{"titulo":"No treinador de harmonia","tipo":"aplicar","blocos":[{"type":"harmonyLink","arrangement":"hino-alegria-contracanto","label":"Hino da Alegria com contracanto e pedal"},{"type":"harmonyLink","arrangement":"pedal-e-melodia","label":"Nota pedal e melodia"},{"type":"checklist","title":"Roteiro de estudo","items":["Ouvi o arranjo no modo conjunto e identifiquei as três camadas","Cantei o contracanto (vozes agudas) ou o pedal (vozes graves) no modo guiado","Transpus +2 semitons: ficou mais confortável para o grupo?","Marquei o compasso do clímax do texto"]}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada recurso de arranjo à sua definição.","pairs":[{"left":"Contracanto","right":"Segunda melodia que dialoga com a principal"},{"left":"Pedal","right":"Nota sustentada enquanto os acordes mudam"},{"left":"Modulação","right":"Mudança de tonalidade"},{"left":"Acorde de passagem","right":"Acorde rápido que liga dois acordes"},{"left":"Rearmonização","right":"Trocar acordes mantendo a melodia"}]}]}],"pratiqueSozinho":{"passos":["Treinador: contracanto ou pedal no modo conjunto.","Escolha uma música do repertório e anote onde caberia um pedal ou uma modulação."],"minutos":15,"frequencia":"2 vezes por semana"},"errosComuns":[{"erro":"Contracanto mais forte que a melodia.","correcao":"O contracanto colore; a melodia continua sendo a principal."},{"erro":"Modular sem preparar a nova nota de entrada.","correcao":"Ensaiem a passagem da modulação separadamente."}],"seguranca":["Interrompa o exercício imediatamente em caso de dor, ardência, rouquidão ou desconforto.","Beba água ao longo do estudo e evite cantar após gritar ou falar por muito tempo.","Estude com volume moderado; exercícios longos não precisam ser fortes.","Rouquidão que dura mais de duas semanas deve ser avaliada por um profissional de saúde (otorrinolaringologista ou fonoaudiólogo)."],"criterioAvanco":"Acertar pelo menos 70% da avaliação."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
