insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:avancado-treinador')::uuid, 'avancado-treinador', (select id from public.lessons where slug = 'arranjos-avancados'), 'Prática: contracanto e pedal', 'Cante uma camada do arranjo com contracanto.', 'harmony_part', '{"voices":3,"arrangementSlug":"hino-alegria-contracanto"}'::jsonb, 'harmonia-tres-quatro-vozes', 'pratica', 3, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:avancado-avaliacao')::uuid, 'avancado-avaliacao', (select id from public.lessons where slug = 'arranjos-avancados'), 'Avaliação: recursos de arranjo', 'Responda sobre arranjos avançados.', 'quiz', '{"questions":[{"q":"Uma nota sustentada no baixo enquanto os acordes mudam acima é um…","options":["Pedal harmônico","Contracanto","Cânone","Acorde de passagem"],"answer":0},{"q":"Contracanto é…","options":["Uma segunda melodia independente que dialoga com a principal","A melodia cantada mais forte","Cantar sem texto","Um tipo de respiração"],"answer":0},{"q":"Uma modulação comum para a última estrofe é…","options":["Subir um tom","Descer uma oitava","Mudar para compasso ternário","Retirar o baixo"],"answer":0},{"q":"O critério principal para escolher a tonalidade de um louvor congregacional é…","options":["A região confortável do grupo e da congregação","A tonalidade da gravação original","A preferência do instrumentista","Ser sempre Dó maior"],"answer":0},{"q":"Ouça: há uma nota grave sustentada enquanto a melodia se move?","options":["Sim, um pedal","Não"],"answer":0,"audio":{"notes":[["C3","C4"],["C3","D4"],["C3","E4"],["C3","F4"],["C3","E4"]],"mode":"seq","tempo":80}}]}'::jsonb, 'teoria-harmonia', 'avaliacao', 3, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.learning_paths (id, slug, code, title, subtitle, description, icon, sort) values (md5('path:leitura-musical')::uuid, 'leitura-musical', 'E', 'Leitura musical', 'Da pauta à partitura vocal', 'Ler música dá autonomia para estudar a própria voz. A trilha cobre notas na pauta, figuras rítmicas e compassos, claves, intervalos escritos, cifras e a leitura de partituras corais.', 'book-open', 4) on conflict (slug) do update set code = excluded.code, title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, icon = excluded.icon, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:notas-na-pauta')::uuid, (select id from public.learning_paths where slug = 'leitura-musical'), 'notas-na-pauta', 'Notas na pauta', 'Linhas, espaços e a clave de Sol.', 0, 1, 20, '{"objetivo":"Ler as notas naturais na clave de Sol, da região do dó central até o Sol5.","gancho":"Cinco linhas, quatro espaços e uma palavra mágica: FALADOMI. Em poucos minutos você vai ler a linha do soprano de um hino sem pedir ajuda.","etapas":[{"titulo":"Uma escada de cinco linhas","tipo":"descobrir","blocos":[{"type":"illustration","name":"pauta","caption":"Linhas e espaços contam de baixo para cima."},{"type":"p","text":"A pauta (ou pentagrama) tem cinco linhas e quatro espaços. Cada linha e cada espaço é uma nota. Quanto mais acima, mais aguda. Para ir além da pauta, usamos pequenas linhas extras: as linhas suplementares."},{"type":"check","question":"Uma nota na 4ª linha soa mais aguda ou mais grave que uma nota na 2ª linha?","options":["Mais aguda","Mais grave","Igual: as duas estão em linhas"],"answer":0,"explain":"Na pauta, subir é ficar mais agudo. A 4ª linha está acima da 2ª, então a nota é mais aguda."}]},{"titulo":"A clave que abraça o Sol","tipo":"descobrir","blocos":[{"type":"illustration","name":"claves","caption":"A clave de Sol começa enrolada na 2ª linha."},{"type":"callout","icon":"olho","title":"Siga o caracol","text":"O desenho da clave de Sol começa com um caracol enrolado na 2ª linha. Essa linha é o Sol (Sol4). Daí em diante é só contar: linha, espaço, linha, espaço…"},{"type":"check","question":"Qual é esta nota?","staff":{"clef":"sol","notes":["G4"]},"options":["Sol","Lá","Mi","Fá"],"answer":0,"explain":"Está na 2ª linha, onde a clave de Sol se enrola. É o Sol4, sua primeira âncora."}]},{"titulo":"FALADOMI: os espaços","tipo":"descobrir","blocos":[{"type":"staff","clef":"sol","notes":["F4","A4","C5","E5"],"label":"Os quatro espaços: Fá, Lá, Dó, Mi"},{"type":"callout","icon":"ideia","title":"Uma palavra só","text":"Lendo os espaços de baixo para cima você tem Fá-Lá-Dó-Mi. Junte tudo: “FALADOMI”. Repita três vezes em voz alta e não esquece mais."},{"type":"check","question":"Qual é esta nota?","staff":{"clef":"sol","notes":["C5"]},"options":["Dó","Lá","Si","Ré"],"answer":0,"explain":"É o 3º espaço: Fá, Lá, DÓ. Esse Dó5 é mais uma âncora."}]},{"titulo":"As linhas pulam uma nota","tipo":"descobrir","blocos":[{"type":"staff","clef":"sol","notes":["E4","G4","B4","D5","F5"],"label":"As cinco linhas: Mi, Sol, Si, Ré, Fá"},{"type":"callout","icon":"musica","title":"Mi, Sol, Si, Ré, Fá","text":"De uma linha para a seguinte você pula uma nota: Mi (Fá) Sol (Lá) Si (Dó) Ré (Mi) Fá. As notas puladas são justamente o FALADOMI dos espaços."},{"type":"check","question":"Qual é esta nota?","staff":{"clef":"sol","notes":["E4"]},"options":["Mi","Fá","Ré","Sol"],"answer":0,"explain":"1ª linha, a de baixo: Mi4. Uma linha abaixo do Sol da clave, pulando o Fá."}]},{"titulo":"Três âncoras no teclado","tipo":"experimentar","blocos":[{"type":"illustration","name":"linhas-suplementares","caption":"O Dó central mora numa linha suplementar abaixo da pauta."},{"type":"keyboard","from":"C4","to":"G5","highlight":["C4","G4","C5"],"label":"Âncoras: Dó4, Sol4 e Dó5"},{"type":"staff","clef":"sol","notes":["C4","D4","E4","F4","G4","A4","B4","C5"],"label":"Escala de Dó4 a Dó5"},{"type":"timer","instruction":"Aponte cada nota da escala e diga o nome em voz alta. Toque no teclado se quiser conferir. O Ré4 fica logo abaixo da 1ª linha.","seconds":30}]},{"titulo":"Qual é esta nota?","tipo":"checar","blocos":[{"type":"check","question":"Qual é esta nota?","staff":{"clef":"sol","notes":["A4"]},"options":["Lá","Sol","Si","Dó"],"answer":0,"explain":"2º espaço: Fá, LÁ. Ou parta da âncora Sol (2ª linha) e suba um degrau."},{"type":"check","question":"Qual é esta nota?","staff":{"clef":"sol","notes":["D4"]},"options":["Ré","Dó","Mi","Si"],"answer":0,"explain":"Fica logo abaixo da 1ª linha (Mi), sem linha suplementar: é o Ré4."},{"type":"check","question":"Qual é esta nota?","staff":{"clef":"sol","notes":["F5"]},"options":["Fá","Mi","Sol","Ré"],"answer":0,"explain":"5ª linha, a última de cima: Mi, Sol, Si, Ré, FÁ."}]},{"titulo":"Leia um hino de verdade","tipo":"aplicar","blocos":[{"type":"staff","clef":"sol","notes":["E4","E4","F4","G4","G4","F4","E4","D4"],"label":"Início do soprano no Hino da Alegria"},{"type":"reveal","prompt":"Diga os nomes das oito notas antes de tocar para ver.","answer":"Mi, Mi, Fá, Sol, Sol, Fá, Mi, Ré. Usou as âncoras? O Sol da 2ª linha resolve quase tudo aqui."},{"type":"toolLink","tool":"teclado","label":"Toque a frase no teclado e cante junto"}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada lugar da pauta (clave de Sol) à sua nota.","pairs":[{"left":"Linha suplementar abaixo","right":"Dó4"},{"left":"1ª linha","right":"Mi4"},{"left":"2ª linha","right":"Sol4"},{"left":"3º espaço","right":"Dó5"},{"left":"5ª linha","right":"Fá5"}]}]}],"pratiqueSozinho":{"passos":["5 minutos de leitura de notas por dia.","Leia a linha do soprano de um hino conhecido dizendo os nomes das notas."],"minutos":5,"frequencia":"Diariamente por duas semanas"},"errosComuns":[{"erro":"Contar as linhas de cima para baixo.","correcao":"Linhas e espaços são contados de baixo para cima."},{"erro":"Confundir notas em linha e em espaço vizinhos.","correcao":"Olhe se a linha passa pelo meio da nota (linha) ou se a nota está entre duas linhas (espaço)."}],"seguranca":["A leitura cansa a vista e a mente: faça pausas curtas a cada 15 minutos."],"criterioAvanco":"Acertar pelo menos 70% na avaliação de leitura na clave de Sol."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
