insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:pauta-pratica')::uuid, 'pauta-pratica', (select id from public.lessons where slug = 'notas-na-pauta'), 'Prática: Dó4 a Dó5', 'Qual é o nome da nota?', 'staff_read', '{"rounds":8,"clef":"sol","range":["C4","C5"]}'::jsonb, 'leitura-pauta', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:pauta-avaliacao')::uuid, 'pauta-avaliacao', (select id from public.lessons where slug = 'notas-na-pauta'), 'Avaliação: clave de Sol', 'Qual é o nome da nota?', 'staff_read', '{"rounds":10,"clef":"sol","range":["C4","G5"]}'::jsonb, 'leitura-pauta', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:figuras-ritmicas-e-compassos')::uuid, (select id from public.learning_paths where slug = 'leitura-musical'), 'figuras-ritmicas-e-compassos', 'Ritmo: figuras e compassos', 'Semibreve, mínima, semínima, colcheia, pausas e fórmulas de compasso.', 1, 1, 25, '{"objetivo":"Ler as figuras rítmicas e as pausas mais comuns e compreender os compassos simples 2/4, 3/4 e 4/4.","gancho":"Ritmo é matemática que se dança. Com uma pizza imaginária e três sílabas (tá, ti-ti, tá-a) você vai ler qualquer ritmo de hino.","etapas":[{"titulo":"A pizza do ritmo","tipo":"descobrir","blocos":[{"type":"illustration","name":"figuras-ritmicas","caption":"Cada figura vale metade da anterior."},{"type":"callout","icon":"ideia","title":"Corte a pizza ao meio","text":"A semibreve é a pizza inteira: 4 tempos. A mínima é meia pizza: 2 tempos. A semínima, um quarto: 1 tempo. A colcheia, meio tempo. A semicolcheia, um quarto de tempo."},{"type":"check","question":"Quantas semínimas cabem numa mínima?","options":["2","4","1","3"],"answer":0,"explain":"A mínima vale 2 tempos e a semínima vale 1. Meia pizza = dois pedaços de um quarto."}]},{"titulo":"Ouça as figuras","tipo":"ouvir","blocos":[{"type":"p","text":"Os quatro exemplos ocupam o mesmo espaço: um compasso de 4 tempos. Só muda quantas notas cabem nele."},{"type":"rhythm","pattern":"w","bpm":80,"label":"Semibreve (4 tempos)"},{"type":"rhythm","pattern":"h h","bpm":80,"label":"Duas mínimas"},{"type":"rhythm","pattern":"q q q q","bpm":80,"label":"Quatro semínimas"},{"type":"rhythm","pattern":"e e e e e e e e","bpm":80,"label":"Oito colcheias (duas por tempo)"}]},{"titulo":"Fale o ritmo","tipo":"experimentar","blocos":[{"type":"list","items":["Semínima: “tá” (1 tempo).","Duas colcheias: “ti-ti” (as duas num tempo).","Mínima: “tá-a” (segure por 2 tempos)."]},{"type":"rhythm","pattern":"q e e q q","bpm":72,"label":"tá, ti-ti, tá, tá"},{"type":"rhythm","pattern":"q q h","bpm":72,"label":"tá, tá, tá-a"},{"type":"timer","instruction":"Bata o pé no pulso e fale as sílabas dos dois ritmos acima, duas vezes cada.","seconds":30}]},{"titulo":"O ponto que estica","tipo":"descobrir","blocos":[{"type":"callout","icon":"estrela","title":"Ponto = mais metade","text":"O ponto de aumento soma metade do valor da figura. Mínima pontuada: 2 + 1 = 3 tempos. Semínima pontuada: 1 + ½ = 1 tempo e meio."},{"type":"rhythm","pattern":"h. q","bpm":80,"label":"Mínima pontuada e semínima"},{"type":"rhythm","pattern":"q. e q q","bpm":80,"label":"“tá—a-ti, tá, tá”"},{"type":"check","question":"Quanto vale uma semínima pontuada?","options":["1 tempo e meio","2 tempos","1 tempo","3 tempos"],"answer":0,"explain":"Semínima = 1 tempo; metade dela = meio tempo. Somando: 1 tempo e meio."}]},{"titulo":"O silêncio também conta","tipo":"ouvir","blocos":[{"type":"p","text":"Cada figura tem uma pausa com a mesma duração, só que em silêncio. Na pausa o pulso continua: aproveite para respirar."},{"type":"rhythm","pattern":"rq q q q","bpm":72,"label":"Pausa de semínima e três semínimas"},{"type":"trueFalse","items":[{"statement":"Na pausa, posso parar de contar.","answer":false,"explain":"O pulso não para. Quem para de contar entra atrasado(a)."},{"statement":"A pausa de mínima vale 2 tempos de silêncio.","answer":true,"explain":"Toda pausa tem o valor da figura correspondente."},{"statement":"O ponto também pode aparecer em pausas.","answer":true,"explain":"Sim: a pausa pontuada também ganha metade do seu valor."}]}]},{"titulo":"A fração do compasso","tipo":"descobrir","blocos":[{"type":"illustration","name":"compasso","caption":"O número de cima conta os tempos; o de baixo diz qual figura vale um tempo."},{"type":"p","text":"A fórmula de compasso aparece no início da música. Em 2/4, 3/4 e 4/4, o 4 de baixo significa que a semínima vale um tempo. O número de cima diz quantos tempos cabem em cada compasso."},{"type":"check","question":"No compasso 3/4, quanto cabe em cada compasso?","options":["Três semínimas","Três mínimas","Quatro semínimas","Três colcheias"],"answer":0,"explain":"3 tempos (em cima), cada um valendo uma semínima (o 4 embaixo). É o compasso de muitos hinos, como “Que grande amor”."}]},{"titulo":"Ritmo no ensaio","tipo":"aplicar","blocos":[{"type":"illustration","name":"pulso"},{"type":"check","question":"No fim da primeira frase do Hino da Alegria aparece o ritmo “tá—a-ti”, um longo e um curto. Que figuras são essas?","options":["Semínima pontuada + colcheia","Duas semínimas","Mínima + semínima","Duas colcheias"],"answer":0,"explain":"O “tá—a” longo é a semínima pontuada (1 tempo e meio) e o “ti” curto é a colcheia (meio tempo). Juntas fecham 2 tempos."},{"type":"toolLink","tool":"metronomo","label":"Ligue o metrônomo a 72 e fale o ritmo da sua voz num hino"}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada figura à sua duração (em compassos de semínima).","pairs":[{"left":"Semibreve","right":"4 tempos"},{"left":"Mínima pontuada","right":"3 tempos"},{"left":"Mínima","right":"2 tempos"},{"left":"Semínima","right":"1 tempo"},{"left":"Colcheia","right":"Meio tempo"}]}]}],"pratiqueSozinho":{"passos":["Leia o ritmo da sua voz numa partitura do repertório, falando as sílabas no tempo.","Exercício de ritmo com padrões pontuados."],"minutos":8,"frequencia":"3 vezes por semana"},"errosComuns":[{"erro":"Ignorar o ponto de aumento.","correcao":"O ponto acrescenta metade do valor da figura."},{"erro":"Pular pausas.","correcao":"Pausas também são contadas: o silêncio faz parte do ritmo."}],"seguranca":["A leitura cansa a vista e a mente: faça pausas curtas a cada 15 minutos."],"criterioAvanco":"Acertar pelo menos 70% nas avaliações de leitura rítmica."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
