insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:ritmo-pontuado-pratica')::uuid, 'ritmo-pontuado-pratica', (select id from public.lessons where slug = 'figuras-ritmicas-e-compassos'), 'Prática: ritmos pontuados', 'Ouça e reproduza.', 'rhythm_tap', '{"rounds":4,"patterns":["h. q","q. e q q","q q. e q","q. e h"],"bpm":72}'::jsonb, 'leitura-ritmica', 'pratica', 1, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:figuras-avaliacao')::uuid, 'figuras-avaliacao', (select id from public.lessons where slug = 'figuras-ritmicas-e-compassos'), 'Avaliação: figuras e compassos', 'Responda sobre figuras e compassos.', 'quiz', '{"questions":[{"q":"Em 4/4, quantos tempos vale a mínima?","options":["2","1","4","3"],"answer":0},{"q":"Quantas colcheias cabem em um tempo de semínima?","options":["2","1","4","8"],"answer":0},{"q":"Quanto vale uma mínima pontuada?","options":["3 tempos","2 tempos","2 tempos e meio","4 tempos"],"answer":0},{"q":"No compasso 3/4, cada compasso tem…","options":["Três semínimas","Três mínimas","Quatro semínimas","Três colcheias"],"answer":0},{"q":"Uma pausa de semínima vale…","options":["1 tempo de silêncio","Meio tempo","2 tempos","Nenhum tempo"],"answer":0}]}'::jsonb, 'leitura-ritmica', 'avaliacao', 1, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:claves')::uuid, (select id from public.learning_paths where slug = 'leitura-musical'), 'claves', 'Claves de Sol e de Fá', 'Leitura na clave de Fá e a clave de Sol do tenor.', 2, 2, 20, '{"objetivo":"Ler notas na clave de Fá (vozes graves) e entender a clave de Sol oitavada usada para o tenor.","gancho":"Tenores e baixos, esta aula é de vocês (e de quem quer entender a pauta de baixo do hinário). A clave de Fá tem dois pontinhos que entregam o segredo.","etapas":[{"titulo":"Duas claves, duas regiões","tipo":"descobrir","blocos":[{"type":"illustration","name":"claves","caption":"Clave de Sol para as vozes agudas; clave de Fá para as graves."},{"type":"p","text":"A clave diz qual nota mora em cada linha. A de Sol serve às vozes agudas. A de Fá serve aos baixos e, em muitos hinários, também aos tenores."},{"type":"check","question":"Por que os baixos leem na clave de Fá?","options":["Porque as notas graves ficam dentro da pauta, sem muitas linhas suplementares","Porque a clave de Fá é mais fácil","Porque baixos não usam notas"],"answer":0,"explain":"Na clave de Sol, as notas do baixo ficariam muito abaixo da pauta, cheias de linhas suplementares. A clave de Fá traz essa região para dentro das cinco linhas."}]},{"titulo":"Os dois pontinhos marcam o Fá","tipo":"descobrir","blocos":[{"type":"callout","icon":"olho","title":"Um sanduíche de pontos","text":"A clave de Fá começa na 4ª linha, e os dois pontos ficam um acima e outro abaixo dela. A linha “recheada” pelos pontos é o Fá3, sua âncora."},{"type":"staff","clef":"fa","notes":["F3"],"label":"Fá3 na 4ª linha"},{"type":"check","question":"Qual é esta nota?","staff":{"clef":"fa","notes":["F3"]},"options":["Fá","Lá","Ré","Sol"],"answer":0,"explain":"4ª linha, entre os dois pontos da clave: Fá3."}]},{"titulo":"Linhas e espaços da clave de Fá","tipo":"descobrir","blocos":[{"type":"staff","clef":"fa","notes":["G2","B2","D3","F3","A3"],"label":"Linhas: Sol, Si, Ré, Fá, Lá"},{"type":"staff","clef":"fa","notes":["A2","C3","E3","G3"],"label":"Espaços: Lá, Dó, Mi, Sol"},{"type":"callout","icon":"ideia","title":"Truque das duas notas","text":"Sabe ler na clave de Sol? Leia a posição como se fosse clave de Sol e suba duas notas no nome. 1ª linha: Mi vira Sol. 1º espaço: Fá vira Lá. 4ª linha: Ré vira Fá."}]},{"titulo":"Qual é esta nota? (clave de Fá)","tipo":"checar","blocos":[{"type":"check","question":"Qual é esta nota?","staff":{"clef":"fa","notes":["C3"]},"options":["Dó","Lá","Mi","Si"],"answer":0,"explain":"2º espaço: Lá, DÓ. Pelo truque: na clave de Sol seria Lá; duas notas acima, Dó."},{"type":"check","question":"Qual é esta nota?","staff":{"clef":"fa","notes":["A3"]},"options":["Lá","Fá","Sol","Dó"],"answer":0,"explain":"5ª linha, a de cima: Sol, Si, Ré, Fá, LÁ. Uma linha acima da âncora Fá."},{"type":"check","question":"Qual é esta nota?","staff":{"clef":"fa","notes":["D3"]},"options":["Ré","Si","Fá","Mi"],"answer":0,"explain":"3ª linha, a do meio: uma linha abaixo do Fá (pulando o Mi). É o Ré3."}]},{"titulo":"O Dó central une as pautas","tipo":"experimentar","blocos":[{"type":"illustration","name":"linhas-suplementares","caption":"O mesmo Dó4 aparece acima da pauta de Fá e abaixo da pauta de Sol."},{"type":"staff","clef":"fa","notes":["C3","D3","E3","F3","G3","A3","B3","C4"],"label":"Escala de Dó3 a Dó4 na clave de Fá"},{"type":"keyboard","from":"C3","to":"C5","highlight":["C3","F3","C4"],"label":"Dó3, a âncora Fá3 e o Dó central"},{"type":"timer","instruction":"Leia a escala em voz alta, nota por nota, e toque cada uma no teclado.","seconds":30}]},{"titulo":"O 8 do tenor","tipo":"ouvir","blocos":[{"type":"p","text":"Algumas partituras escrevem o tenor na clave de Sol com um 8 pequeno embaixo. O 8 avisa: cante uma oitava abaixo do que está escrito."},{"type":"compare","prompt":"A nota escrita é Sol4 na clave de Sol com 8. Ouça as duas e veja qual o tenor canta.","options":[{"label":"Sol4 (como está escrito)","notes":["G4"]},{"label":"Sol3 (uma oitava abaixo)","notes":["G3"]}],"explain":"O tenor canta Sol3, uma oitava abaixo. O desenho fica igual ao das vozes agudas, mas o som é o da voz masculina."},{"type":"check","question":"Num hinário SATB de duas pautas, quem lê na pauta de baixo (clave de Fá)?","options":["Tenor e baixo","Soprano e contralto","Só o baixo","Contralto e tenor"],"answer":0,"explain":"Soprano e contralto ficam na pauta de cima (clave de Sol); tenor e baixo, na de baixo (clave de Fá)."}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada pista ao que ela indica.","pairs":[{"left":"Caracol na 2ª linha","right":"Sol4 (clave de Sol)"},{"left":"Dois pontos na 4ª linha","right":"Fá3 (clave de Fá)"},{"left":"Linha suplementar acima da pauta de Fá","right":"Dó4 (dó central)"},{"left":"Clave de Sol com 8 embaixo","right":"Soa uma oitava abaixo"}]}]}],"pratiqueSozinho":{"passos":["5 minutos de leitura na clave de Fá.","Leia a linha do baixo de um hino conhecido."],"minutos":5,"frequencia":"Diariamente por duas semanas"},"errosComuns":[{"erro":"Ler a clave de Fá como se fosse a de Sol.","correcao":"Comece sempre pela âncora: a 4ª linha é Fá."}],"seguranca":["A leitura cansa a vista e a mente: faça pausas curtas a cada 15 minutos."],"criterioAvanco":"Acertar pelo menos 70% na avaliação da clave de Fá."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
