insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:clave-fa-pratica')::uuid, 'clave-fa-pratica', (select id from public.lessons where slug = 'claves'), 'Prática: clave de Fá', 'Qual é o nome da nota?', 'staff_read', '{"rounds":8,"clef":"fa","range":["C3","C4"]}'::jsonb, 'leitura-pauta', 'pratica', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:clave-fa-avaliacao')::uuid, 'clave-fa-avaliacao', (select id from public.lessons where slug = 'claves'), 'Avaliação: claves de Sol e de Fá', 'As notas aparecem nas duas claves.', 'staff_read', '{"rounds":10,"clef":"ambas"}'::jsonb, 'leitura-pauta', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:intervalos-na-pauta')::uuid, (select id from public.learning_paths where slug = 'leitura-musical'), 'intervalos-na-pauta', 'Intervalos na pauta', 'Ver e ouvir a distância entre as notas escritas.', 3, 2, 20, '{"objetivo":"Reconhecer intervalos na pauta pela posição das notas e relacioná-los ao som.","gancho":"Ler nota por nota é lento. Quem lê bem enxerga distâncias: “subiu uma terça”, “desceu uma quinta”. Vamos treinar o olho para ver saltos na pauta.","etapas":[{"titulo":"Conte nos dedos, incluindo a primeira","tipo":"descobrir","blocos":[{"type":"illustration","name":"intervalo-escada","caption":"Cada degrau da escada é uma nota."},{"type":"callout","icon":"maos","title":"Dedos na mão","text":"Para saber o intervalo, conte as notas incluindo a primeira e a última. Dó, Ré, Mi: três dedos, então é uma terça."},{"type":"check","question":"De Sol até Ré (subindo), qual é o intervalo?","options":["Quinta","Quarta","Terça","Sexta"],"answer":0,"explain":"Sol, Lá, Si, Dó, Ré: cinco notas contando as duas pontas. Quinta."}]},{"titulo":"O truque linha e espaço","tipo":"descobrir","blocos":[{"type":"callout","icon":"ideia","title":"Ímpar casa com igual","text":"Linha para linha (ou espaço para espaço): intervalo ímpar, como terça, quinta ou sétima. Linha para espaço: intervalo par, como segunda, quarta, sexta ou oitava."},{"type":"staff","clef":"sol","notes":["E4","G4"],"label":"Terça: linha → linha seguinte"},{"type":"staff","clef":"sol","notes":["A4","B4"],"label":"Segunda: notas “encostadas”"},{"type":"check","question":"Que intervalo é este?","staff":{"clef":"sol","notes":["G4","D5"]},"options":["Quinta","Terça","Quarta","Sexta"],"answer":0,"explain":"Linha para linha, pulando uma linha no meio: quinta. Conferindo: Sol, Lá, Si, Dó, Ré."}]},{"titulo":"Ouça o tamanho do salto","tipo":"ouvir","blocos":[{"type":"p","text":"Agora ligue o que você vê ao que você ouve. Toque cada intervalo a partir do Mi."},{"type":"intervals","root":"E4","semitones":[3,7,12]},{"type":"compare","prompt":"Qual destes saltos é a oitava (Dó4 → Dó5)?","options":[{"label":"Dó → Sol (quinta)","notes":["C4","G4"],"mode":"seq"},{"label":"Dó → Dó (oitava)","notes":["C4","C5"],"mode":"seq"},{"label":"Dó → Mi (terça)","notes":["C4","E4"],"mode":"seq"}],"answer":1,"explain":"Na oitava as duas notas têm o mesmo nome e soam quase como uma só, uma mais aguda que a outra."}]},{"titulo":"Cante a terça","tipo":"experimentar","blocos":[{"type":"staff","clef":"sol","notes":["C4","E4"],"label":"Dó4 → Mi4: linha suplementar para linha"},{"type":"audio","label":"Ouça Dó → Mi","notes":["C4","E4"],"mode":"seq","tempo":70},{"type":"singAlong","instruction":"Ouça o Mi, a terça acima do Dó, e cante-o em “lá”, sem esforço.","note":"E4","seconds":3},{"type":"callout","icon":"ouvido","title":"Por que a terça importa","text":"A terça é a distância entre as duas primeiras notas de um acorde maior ou menor. Vê-la na pauta já prepara o ouvido."}]},{"titulo":"Que intervalo é este?","tipo":"checar","blocos":[{"type":"check","question":"Que intervalo é este?","staff":{"clef":"sol","notes":["D4","G4"]},"audio":{"notes":["D4","G4"],"mode":"seq","tempo":70},"options":["Quarta","Terça","Quinta","Segunda"],"answer":0,"explain":"Espaço (abaixo da pauta) para linha: intervalo par. Ré, Mi, Fá, Sol: quarta."},{"type":"check","question":"Que intervalo é este (clave de Fá)?","staff":{"clef":"fa","notes":["C3","E3"]},"options":["Terça","Quinta","Segunda","Oitava"],"answer":0,"explain":"Espaço para o espaço seguinte: terça. Dó, Ré, Mi. O truque vale em qualquer clave."},{"type":"check","question":"Que intervalo é este?","staff":{"clef":"sol","notes":["C4","C5"]},"options":["Oitava","Sétima","Quinta","Sexta"],"answer":0,"explain":"Linha suplementar para o 3º espaço, com o mesmo nome: Dó4 → Dó5, oitava."}]},{"titulo":"Saltos no repertório","tipo":"aplicar","blocos":[{"type":"reveal","prompt":"Pegue a sua voz num hino do repertório. Antes de cantar, procure o maior salto da linha. Qual é?","answer":"Circule-o a lápis, conte as notas e cante só esse salto algumas vezes. Saltos marcados com antecedência deixam de ser surpresa no ensaio."},{"type":"harmonyLink","arrangement":"tercas-paralelas","label":"Ouça e cante terças em paralelo no treinador"}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue o que você vê na pauta ao intervalo.","pairs":[{"left":"Notas encostadas (linha → espaço vizinho)","right":"Segunda"},{"left":"Linha → linha seguinte","right":"Terça"},{"left":"Linha → linha, pulando uma","right":"Quinta"},{"left":"Mesmo nome, Dó4 → Dó5","right":"Oitava"}]}]}],"pratiqueSozinho":{"passos":["Na sua partitura, circule os saltos de terça, quinta e oitava da sua voz e cante-os separadamente."],"minutos":6,"frequencia":"2 vezes por semana"},"errosComuns":[{"erro":"Contar o intervalo sem incluir a primeira nota.","correcao":"Conte as duas notas: de Dó a Mi são três notas (Dó, Ré, Mi) — terça."}],"seguranca":["A leitura cansa a vista e a mente: faça pausas curtas a cada 15 minutos."],"criterioAvanco":"Acertar pelo menos 70% na avaliação."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'leitura-pauta' from public.lessons where slug = 'intervalos-na-pauta' on conflict do nothing;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'intervalos' from public.lessons where slug = 'intervalos-na-pauta' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:intervalos-pauta-avaliacao')::uuid, 'intervalos-pauta-avaliacao', (select id from public.lessons where slug = 'intervalos-na-pauta'), 'Avaliação: intervalos escritos', 'Observe as notas na pauta e ouça.', 'quiz', '{"questions":[{"q":"Que intervalo é este?","options":["Terça","Segunda","Quinta","Oitava"],"answer":0,"staff":{"clef":"sol","notes":["E4","G4"]},"audio":{"notes":["E4","G4"],"mode":"seq","tempo":70}},{"q":"Que intervalo é este?","options":["Quinta","Terça","Quarta","Sexta"],"answer":0,"staff":{"clef":"sol","notes":["G4","D5"]},"audio":{"notes":["G4","D5"],"mode":"seq","tempo":70}},{"q":"Que intervalo é este?","options":["Segunda","Terça","Uníssono","Quarta"],"answer":0,"staff":{"clef":"sol","notes":["A4","B4"]},"audio":{"notes":["A4","B4"],"mode":"seq","tempo":70}},{"q":"Que intervalo é este?","options":["Oitava","Sétima","Quinta","Sexta"],"answer":0,"staff":{"clef":"sol","notes":["C4","C5"]},"audio":{"notes":["C4","C5"],"mode":"seq","tempo":70}},{"q":"Que intervalo é este?","options":["Quarta","Terça","Quinta","Segunda"],"answer":0,"staff":{"clef":"sol","notes":["D4","G4"]},"audio":{"notes":["D4","G4"],"mode":"seq","tempo":70}},{"q":"Que intervalo é este (clave de Fá)?","options":["Terça","Quinta","Segunda","Oitava"],"answer":0,"staff":{"clef":"fa","notes":["C3","E3"]},"audio":{"notes":["C3","E3"],"mode":"seq","tempo":70}}]}'::jsonb, 'leitura-pauta', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:cifras')::uuid, (select id from public.learning_paths where slug = 'leitura-musical'), 'cifras', 'Cifras', 'Letras, acidentes e sufixos dos acordes.', 4, 2, 20, '{"objetivo":"Ler cifras (C, Am, G7, D/F♯…) e identificar as notas que formam cada acorde.","gancho":"Aquelas letras em cima da letra do hino (C, Am, G7, D/F♯) não são só para o violão. Quem canta e sabe ler cifra sabe onde a própria nota mora no acorde.","etapas":[{"titulo":"A, B, C… é Lá, Si, Dó","tipo":"descobrir","blocos":[{"type":"illustration","name":"cifra","caption":"Letra = nota fundamental; o resto diz o tipo do acorde."},{"type":"callout","icon":"ideia","title":"Comece no Lá","text":"A cifra usa letras. O alfabeto começa no Lá: A = Lá, B = Si, C = Dó, D = Ré, E = Mi, F = Fá, G = Sol. Fixe o par A = Lá e siga em frente na escala: as outras vêm em ordem."},{"type":"check","question":"A cifra E corresponde a qual nota?","options":["Mi","Ré","Fá","Lá"],"answer":0,"explain":"A, B, C, D, E: Lá, Si, Dó, Ré, MI."}]},{"titulo":"Sustenido sobe, bemol baixa","tipo":"descobrir","blocos":[{"type":"callout","icon":"olho","title":"♭ de “baixo”","text":"♯ (sustenido) sobe meio-tom; ♭ (bemol) desce meio-tom. Lembre: o bemol parece um “b” minúsculo, de “baixar”. F♯ = Fá sustenido; B♭ = Si bemol."},{"type":"keyboard","from":"C4","to":"C5","highlight":["F#4","Bb4"],"label":"F♯ (Fá sustenido) e B♭ (Si bemol)"},{"type":"check","question":"No teclado, onde fica o B♭?","options":["Na tecla preta logo abaixo do Si","Na tecla preta logo acima do Si","Na tecla branca do Lá","Na tecla branca do Dó"],"answer":0,"explain":"Bemol desce meio-tom: do Si, vá para a tecla vizinha à esquerda, a preta entre Lá e Si."}]},{"titulo":"O “m” muda tudo","tipo":"ouvir","blocos":[{"type":"p","text":"Letra sozinha é acorde maior: C = Dó, Mi, Sol. Com “m” minúsculo é menor: Cm = Dó, Mi♭, Sol. Só a nota do meio muda."},{"type":"chords","root":"C4","qualities":["maior","menor"]},{"type":"compare","prompt":"Desafio: qual destes é o Cm (Dó menor)?","options":[{"label":"C (maior)","notes":[["C4","E4","G4"]],"mode":"chord"},{"label":"Cm (menor)","notes":[["C4","Eb4","G4"]],"mode":"chord"}],"answer":1,"explain":"O menor soa mais escuro, mais “sério”. O maior soa mais aberto e luminoso."}]},{"titulo":"O 7, o 7M e a barra","tipo":"descobrir","blocos":[{"type":"list","items":["“7”: acrescenta a sétima menor. G7 = Sol, Si, Ré, Fá.","“7M” ou “maj7”: sétima maior. C7M = Dó, Mi, Sol, Si.","“°” ou “dim”: diminuto. “+” ou “aug”: aumentado.","Barra: a nota depois dela vai no baixo. D/F♯ = Ré maior com Fá♯ no baixo."]},{"type":"audio","label":"G7 (Sol–Si–Ré–Fá)","notes":[["G3","B3","D4","F4"]],"mode":"chord","tempo":30},{"type":"audio","label":"D/F♯ (Ré maior com Fá♯ no baixo)","notes":[["F#3","D4","F#4","A4"]],"mode":"chord","tempo":30},{"type":"check","question":"O que significa a cifra D/F♯?","options":["Ré maior com Fá♯ no baixo","Ré e Fá♯ alternados","Fá♯ maior","Ré menor"],"answer":0,"explain":"Antes da barra, o acorde (Ré maior); depois da barra, a nota mais grave (Fá♯)."}]},{"titulo":"Monte os acordes","tipo":"experimentar","blocos":[{"type":"callout","icon":"maos","title":"Pula uma, pega uma","text":"Para montar um acorde maior ou menor, parta da letra e pegue notas pulando uma: Dó (Ré) Mi (Fá) Sol. Depois confira se a nota do meio é maior ou menor."},{"type":"keyboard","from":"C4","to":"C5","highlight":["F4","A4","C5"],"label":"F = Fá, Lá, Dó"},{"type":"reveal","prompt":"Pense: quais são as notas de G e de Am?","answer":"G = Sol, Si, Ré. Am = Lá, Dó, Mi. Toque os dois no teclado para conferir."},{"type":"toolLink","tool":"teclado","label":"Monte C, F, G e Am no teclado"}]},{"titulo":"Onde está a sua nota?","tipo":"aplicar","blocos":[{"type":"illustration","name":"triade","caption":"Fundamental, terça e quinta."},{"type":"check","question":"A cifra é C e você, contralto, canta Mi. Em que posição do acorde você está?","options":["Na terça","Na fundamental","Na quinta","Fora do acorde"],"answer":0,"explain":"C = Dó (fundamental), Mi (terça), Sol (quinta). Saber isso ajuda a afinar: a terça define se o acorde é maior ou menor."},{"type":"trueFalse","items":[{"statement":"Bm é Si maior.","answer":false,"explain":"O “m” minúsculo indica menor: Si menor."},{"statement":"“7” e “7M” são a mesma coisa.","answer":false,"explain":"“7” é sétima menor (a mais comum); “7M” é sétima maior."},{"statement":"C7 tem quatro notas: Dó, Mi, Sol, Si♭.","answer":true,"explain":"A tríade de Dó maior mais a sétima menor (Si♭)."}]}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada cifra às notas do acorde.","pairs":[{"left":"C","right":"Dó, Mi, Sol"},{"left":"Am","right":"Lá, Dó, Mi"},{"left":"G7","right":"Sol, Si, Ré, Fá"},{"left":"C7M","right":"Dó, Mi, Sol, Si"},{"left":"D/F♯","right":"Ré maior, Fá♯ no baixo"}]}]}],"pratiqueSozinho":{"passos":["Pegue a cifra de um hino do repertório e escreva as notas de cada acorde.","Identifique em que nota do acorde a sua voz está em cada sílaba forte."],"minutos":10,"frequencia":"2 vezes por semana"},"errosComuns":[{"erro":"Confundir “7” com “7M”.","correcao":"“7” é sétima menor (a mais comum); “7M” é sétima maior."},{"erro":"Ler “Bm” como Si maior.","correcao":"O “m” minúsculo indica menor."}],"seguranca":["A leitura cansa a vista e a mente: faça pausas curtas a cada 15 minutos."],"criterioAvanco":"Acertar pelo menos 70% na avaliação de cifras."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'cifras' from public.lessons where slug = 'cifras' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:cifras-avaliacao')::uuid, 'cifras-avaliacao', (select id from public.lessons where slug = 'cifras'), 'Avaliação: lendo cifras', 'Responda sobre cifras.', 'quiz', '{"questions":[{"q":"Quais notas formam o acorde G?","options":["Sol, Si, Ré","Sol, Si♭, Ré","Sol, Dó, Mi","Lá, Dó, Mi"],"answer":0},{"q":"Quais notas formam o acorde Am?","options":["Lá, Dó, Mi","Lá, Dó♯, Mi","Lá, Ré, Fá","Mi, Sol, Si"],"answer":0},{"q":"O que significa a cifra D/F♯?","options":["Ré maior com Fá♯ no baixo","Ré e Fá♯ alternados","Ré menor","Fá♯ maior"],"answer":0},{"q":"A letra E corresponde a…","options":["Mi","Ré","Fá","Lá"],"answer":0},{"q":"Quantas notas tem o acorde C7?","options":["Quatro (Dó, Mi, Sol, Si♭)","Três","Sete","Duas"],"answer":0},{"q":"Ouça: este acorde é C ou Cm?","options":["Cm","C"],"answer":0,"audio":{"notes":[["C4","D#4","G4"]],"mode":"chord","tempo":30}}]}'::jsonb, 'cifras', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:leitura-de-partituras-vocais')::uuid, (select id from public.learning_paths where slug = 'leitura-musical'), 'leitura-de-partituras-vocais', 'Leitura aplicada a partituras vocais', 'Encontrar a sua voz, o texto, as respirações e as indicações.', 5, 2, 25, '{"objetivo":"Orientar-se numa partitura coral: sistemas, pautas, a própria voz, texto, repetições, dinâmicas e marcações de estudo.","gancho":"Abriu o hinário e viu quatro vozes, duas pautas, três estrofes e um monte de sinais? Calma: a partitura é um mapa, e você vai aprender a achar o seu caminho nele.","etapas":[{"titulo":"A partitura é um mapa","tipo":"descobrir","blocos":[{"type":"illustration","name":"partitura-vocal","caption":"Um sistema: as pautas lidas ao mesmo tempo."},{"type":"p","text":"O sistema é o conjunto de pautas lidas ao mesmo tempo. Num hinário SATB há duas: soprano e contralto em cima, tenor e baixo embaixo. O texto fica entre as pautas, com as estrofes numeradas."},{"type":"check","question":"Num hinário SATB, em que pauta está o tenor?","options":["Na de baixo, junto com o baixo","Na de cima, junto com o soprano","Numa pauta só dele","Na de cima, junto com o contralto"],"answer":0,"explain":"Pauta de cima: soprano e contralto. Pauta de baixo: tenor e baixo."}]},{"titulo":"Siga a sua haste","tipo":"descobrir","blocos":[{"type":"callout","icon":"olho","title":"Cima é cima, baixo é baixo","text":"Duas vozes dividem a mesma pauta. Haste para cima: a voz de cima (soprano ou tenor). Haste para baixo: a voz de baixo (contralto ou baixo)."},{"type":"trueFalse","items":[{"statement":"Na pauta de cima, as notas com haste para baixo são do contralto.","answer":true,"explain":"O contralto é a voz de baixo da pauta de cima."},{"statement":"Na pauta de baixo, a haste para cima é do baixo.","answer":false,"explain":"Haste para cima na pauta de baixo é do tenor; o baixo tem haste para baixo."}]}]},{"titulo":"Leia e ouça o primeiro compasso","tipo":"ouvir","blocos":[{"type":"staff","clef":"sol","notes":["E4","E4","F4","G4"],"label":"Soprano, primeiro compasso do Hino da Alegria"},{"type":"audio","label":"Ouça o soprano","notes":["E4","E4","F4","G4"],"mode":"seq","tempo":90},{"type":"staff","clef":"fa","notes":["C3","C3","F3","C3"],"label":"Baixo, primeiro compasso do Hino da Alegria"},{"type":"audio","label":"Ouça o baixo","notes":["C3","C3","F3","C3"],"mode":"seq","tempo":90},{"type":"check","question":"Qual é a primeira nota do baixo?","staff":{"clef":"fa","notes":["C3"]},"options":["Dó","Mi","Lá","Fá"],"answer":0,"explain":"2º espaço da clave de Fá: Lá, DÓ. É o Dó3."}]},{"titulo":"O caminho da leitura","tipo":"descobrir","blocos":[{"type":"list","items":["Sinal de repetição (:‖): volte e cante o trecho de novo.","Casas de 1ª e 2ª vez: na repetição, pule a 1ª e vá para a 2ª.","D.C. (da capo, “da cabeça”): volte ao início.","D.S. (dal segno): volte ao sinal 𝄋."]},{"type":"callout","icon":"ideia","title":"Capo é cabeça","text":"Lembre: D.C. = da Cabeça (início). D.S. = do Sinal. Antes de cantar, percorra o caminho com o dedo."},{"type":"check","question":"Você chegou ao D.C. no fim da página. Para onde vai?","options":["Para o início da música","Para o sinal 𝄋","Para a 2ª casa","Termina ali"],"answer":0,"explain":"D.C. vem do italiano da capo: “da cabeça”, ou seja, do começo."}]},{"titulo":"Volume, ar e fermata","tipo":"descobrir","blocos":[{"type":"illustration","name":"dinamica","caption":"p = piano (suave), mf = meio-forte, f = forte."},{"type":"p","text":"Dinâmicas (p, mf, f) e o crescendo dizem o volume. Vírgula ou “V” marcam respiração. A fermata (𝄐) pede para sustentar a nota além do valor, conforme o regente. Os números de compasso servem para combinar onde recomeçar no ensaio."},{"type":"check","question":"Sobre uma nota aparece a fermata (𝄐). O que fazer?","options":["Sustentar além do valor, olhando o regente","Cantar mais forte","Respirar ali","Repetir o trecho"],"answer":0,"explain":"A fermata alonga a nota. Quanto, quem decide é o regente: por isso olhe para ele(a)."}]},{"titulo":"Prepare a sua voz","tipo":"experimentar","blocos":[{"type":"order","prompt":"Coloque na ordem os passos para estudar uma partitura nova.","items":["Encontrar a sua pauta e a direção da sua haste","Percorrer o caminho com o dedo (repetições, D.C.)","Ler o ritmo falando o texto","Cantar com as notas","Marcar respirações e trechos difíceis a lápis"]},{"type":"checklist","title":"Marcações a lápis","items":["Minha voz destacada com marca-texto","Respirações marcadas com “V”","Trechos difíceis circulados","Repetições e D.C. conferidos","Marcações revisadas após o ensaio"]}]},{"titulo":"No treinador de harmonia","tipo":"aplicar","blocos":[{"type":"rhythm","pattern":"q. e h","bpm":80,"label":"O ritmo pontuado do fim da frase: “tá—a-ti tá-a”"},{"type":"reveal","prompt":"Abra o Hino da Alegria SATB e siga a sua voz. Em que ponto aparece esse ritmo pontuado?","answer":"No fim das frases (por exemplo, a primeira termina com Mi pontuado, Ré colcheia e Ré mínima). Fale o texto nesse ritmo antes de cantar e use “marcar trecho” onde travar."},{"type":"harmonyLink","arrangement":"hino-alegria-satb","label":"Siga a sua voz no Hino da Alegria SATB"}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada sinal ao que ele pede.","pairs":[{"left":"D.C.","right":"Voltar ao início"},{"left":"D.S.","right":"Voltar ao sinal"},{"left":"Fermata (𝄐)","right":"Sustentar além do valor"},{"left":"“V” ou vírgula","right":"Respirar"},{"left":"Número de compasso","right":"Combinar onde recomeçar"}]}]}],"pratiqueSozinho":{"passos":["Prepare a sua voz de uma música do repertório com marcações a lápis.","Leve dúvidas para o professor."],"minutos":15,"frequencia":"1 vez por semana"},"errosComuns":[{"erro":"Seguir a haste errada na pauta compartilhada.","correcao":"Confira a direção das hastes da sua voz."},{"erro":"Esquecer as repetições.","correcao":"Antes de cantar, percorra o “caminho” da partitura com o dedo."}],"seguranca":["A leitura cansa a vista e a mente: faça pausas curtas a cada 15 minutos."],"criterioAvanco":"Acertar pelo menos 70% da avaliação."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
