insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:partitura-avaliacao')::uuid, 'partitura-avaliacao', (select id from public.lessons where slug = 'leitura-de-partituras-vocais'), 'Avaliação: orientação na partitura', 'Responda sobre leitura de partituras vocais.', 'quiz', '{"questions":[{"q":"Na pauta de cima de um hinário SATB, as notas com haste para baixo são do…","options":["Contralto","Soprano","Tenor","Baixo"],"answer":0},{"q":"O sinal de fermata indica…","options":["Sustentar a nota além do valor, conforme o regente","Repetir o trecho","Cantar forte","Respirar"],"answer":0},{"q":"D.C. significa…","options":["Voltar ao início","Ir para o sinal","Diminuir o volume","Cantar mais devagar"],"answer":0},{"q":"Para que servem os números de compasso no ensaio?","options":["Combinar de onde recomeçar","Indicar a dinâmica","Contar os cantores","Indicar a tonalidade"],"answer":0}]}'::jsonb, 'leitura-pauta', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.learning_paths (id, slug, code, title, subtitle, description, icon, sort) values (md5('path:teoria-aplicada')::uuid, 'teoria-aplicada', 'F', 'Teoria aplicada', 'Escalas, acordes, campo harmônico e transposição', 'Teoria a serviço do ministério: entender por que as vozes se encaixam, como os acordes funcionam numa música e como escolher a tonalidade certa para o grupo.', 'library', 5) on conflict (slug) do update set code = excluded.code, title = excluded.title, subtitle = excluded.subtitle, description = excluded.description, icon = excluded.icon, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:escalas-tons-e-semitons')::uuid, (select id from public.learning_paths where slug = 'teoria-aplicada'), 'escalas-tons-e-semitons', 'Escalas, tons, semitons e armaduras', 'A fórmula da escala maior e menor e as armaduras de clave.', 0, 2, 25, '{"objetivo":"Construir escalas maiores e menores a partir de tons e semitons e reconhecer as armaduras de clave mais usadas.","gancho":"Por que o “Dó-Ré-Mi” soa tão familiar? Por trás dele existe uma receita simples de passos grandes e pequenos. Vamos descobri-la no teclado.","etapas":[{"titulo":"O menor passo da música","tipo":"descobrir","blocos":[{"type":"illustration","name":"tom-semitom","caption":"Semitom: tecla vizinha. Tom: dois semitons."},{"type":"p","text":"Semitom é a menor distância entre duas notas: a tecla vizinha, branca ou preta. Tom são dois semitons."},{"type":"keyboard","from":"C4","to":"C5","highlight":["E4","F4","B4","C5"],"label":"Semitons naturais: Mi–Fá e Si–Dó"},{"type":"check","question":"Quantos semitons há de Dó a Ré?","options":["2 (um tom)","1 (um semitom)","3"],"answer":0,"explain":"Entre Dó e Ré existe uma tecla preta (Dó♯). São dois passos de tecla vizinha: um tom."}]},{"titulo":"Ouça o passo grande e o pequeno","tipo":"ouvir","blocos":[{"type":"intervals","root":"C4","semitones":[1,2]},{"type":"compare","prompt":"Qual dos dois passos é um semitom?","options":[{"label":"Dó → Ré (tom)","notes":["C4","D4"],"tempo":70},{"label":"Mi → Fá (semitom)","notes":["E4","F4"],"tempo":70}],"answer":1,"explain":"Entre Mi e Fá não há tecla preta: o passo é de um só semitom. Entre Dó e Ré há um tom inteiro."},{"type":"tip","text":"Os únicos semitons entre notas naturais são Mi–Fá e Si–Dó. Olhe o teclado: não há tecla preta entre eles."}]},{"titulo":"A receita da escala maior","tipo":"descobrir","blocos":[{"type":"p","text":"A escala maior segue sempre a mesma fórmula: T T S T T T S. Em Dó maior: Dó Ré Mi Fá Sol Lá Si Dó."},{"type":"scales","tonic":"C4","kinds":["maior"]},{"type":"check","question":"Na escala maior, onde ficam os dois semitons?","options":["Entre os graus 3–4 e 7–8","Entre os graus 1–2 e 5–6","Entre os graus 2–3 e 6–7"],"answer":0,"explain":"T T S T T T S: o primeiro S (3º passo) cai entre Mi e Fá, graus 3–4; o último, entre Si e Dó, graus 7–8."}]},{"titulo":"Sua vez: Sol maior e Fá maior","tipo":"experimentar","blocos":[{"type":"p","text":"Toque a escala de Sol maior seguindo T T S T T T S. Depois, toque Fá maior com a mesma receita."},{"type":"keyboard","from":"F4","to":"G5","highlight":["G4","A4","B4","C5","D5","E5","F#5","G5"],"label":"Sol maior"},{"type":"reveal","prompt":"Que nota “diferente” Sol maior precisa? E Fá maior?","answer":"Sol maior precisa de Fá♯: do 6º grau (Mi) ao 7º deve haver um tom, e do 7º ao Sol, um semitom. Fá maior precisa de Si♭: do 3º grau (Lá) ao 4º deve haver só um semitom."}]},{"titulo":"Maior e menor: luz e sombra","tipo":"ouvir","blocos":[{"type":"list","items":["Menor natural: T S T T S T T (Lá menor: Lá Si Dó Ré Mi Fá Sol Lá).","Menor harmônica: a natural com o 7º grau elevado. Ele vira sensível e conduz à tônica."]},{"type":"scales","tonic":"C4","kinds":["maior","menor_natural","menor_harmonica"]},{"type":"compare","prompt":"Qual das duas é a escala menor?","options":[{"label":"Dó maior","notes":["C4","D4","E4","F4","G4","A4","B4","C5"],"tempo":110},{"label":"Dó menor natural","notes":["C4","D4","Eb4","F4","G4","Ab4","Bb4","C5"],"tempo":110}],"answer":1,"explain":"A menor tem o 3º grau meio-tom mais baixo (Mi♭ em vez de Mi), além do 6º e do 7º. É isso que dá a cor mais sombria."}]},{"titulo":"Armadura: o tom em resumo","tipo":"descobrir","blocos":[{"type":"p","text":"Logo após a clave, a armadura mostra os sustenidos ou bemóis da tonalidade. Assim ninguém precisa escrevê-los em cada nota."},{"type":"list","items":["Ordem dos sustenidos: Fá, Dó, Sol, Ré, Lá, Mi, Si.","Ordem dos bemóis: Si, Mi, Lá, Ré, Sol, Dó, Fá.","Sol maior = 1♯; Ré maior = 2♯; Fá maior = 1♭; Si♭ maior = 2♭."]},{"type":"callout","icon":"ideia","title":"Truque","text":"Com sustenidos, a tônica maior fica meio-tom acima do último sustenido. Com bemóis, é o penúltimo bemol (exceto Fá maior, que tem um só)."},{"type":"check","question":"A armadura tem Fá♯ e Dó♯. Qual é a tonalidade maior?","options":["Ré maior","Dó♯ maior","Sol maior","Lá maior"],"answer":0,"explain":"O último sustenido é Dó♯; meio-tom acima dele está Ré. Ré maior tem dois sustenidos."}]},{"titulo":"Abra o hinário","tipo":"aplicar","blocos":[{"type":"p","text":"Toda tonalidade maior tem uma relativa menor com a mesma armadura: Dó maior e Lá menor. Por isso, olhe também a última nota do baixo."},{"type":"check","question":"Um hino tem um bemol (Si♭) na armadura e termina num acorde de Fá. Qual é a tonalidade?","options":["Fá maior","Ré menor","Si♭ maior","Sol menor"],"answer":0,"explain":"Um bemol serve para Fá maior e para sua relativa, Ré menor. Como o hino repousa em Fá, a tonalidade é Fá maior."},{"type":"toolLink","tool":"teclado","label":"Toque no teclado a escala de um hino que você canta"}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada termo ao seu significado.","pairs":[{"left":"Semitom","right":"Tecla vizinha"},{"left":"Tom","right":"Dois semitons"},{"left":"T T S T T T S","right":"Escala maior"},{"left":"T S T T S T T","right":"Escala menor natural"},{"left":"7º grau elevado","right":"Menor harmônica"}]}]}],"pratiqueSozinho":{"passos":["Laboratório: escalas maior e menor.","Descubra a armadura de duas músicas do repertório."],"minutos":10,"frequencia":"2 vezes por semana"},"errosComuns":[{"erro":"Esquecer os semitons naturais Mi–Fá e Si–Dó.","correcao":"Olhe o teclado: não há tecla preta entre eles."}],"seguranca":["Alterne teoria e prática: depois de cada conceito, toque e cante o exemplo."],"criterioAvanco":"Acertar pelo menos 70% nas avaliações."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'teoria-escalas' from public.lessons where slug = 'escalas-tons-e-semitons' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:escalas-escuta-avaliacao')::uuid, 'escalas-escuta-avaliacao', (select id from public.lessons where slug = 'escalas-tons-e-semitons'), 'Avaliação: maior ou menor?', 'Ouça a escala.', 'scale_id', '{"rounds":6,"scales":["maior","menor_natural"]}'::jsonb, 'teoria-escalas', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:escalas-teoria-avaliacao')::uuid, 'escalas-teoria-avaliacao', (select id from public.lessons where slug = 'escalas-tons-e-semitons'), 'Avaliação: escalas e armaduras', 'Responda sobre escalas e armaduras.', 'quiz', '{"questions":[{"q":"Qual é a fórmula da escala maior?","options":["T T S T T T S","T S T T S T T","S T T S T T T","T T T S T T S"],"answer":0},{"q":"Quantos semitons há em um tom?","options":["2","1","3","12"],"answer":0},{"q":"Qual é a armadura de Sol maior?","options":["1 sustenido (Fá♯)","1 bemol (Si♭)","2 sustenidos","Nenhum acidente"],"answer":0},{"q":"Qual é a relativa menor de Dó maior?","options":["Lá menor","Dó menor","Mi menor","Ré menor"],"answer":0},{"q":"Entre quais notas naturais há apenas um semitom?","options":["Mi–Fá e Si–Dó","Dó–Ré e Fá–Sol","Lá–Si e Ré–Mi","Sol–Lá e Dó–Ré"],"answer":0},{"q":"Uma armadura com 2 bemóis (Si♭ e Mi♭) indica, no modo maior…","options":["Si♭ maior","Mi♭ maior","Fá maior","Ré maior"],"answer":0}]}'::jsonb, 'teoria-escalas', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:triades-e-inversoes')::uuid, (select id from public.learning_paths where slug = 'teoria-aplicada'), 'triades-e-inversoes', 'Tríades e inversões', 'Acordes maiores, menores, diminutos e aumentados; estado fundamental e inversões.', 1, 2, 25, '{"objetivo":"Formar tríades maiores, menores, diminutas e aumentadas e reconhecer o estado fundamental e as inversões.","gancho":"Quando o quarteto canta um acorde, cada um segura uma peça do mesmo quebra-cabeça. Descubra quais peças existem e por que às vezes a sua nota fica embaixo, às vezes em cima.","etapas":[{"titulo":"Três notas, um acorde","tipo":"descobrir","blocos":[{"type":"illustration","name":"triade","caption":"Fundamental, terça e quinta, empilhadas em terças."},{"type":"p","text":"Tríade é um acorde de três notas empilhadas em terças: a fundamental (que dá o nome), a terça e a quinta."},{"type":"keyboard","from":"C4","to":"C5","highlight":["C4","E4","G4"],"label":"Dó maior: Dó–Mi–Sol"},{"type":"check","question":"No acorde Dó–Mi–Sol, qual nota é a terça?","options":["Mi","Dó","Sol"],"answer":0,"explain":"Dó é a fundamental, Mi fica uma terça acima dela e Sol, uma quinta acima."}]},{"titulo":"Quatro cores de acorde","tipo":"ouvir","blocos":[{"type":"list","items":["Maior: terça maior + terça menor (Dó–Mi–Sol).","Menor: terça menor + terça maior (Dó–Mi♭–Sol).","Diminuta: terça menor + terça menor (Si–Ré–Fá).","Aumentada: terça maior + terça maior (Dó–Mi–Sol♯)."]},{"type":"chords","root":"C4","qualities":["maior","menor","diminuto","aumentado"]},{"type":"tip","text":"Terça maior = 4 semitons. Terça menor = 3 semitons. Conte no teclado."}]},{"titulo":"Desafio: qual é o menor?","tipo":"checar","blocos":[{"type":"compare","prompt":"Ouça os dois acordes. Qual deles é menor?","options":[{"label":"Dó maior","notes":["C4","E4","G4",["C4","E4","G4"]],"tempo":90},{"label":"Dó menor","notes":["C4","Eb4","G4",["C4","Eb4","G4"]],"tempo":90}],"answer":1,"explain":"Só a terça mudou: Mi virou Mi♭, meio-tom abaixo. Uma única nota troca a cor do acorde inteiro."},{"type":"check","question":"Ré–Fá♯–Lá é uma tríade…","options":["Maior","Menor","Diminuta","Aumentada"],"answer":0,"explain":"Ré–Fá♯ tem 4 semitons (terça maior) e Fá♯–Lá tem 3 (terça menor): é Ré maior."}]},{"titulo":"Sua vez: quatro acordes sobre Ré","tipo":"experimentar","blocos":[{"type":"p","text":"Toque Ré–Fá♯–Lá (maior). Abaixe o Fá♯ para Fá: menor. Abaixe também o Lá para Lá♭: diminuta. Volte ao maior e suba o Lá para Lá♯: aumentada."},{"type":"keyboard","from":"C4","to":"C5","highlight":["D4","F#4","A4"],"label":"Comece por Ré maior"},{"type":"reveal","prompt":"Quais são as notas de Ré diminuto?","answer":"Ré–Fá–Lá♭: duas terças menores (3 + 3 semitons)."}]},{"titulo":"Mesmo acorde, outro baixo","tipo":"descobrir","blocos":[{"type":"illustration","name":"inversoes"},{"type":"list","items":["Estado fundamental: a fundamental no baixo (Dó–Mi–Sol). Cifra: C.","1ª inversão: a terça no baixo (Mi–Sol–Dó). Cifra: C/E.","2ª inversão: a quinta no baixo (Sol–Dó–Mi). Cifra: C/G."]},{"type":"audio","label":"Dó maior: estado fundamental, 1ª e 2ª inversão","notes":[["C4","E4","G4"],["E4","G4","C5"],["G4","C5","E5"]],"tempo":50},{"type":"trueFalse","items":[{"statement":"C/E continua sendo um acorde de Dó maior.","answer":true,"explain":"As notas são as mesmas (Dó, Mi, Sol). Muda só a nota do baixo."},{"statement":"Inverter um acorde maior o transforma em menor.","answer":false,"explain":"A inversão não muda o tipo do acorde, só a ordem das notas."},{"statement":"Lá–Dó–Fá é Fá maior em 1ª inversão (F/A).","answer":true,"explain":"Fá maior é Fá–Lá–Dó. Com o Lá, a terça, no baixo, é a 1ª inversão."}]}]},{"titulo":"Por que os arranjos invertem","tipo":"ouvir","blocos":[{"type":"p","text":"Inversões deixam as vozes se moverem pouco entre os acordes. Compare o baixo nas duas versões de C – G – C."},{"type":"compare","prompt":"Ouça e repare na voz mais grave.","options":[{"label":"G em estado fundamental: o baixo salta Dó–Sol–Dó","notes":[["C3","G3","E4","C5"],["G2","G3","D4","B4"],["C3","G3","E4","C5"]],"tempo":50},{"label":"G/B (1ª inversão): o baixo anda Dó–Si–Dó","notes":[["C3","G3","E4","C5"],["B2","G3","D4","D5"],["C3","G3","E4","C5"]],"tempo":50}],"explain":"Com G/B, o baixo anda só um semitom. Fica mais fácil de afinar e a linha soa mais ligada. É por isso que a sua nota às vezes não é a fundamental."}]},{"titulo":"Encontre no repertório","tipo":"aplicar","blocos":[{"type":"p","text":"No arranjo abaixo, a voz grave fica quase toda no Dó. Por isso vi e IV aparecem invertidos (Am/C e F/C) e o V vem como G/B."},{"type":"harmonyLink","arrangement":"triades-tres-vozes","label":"Treinador: tríades a três vozes (I – vi – IV – V – I)"},{"type":"check","question":"Na cifra de um louvor aparece D/F♯. O que o baixo canta ou toca?","options":["Fá♯, a terça de Ré maior","Ré, a fundamental","Um acorde de Fá♯ maior"],"answer":0,"explain":"A nota depois da barra é o baixo. D/F♯ é Ré maior em 1ª inversão."}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada cifra às suas notas.","pairs":[{"left":"C","right":"Dó–Mi–Sol"},{"left":"Cm","right":"Dó–Mi♭–Sol"},{"left":"C°","right":"Dó–Mi♭–Sol♭"},{"left":"C+","right":"Dó–Mi–Sol♯"},{"left":"C/E","right":"Mi–Sol–Dó"}]}]}],"pratiqueSozinho":{"passos":["Laboratório de acordes (níveis 3 a 5).","Identifique uma inversão numa música do repertório (cifra com barra)."],"minutos":10,"frequencia":"2 vezes por semana"},"errosComuns":[{"erro":"Achar que a inversão muda o tipo do acorde.","correcao":"C/E continua sendo Dó maior; muda só a nota do baixo."}],"seguranca":["Alterne teoria e prática: depois de cada conceito, toque e cante o exemplo."],"criterioAvanco":"Acertar pelo menos 70% nas avaliações."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
