insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:triades-escuta-avaliacao')::uuid, 'triades-escuta-avaliacao', (select id from public.lessons where slug = 'triades-e-inversoes'), 'Avaliação: quatro tipos de tríade', 'Identifique o tipo de acorde.', 'chord_quality', '{"rounds":8,"qualities":["maior","menor","diminuto","aumentado"],"play":"ambos"}'::jsonb, 'acordes', 'avaliacao', 2, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:triades-teoria-avaliacao')::uuid, 'triades-teoria-avaliacao', (select id from public.lessons where slug = 'triades-e-inversoes'), 'Avaliação: formação e inversões', 'Responda sobre tríades e inversões.', 'quiz', '{"questions":[{"q":"Quais notas formam Ré menor?","options":["Ré, Fá, Lá","Ré, Fá♯, Lá","Ré, Fá, Lá♭","Ré, Sol, Si"],"answer":0},{"q":"Si–Ré–Fá é uma tríade…","options":["Diminuta","Menor","Maior","Aumentada"],"answer":0},{"q":"Mi–Sol–Dó é Dó maior em…","options":["1ª inversão","Estado fundamental","2ª inversão","Não é Dó maior"],"answer":0},{"q":"A cifra C/G indica…","options":["Dó maior com Sol no baixo (2ª inversão)","Dó e Sol tocados juntos apenas","Sol maior","Dó com sétima"],"answer":0},{"q":"Por que os arranjos vocais usam inversões?","options":["Para as vozes se moverem pouco entre os acordes","Para mudar o tipo do acorde","Para evitar o baixo","Porque soam mais forte"],"answer":0}]}'::jsonb, 'teoria-harmonia', 'avaliacao', 2, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:campo-harmonico-e-funcoes')::uuid, (select id from public.learning_paths where slug = 'teoria-aplicada'), 'campo-harmonico-e-funcoes', 'Campo harmônico e funções', 'Os sete acordes da tonalidade e o papel de cada um.', 2, 3, 25, '{"objetivo":"Montar o campo harmônico maior e entender as funções de tônica, subdominante e dominante.","gancho":"Quase todo louvor gira em torno de uma “família” de sete acordes. Conheça essa família e você vai prever para onde a música quer ir.","etapas":[{"titulo":"Uma família de sete acordes","tipo":"descobrir","blocos":[{"type":"illustration","name":"campo-harmonico","caption":"Um acorde sobre cada nota da escala."},{"type":"p","text":"Campo harmônico é o conjunto de tríades formadas sobre cada nota da escala, usando só notas da tonalidade. Em Dó maior: C, Dm, Em, F, G, Am, B°."},{"type":"audio","label":"Campo harmônico de Dó maior","notes":[["C4","E4","G4"],["D4","F4","A4"],["E4","G4","B4"],["F4","A4","C5"],["G4","B4","D5"],["A4","C5","E5"],["B4","D5","F5"]],"tempo":70},{"type":"check","question":"Por que o acorde do 2º grau de Dó maior é Dm, e não D?","options":["Porque Fá♯ não pertence a Dó maior: usa-se Fá natural","Porque o 2º grau é sempre diminuto","Porque D só existe em tons menores"],"answer":0,"explain":"Ré maior precisaria de Fá♯. Usando só notas de Dó maior, sobre Ré forma-se Ré–Fá–Lá: Ré menor."}]},{"titulo":"O padrão que nunca muda","tipo":"descobrir","blocos":[{"type":"p","text":"Em qualquer tonalidade maior, a sequência de tipos é a mesma: maior, menor, menor, maior, maior, menor, diminuto."},{"type":"callout","icon":"olho","title":"Graus em algarismos romanos","text":"I, IV, V em maiúsculas são maiores; ii, iii, vi em minúsculas são menores; vii° é diminuto. Assim falamos da harmonia em qualquer tom."},{"type":"reveal","prompt":"Monte o campo harmônico de Sol maior (lembre-se do Fá♯).","answer":"G, Am, Bm, C, D, Em, F♯°."}]},{"titulo":"Casa, saída e tensão","tipo":"ouvir","blocos":[{"type":"list","items":["Tônica (I, e também iii e vi): repouso, a “casa”.","Subdominante (IV, e também ii): afastamento, preparação.","Dominante (V e vii°): tensão que pede a volta à tônica."]},{"type":"audio","label":"I – IV – V – I em Dó (repouso, afastamento, tensão, repouso)","notes":[["C3","G3","C4","E4"],["F2","A3","C4","F4"],["G2","G3","B3","D4"],["C3","G3","C4","E4"]],"tempo":60},{"type":"callout","icon":"coracao","title":"Como uma visita","text":"Você sai de casa (IV), chega ao ponto mais distante (V) e sente vontade de voltar (I)."}]},{"titulo":"Desafio: onde está a casa?","tipo":"checar","blocos":[{"type":"compare","prompt":"Qual das duas progressões termina em repouso?","options":[{"label":"I – IV – V – I","notes":[["C3","G3","C4","E4"],["F2","A3","C4","F4"],["G2","G3","B3","D4"],["C3","G3","C4","E4"]],"tempo":60},{"label":"I – IV – I – V","notes":[["C3","G3","C4","E4"],["F2","A3","C4","F4"],["C3","G3","C4","E4"],["G2","G3","B3","D4"]],"tempo":60}],"answer":0,"explain":"Terminar no I soa como chegar em casa. Terminar no V deixa a frase suspensa, pedindo continuação."},{"type":"check","question":"Am aparece numa música em Dó maior. Ele está “fora do tom”?","options":["Não: é o vi grau, com função de tônica","Sim: acordes menores não pertencem a tons maiores","Sim: é um acorde de dominante emprestado"],"answer":0,"explain":"Am (Lá–Dó–Mi) usa só notas de Dó maior e divide Dó e Mi com o I. Por isso pode substituir a tônica."}]},{"titulo":"Sua vez: I – IV – V – I em Sol","tipo":"experimentar","blocos":[{"type":"p","text":"Toque com a mão direita: Sol–Si–Ré (G), Sol–Dó–Mi (C), Fá♯–Lá–Ré (D), Sol–Si–Ré (G). Repare que as notas mudam pouco de um acorde para o outro."},{"type":"keyboard","from":"F4","to":"E5","highlight":["G4","B4","D5"],"label":"Comece em G (I de Sol maior)"},{"type":"audio","label":"I – IV – V – I em Sol maior","notes":[["G3","G4","B4","D5"],["C3","G4","C5","E5"],["D3","F#4","A4","D5"],["G3","G4","B4","D5"]],"tempo":60}]},{"titulo":"Graus na cifra do louvor","tipo":"aplicar","blocos":[{"type":"illustration","name":"cifra"},{"type":"p","text":"Pegue a cifra de uma música do repertório e escreva o grau sobre cada acorde. Você logo percebe o caminho da harmonia."},{"type":"check","question":"Um louvor está em Ré maior e aparece o acorde G. Qual é o grau?","options":["IV","V","iii","ii"],"answer":0,"explain":"Ré maior: Ré (I), Mi (ii), Fá♯ (iii), Sol (IV). G é o IV: subdominante."},{"type":"harmonyLink","arrangement":"triades-tres-vozes","label":"Cante I – vi – IV – V – I a três vozes"}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Em Dó maior, ligue cada grau ao seu acorde.","pairs":[{"left":"ii","right":"Dm"},{"left":"IV","right":"F"},{"left":"V","right":"G"},{"left":"vi","right":"Am"},{"left":"vii°","right":"B°"}]},{"type":"trueFalse","items":[{"statement":"O V grau tem função de dominante: tensão que pede resolução.","answer":true,"explain":"V e vii° são os acordes de dominante."},{"statement":"O ii grau tem função de tônica.","answer":false,"explain":"O ii acompanha o IV na função de subdominante, de preparação."}]}]}],"pratiqueSozinho":{"passos":["Laboratório de progressões.","Na cifra de uma música do repertório, escreva o grau de cada acorde."],"minutos":10,"frequencia":"2 vezes por semana"},"errosComuns":[{"erro":"Confundir o vi com um acorde “fora do tom”.","correcao":"Am faz parte de Dó maior: é o 6º grau, com função de tônica."}],"seguranca":["Alterne teoria e prática: depois de cada conceito, toque e cante o exemplo."],"criterioAvanco":"Acertar pelo menos 70% nas avaliações."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
