insert into public.lesson_skills (lesson_id, skill_slug) select id, 'progressoes' from public.lessons where slug = 'campo-harmonico-e-funcoes' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:progressoes-avaliacao')::uuid, 'progressoes-avaliacao', (select id from public.lessons where slug = 'campo-harmonico-e-funcoes'), 'Avaliação: progressões comuns', 'Qual progressão você ouviu?', 'progression_id', '{"rounds":6,"progressions":["I-IV-V-I","I-V-vi-IV","I-vi-IV-V"]}'::jsonb, 'progressoes', 'avaliacao', 3, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:campo-harmonico-avaliacao')::uuid, 'campo-harmonico-avaliacao', (select id from public.lessons where slug = 'campo-harmonico-e-funcoes'), 'Avaliação: campo harmônico', 'Responda sobre campo harmônico e funções.', 'quiz', '{"questions":[{"q":"Qual é o acorde do 5º grau em Dó maior?","options":["G","F","Am","Em"],"answer":0},{"q":"Qual função o acorde V exerce?","options":["Dominante","Tônica","Subdominante","Nenhuma"],"answer":0},{"q":"Em qualquer tom maior, o 6º grau é um acorde…","options":["Menor","Maior","Diminuto","Aumentado"],"answer":0},{"q":"Qual é o IV grau de Sol maior?","options":["C","D","Am","F"],"answer":0},{"q":"Qual acorde costuma soar como “casa”, repouso?","options":["I","V","vii°","ii"],"answer":0}]}'::jsonb, 'teoria-harmonia', 'avaliacao', 3, 1) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:cadencias')::uuid, (select id from public.learning_paths where slug = 'teoria-aplicada'), 'cadencias', 'Cadências', 'Como as frases terminam: perfeita, plagal, à dominante e de engano.', 3, 3, 20, '{"objetivo":"Reconhecer as cadências mais comuns e usar essa percepção para cantar com segurança os finais de frase.","gancho":"Por que o “A-mém” no fim do hino soa tão sereno? E por que algumas frases parecem uma pergunta? A resposta está nas cadências.","etapas":[{"titulo":"A pontuação da música","tipo":"descobrir","blocos":[{"type":"illustration","name":"cadencia","caption":"Cadência: o jeito como a frase termina."},{"type":"callout","icon":"ideia","title":"Como num texto","text":"Uma frase pode terminar em ponto final, em vírgula ou com uma surpresa. Na música, quem faz essa pontuação são os acordes do fim da frase."},{"type":"list","items":["Perfeita (V → I): conclusão firme, o ponto final.","Plagal (IV → I): o tradicional “A-mém”.","Semicadência (… → V): frase em aberto, como uma vírgula.","De engano (V → vi): a tensão resolve num acorde inesperado."]}]},{"titulo":"O ponto final: V → I","tipo":"ouvir","blocos":[{"type":"audio","label":"Cadência perfeita em Dó (G → C)","notes":[["G2","D3","B3","G4"],["C3","E3","C4","G4"]],"tempo":50},{"type":"p","text":"Ouça de novo, prestando atenção em duas vozes: a sensível (Si, 7º grau) sobe meio-tom para a tônica (Dó), e o baixo salta de Sol para Dó."},{"type":"singAlong","instruction":"Depois da cadência, cante a tônica (Dó) e sustente: é a nota de chegada.","note":"C4","seconds":3}]},{"titulo":"O “A-mém”: IV → I","tipo":"ouvir","blocos":[{"type":"audio","label":"Cadência plagal (F → C): “A-mém”","notes":[["F2","A3","C4","F4"],["C3","G3","C4","E4"]],"tempo":50},{"type":"p","text":"Aqui a voz mais aguda desce de Fá para Mi, enquanto o Dó fica parado nas duas sílabas. Uma resolução suave, sem a tensão da sensível."},{"type":"singAlong","instruction":"Cante o “mém”: a nota Mi, leve e sustentada.","note":"E4","seconds":3}]},{"titulo":"Vírgula e surpresa","tipo":"ouvir","blocos":[{"type":"check","question":"Ouça o fim desta frase. Como ela termina?","options":["Em aberto, pedindo continuação","Com conclusão firme","Com o “A-mém”"],"answer":0,"explain":"Terminou no V: é uma semicadência. A frase fica suspensa, esperando a próxima.","audio":{"notes":[["C3","G3","C4","E4"],["F2","A3","C4","F4"],["G2","G3","B3","D4"]],"tempo":50}},{"type":"compare","prompt":"As duas começam no mesmo V. Qual delas engana o ouvido?","options":[{"label":"Perfeita (V → I)","notes":[["G2","D4","G4","B4"],["C3","C4","E4","C5"]],"tempo":50},{"label":"De engano (V → vi)","notes":[["G2","D4","G4","B4"],["A2","C4","E4","C5"]],"tempo":50}],"answer":1,"explain":"As vozes de cima chegam às mesmas notas. Só o baixo muda: em vez de Dó, vai para Lá, e o acorde final vira Am (vi)."}]},{"titulo":"No Hino da Alegria","tipo":"aplicar","blocos":[{"type":"p","text":"A primeira frase termina em Ré, sobre o acorde de G (V): semicadência. A segunda termina em Dó, sobre C (I): cadência perfeita."},{"type":"audio","label":"Hino da Alegria, 1ª frase (termina no V)","notes":["E4","E4","F4","G4","G4","F4","E4","D4","C4","C4","D4","E4","E4","D4","D4"],"tempo":110},{"type":"audio","label":"2ª frase (termina no I)","notes":["E4","E4","F4","G4","G4","F4","E4","D4","C4","C4","D4","E4","D4","C4","C4"],"tempo":110},{"type":"tip","text":"Ao chegar no acorde final de uma cadência, pense na sua nota de destino antes de cantá-la. Isso ajuda a afinar o fim da frase."}]},{"titulo":"Cante uma cadência a quatro vozes","tipo":"aplicar","blocos":[{"type":"p","text":"No treinador, o V7 resolve no I: cadência perfeita. Escute o seu naipe chegar ao acorde final."},{"type":"harmonyLink","arrangement":"acordes-sustentados-satb","label":"Treinador: I – IV – V7 – I em SATB"},{"type":"check","question":"No V7 desse arranjo, o soprano canta Fá, a sétima do acorde. Para onde ele vai no acorde final?","options":["Desce para Mi","Sobe para Sol","Fica parado em Fá"],"answer":0,"explain":"A sétima do V7 tende a descer por grau. Fá desce para Mi, a terça de Dó maior, e o acorde repousa."}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"match","prompt":"Ligue cada cadência à sua sensação.","pairs":[{"left":"V → I (perfeita)","right":"Ponto final"},{"left":"IV → I (plagal)","right":"“A-mém”"},{"left":"… → V (semicadência)","right":"Vírgula, em aberto"},{"left":"V → vi (de engano)","right":"Surpresa"}]},{"type":"trueFalse","items":[{"statement":"Uma semicadência pode encerrar a música definitivamente.","answer":false,"explain":"Ela soa em aberto. O fim definitivo vem com a tônica."},{"statement":"Na cadência perfeita, a sensível costuma subir para a tônica.","answer":true,"explain":"Em Dó maior, Si sobe para Dó."}]}]}],"pratiqueSozinho":{"passos":["Laboratório de progressões com cadências.","Encontre uma cadência plagal num hino do repertório."],"minutos":8,"frequencia":"2 vezes por semana"},"errosComuns":[{"erro":"Confundir semicadência com fim da música.","correcao":"Na semicadência, a frase soa “em aberto”; o fim definitivo vem com a tônica."}],"seguranca":["Alterne teoria e prática: depois de cada conceito, toque e cante o exemplo."],"criterioAvanco":"Acertar pelo menos 70% na avaliação."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
