insert into public.lesson_skills (lesson_id, skill_slug) select id, 'teoria-harmonia' from public.lessons where slug = 'cadencias' on conflict do nothing;
insert into public.exercises (id, slug, lesson_id, title, instructions, type, config, skill_slug, purpose, difficulty, sort) values (md5('exercise:cadencias-avaliacao')::uuid, 'cadencias-avaliacao', (select id from public.lessons where slug = 'cadencias'), 'Avaliação: qual cadência?', 'Identifique a cadência.', 'progression_id', '{"rounds":6,"progressions":["IV-V-I","I-IV-I","I-V","V-vi"]}'::jsonb, 'progressoes', 'avaliacao', 3, 0) on conflict (slug) do update set lesson_id = excluded.lesson_id, title = excluded.title, instructions = excluded.instructions, type = excluded.type, config = excluded.config, skill_slug = excluded.skill_slug, purpose = excluded.purpose, difficulty = excluded.difficulty, sort = excluded.sort;
insert into public.lessons (id, path_id, slug, title, summary, sort, level, estimated_minutes, content, pass_threshold) values (md5('lesson:tonalidade-e-transposicao')::uuid, (select id from public.learning_paths where slug = 'teoria-aplicada'), 'tonalidade-e-transposicao', 'Tonalidade e transposição', 'Mudar o tom de uma música para servir ao grupo e à congregação.', 4, 3, 20, '{"objetivo":"Entender o que é tonalidade e transpor uma melodia e uma sequência de cifras para outra tonalidade.","gancho":"O louvor ficou alto demais e a igreja parou de cantar no refrão? Transpor resolve: a mesma música, no lugar certo para as vozes.","etapas":[{"titulo":"A mesma música, outra altura","tipo":"descobrir","blocos":[{"type":"p","text":"Tonalidade é o centro da música: a nota e o acorde de repouso (a tônica) e a escala que parte dela. Transpor é cantar ou tocar a mesma música em outra tonalidade."},{"type":"callout","icon":"ideia","title":"Como um elevador","text":"A família inteira sobe junto: todos mudam de andar, mas a distância entre eles continua a mesma. Ao transpor, todos os intervalos se mantêm."},{"type":"compare","prompt":"Ouça o início do Hino da Alegria em dois tons.","options":[{"label":"Em Dó: Mi–Mi–Fá–Sol","notes":["E4","E4","F4","G4"],"tempo":90},{"label":"Em Ré: Fá♯–Fá♯–Sol–Lá","notes":["F#4","F#4","G4","A4"],"tempo":90}],"explain":"A melodia é a mesma, só ficou um tom mais aguda. O desenho de passos (semitom, depois tom) não mudou."}]},{"titulo":"Por que Fá♯, e não Fá?","tipo":"checar","blocos":[{"type":"check","question":"Em Dó, a melodia faz Mi–Mi–Fá–Sol. Transposta um tom acima (para Ré), ela fica…","options":["Fá♯–Fá♯–Sol–Lá","Fá–Fá–Sol–Lá","Ré–Ré–Mi–Fá"],"answer":0,"explain":"Cada nota sobe 2 semitons: Mi → Fá♯, Fá → Sol, Sol → Lá. Com Fá natural, o primeiro passo viraria um tom e a melodia mudaria."},{"type":"keyboard","from":"C4","to":"C5","highlight":["F#4","G4","A4"],"label":"Em Ré: Fá♯, Sol, Lá"}]},{"titulo":"Conte os semitons","tipo":"descobrir","blocos":[{"type":"list","ordered":true,"items":["Decida quantos semitons subir ou descer (de Dó para Ré = +2).","Some esse valor a todas as notas e às fundamentais dos acordes.","Mantenha o tipo de cada acorde: Am em Dó vira Bm em Ré.","Confira a nota mais aguda e a mais grave de cada voz."]},{"type":"check","question":"De Dó maior para Mi♭ maior, quantos semitons?","options":["+3","+2","+4","−3"],"answer":0,"explain":"Dó → Dó♯ → Ré → Mi♭: três teclas vizinhas, +3 semitons."}]},{"titulo":"Sua vez: transponha a cifra","tipo":"experimentar","blocos":[{"type":"illustration","name":"cifra","caption":"Na cifra, muda a letra; o tipo do acorde fica."},{"type":"reveal","prompt":"Transponha C – F – G – C para Ré (+2).","answer":"D – G – A – D."},{"type":"reveal","prompt":"Transponha Am – Dm – E – Am para Si menor (+2).","answer":"Bm – Em – F♯ – Bm. O E é maior e continua maior: F♯."}]},{"titulo":"Ouça: o tipo não muda","tipo":"ouvir","blocos":[{"type":"compare","prompt":"A mesma progressão em Lá menor e em Si menor.","options":[{"label":"Am – Dm – E – Am","notes":[["A3","C4","E4"],["A3","D4","F4"],["G#3","B3","E4"],["A3","C4","E4"]],"tempo":60},{"label":"Bm – Em – F♯ – Bm","notes":[["B3","D4","F#4"],["B3","E4","G4"],["A#3","C#4","F#4"],["B3","D4","F#4"]],"tempo":60}],"explain":"O caráter é idêntico: menor, menor, maior, menor. Só a altura subiu um tom."},{"type":"trueFalse","items":[{"statement":"Am transposto um tom acima vira Bm.","answer":true,"explain":"Lá + 2 semitons = Si, e o acorde continua menor."},{"statement":"Ao transpor, um acorde com sétima pode perder a sétima.","answer":false,"explain":"Nada muda além da altura: com sétima continua com sétima."}]}]},{"titulo":"O tom que serve à igreja","tipo":"aplicar","blocos":[{"type":"illustration","name":"extensao-tessitura"},{"type":"p","text":"Se a melodia passa de Ré5, sopranos e congregação se cansam. Se desce abaixo de Lá3, perde força. Mudar um ou dois semitons pode transformar a participação da igreja."},{"type":"check","question":"Um louvor está em Mi maior e o refrão chega a Mi5. A igreja para de cantar ali. O que fazer?","options":["Descer para Ré maior (−2): o agudo vira Ré5","Subir para Fá maior para dar mais brilho","Manter o tom e pedir mais volume"],"answer":0,"explain":"Descendo um tom, tudo desce 2 semitons: Mi5 vira Ré5, uma região confortável para a maioria."},{"type":"harmonyLink","arrangement":"hino-alegria-satb","label":"No treinador, transponha o SATB em +2 e veja a nota mais aguda do soprano"}]},{"titulo":"Juntando tudo","tipo":"checar","blocos":[{"type":"order","prompt":"Coloque os passos da transposição na ordem.","items":["Escolher o novo tom e contar os semitons","Somar esse valor a todas as notas e cifras","Conferir que cada acorde manteve o tipo","Verificar o agudo e o grave de cada voz"]}]}],"pratiqueSozinho":{"passos":["Escolha um hino e descubra a nota mais aguda e a mais grave da melodia.","Proponha uma tonalidade confortável para o seu grupo."],"minutos":10,"frequencia":"1 vez por semana"},"errosComuns":[{"erro":"Mudar o tipo do acorde ao transpor.","correcao":"Menor continua menor; com sétima continua com sétima."}],"seguranca":["Alterne teoria e prática: depois de cada conceito, toque e cante o exemplo."],"criterioAvanco":"Acertar pelo menos 70% na avaliação."}'::jsonb, 0.70) on conflict (slug) do update set path_id = excluded.path_id, title = excluded.title, summary = excluded.summary, sort = excluded.sort, level = excluded.level, estimated_minutes = excluded.estimated_minutes, content = excluded.content, pass_threshold = excluded.pass_threshold;
insert into public.lesson_skills (lesson_id, skill_slug) select id, 'teoria-escalas' from public.lessons where slug = 'tonalidade-e-transposicao' on conflict do nothing;
